            if (_aff >= 60) _rel.discovered.presenceBonus.push(60);
            if (_aff >= 80) _rel.discovered.presenceBonus.push(80);
            if (_aff >= 30) _rel.discovered.affinityRewards.push(30);
            if (_aff >= 60) _rel.discovered.affinityRewards.push(60);
