function getDreamBonusText(dream) {
  return dream && dream.bonus && dream.bonus.text ? dream.bonus.text : "";
}

function getCurrentDreamBonus(state) {
  var dream = getCurrentDream(state);
  return dream && dream.bonus ? dream.bonus : null;
}

function getDreamSkillXpMultiplier(state, skillKey) {
  var bonus = getCurrentDreamBonus(state);
  if (!bonus || !bonus.skillXp) return 1;
  return bonus.skillXp[skillKey] || 1;
}

function applyDreamIncomeBonus(state, amount, source) {
  var bonus = getCurrentDreamBonus(state);
  var mul = bonus && bonus.income ? bonus.income[source] || 1 : 1;
  return Math.max(0, Math.floor((amount || 0) * mul));
}

function getDreamBankRateMultiplier(state) {
  var bonus = getCurrentDreamBonus(state);
  return bonus && bonus.bankRate ? bonus.bankRate : 1;
}

/** 推荐选择人生目标弹窗（可跳过；选择目标有加成）*/
function showForcedDreamModal() {
  if (typeof showDreamSelectModal === "function") {
    if (typeof DREAMS === "undefined") return;
    var st =
      typeof StateManager !== "undefined" && StateManager.getState
        ? StateManager.getState()
        : null;
    if (st && st.flags && (st.flags._dreamId || st.flags._dreamSkipped)) return;
    var optHtml = DREAMS.map(function (d) {
      return (
        "<div onclick=\"window.selectDream('" +
        d.id +
        '\')" style="padding:10px 14px;margin:4px 0;background:var(--bg-card);border:1px solid var(--border);border-radius:6px;cursor:pointer;transition:all 0.2s;" ' +
        "onmouseover=\"this.style.borderColor='var(--accent)';this.style.background='var(--bg-card-hover)';this.style.transform='translateY(-1px)';this.style.boxShadow='0 4px 12px var(--accent-glow)';\" onmouseout=\"this.style.borderColor='var(--border)';this.style.background='var(--bg-card)';this.style.transform='none';this.style.boxShadow='none';\"> " +
        "<strong>" +
        d.icon +
        " " +
        d.name +
        "</strong>" +
        '<div style="font-size:11px;color:var(--text-secondary);margin-top:4px;">' +
        d.desc +
        "</div>" +
        '<div style="font-size:11px;color:var(--accent);margin-top:4px;">加成：' +
        getDreamBonusText(d) +
        "</div>" +
        "</div>"
      );
    }).join("");
    showModal({
      title: "🌟 确立人生目标",
      body:
        '<p style="font-size:13px;color:var(--text-primary);margin-bottom:12px;font-weight:600;">在这座城市，你想要什么？目标不是必选项，但选定方向会给你路线加成和里程碑故事。</p>' +
        '<p style="font-size:12px;color:var(--text-secondary);margin-bottom:12px;">不确定也可以先跳过，之后在“个人成长”里重新设定。</p>' +
        optHtml,
      buttons: [
        {
          text: "暂时不选，自由开局",
          cls: "",
          callback: function () {
            if (typeof skipDreamForNow === "function") skipDreamForNow();
          },
        },
      ],
    });
  }
}

/** 获取当前梦想定义 */
function getCurrentDream(state) {
  var id = state.flags && state.flags._dreamId;
  if (!id) return null;
  return (
    DREAMS.find(function (d) {
      return d.id === id;
    }) || null
  );
}

/** 每日检查梦想里程碑进度 */
function checkDreamProgress(state) {
  var dream = getCurrentDream(state);
  if (!dream) return;

  var currentMilestone = state.flags._dreamMilestone || 0;
  if (currentMilestone >= dream.milestones.length) return; // 已全部完成

  var milestone = dream.milestones[currentMilestone];
  if (!milestone) return;

  // 检查条件
  if (milestone.condition(state)) {
    state.flags._dreamMilestone = currentMilestone + 1;
    // 防重复触发
    var flagKey = "_dreamMilestoneShown_" + milestone.id;
    if (!state.flags[flagKey]) {
      state.flags[flagKey] = true;
      StateManager.addMessage(
        dream.icon +
          " 【梦想里程碑：" +
          milestone.title +
          "】\n" +
          milestone.story,
        "event",
      );
    }
  }
}

/** 获取梦想进度百分比 */
function getDreamProgress(state) {
  var dream = getCurrentDream(state);
  if (!dream) return 0;
  var done = state.flags._dreamMilestone || 0;
  return Math.min(100, Math.round((done / dream.milestones.length) * 100));
}

/** 获取当前里程碑标题（用于UI显示） */
function getDreamCurrentTitle(state) {
  var dream = getCurrentDream(state);
  if (!dream) return "";
  var idx = state.flags._dreamMilestone || 0;
  if (idx >= dream.milestones.length) return "圆梦！ 🎉";
  return dream.milestones[idx].title;
}

