          if (st.resources.cash < 500) {
            StateManager.addMessage("🔧 钱不够，只能看着别人买走。", "warning");
            return;
          }
          st.resources.cash -= 500;
          st.skills.repair.xp = (st.skills.repair.xp || 0) + 40;
          // 恢复一件装备的耐久
