        if (!isInvestorE(st)) return false;
        // 至少一个已结识NPC（好感≥15）
        var rels = st.relationships || {};
        for (var id in rels) {
          if (rels[id] && rels[id].met && (rels[id].affinity || 0) >= 15)
            return true;
        }
