/**
 * 创业专属事件系统 — 30+ 随机事件
 *
 * 按阶段分类：种子期 / 成长期 / 成熟期
 * 按行业分类：科技 / 消费 / 金融科技 / 医疗健康 / 教育 / 制造
 * 按类型分类：机遇 / 危机 / 人际 / 政策 / 市场
 */

// ====== 工具函数 ======

/** 转义 HTML 特殊字符 */
function _esc(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

