function getBrandLevel(reputation) {
  for (let i = BRAND_LEVELS.length - 1; i >= 0; i--) {
    if (reputation >= BRAND_LEVELS[i].minReputation) {
      return BRAND_LEVELS[i];
    }
  }
  return BRAND_LEVELS[0];
}

