// ====== 查询/工具函数 ======

/** 获取自住房所在地点 key（无自住房则返回 null）—— 旧接口，兼容保留 */
function getSelfLiveLocKey(state) {
  if (!state || !state.investment) return null;
  var pid = state.investment.selfLivePropertyId;
  if (pid == null) return null;
  var props = state.investment.properties || [];
  for (var i = 0; i < props.length; i++) {
    if (props[i].id === pid || props[i].instanceId === pid) {
      return props[i].loc || null;
    }
  }
  return null;
}

/**
 * 获取玩家住所所在地点 key（租房/自住统一）
 * - tier 0 → null（无家可归）
 * - 自住房存了 loc 字段 → 该地点
 * - 其他 → "slum"（城中村，默认住所区域）
 */
function getHomeLocationKey(state) {
  if (!state || !state.housing) return null;
  var tier = state.housing.tier || 0;
  if (tier <= 0) return null;

  // 自住房优先
  var selfLoc = getSelfLiveLocKey(state);
  if (selfLoc) return selfLoc;

  // 默认住所位置
  return "slum";
}

/**
 * 获取玩家可用的家居设施（按住所等级过滤）
 * @returns {Array} 可用的家居 amenity 列表
 */
function getHomeAmenities(state) {
  if (!state || !state.housing) return [];
  var tier = state.housing.tier || 0;
  var house =
    (typeof HOUSING_TIERS !== "undefined" && HOUSING_TIERS[tier]) || null;
  if (!house) return [];

  var result = [];
  for (var i = 0; i < AMENITIES.length; i++) {
    var a = AMENITIES[i];
    if (!a.homeOnly) continue;
    if (a.loc !== "*selfLive") continue;
    // 按 tier 能力过滤
    if (a.type === "food" && !house.canCook) continue;
    if (a.type === "bath" && !house.canBathe) continue;
    if (a.type === "rest" && !house.canRest) continue;
    // 休息总是可用，不用过滤
    result.push(a);
  }
  return result;
}

/** 获取在指定地点可用的 amenities（按 type 过滤可选） */
function getAmenitiesAtLoc(locKey, type) {
  var state = null;
  try {
    state = StateManager && StateManager.getState && StateManager.getState();
  } catch (e) {
    state = null;
  }
  var selfLoc = state ? getSelfLiveLocKey(state) : null;
  var result = [];
  for (var i = 0; i < AMENITIES.length; i++) {
    var a = AMENITIES[i];
    var matchLoc =
      a.loc === locKey || (a.loc === "*selfLive" && selfLoc === locKey);
    if (!matchLoc) continue;
    if (type && a.type !== type) continue;
    result.push(a);
  }
  return result;
}

/** 获取所有地点中能提供 type 的 amenities，按距离当前位置排序（最近优先） */
function getNearestAmenitiesByType(state, type, limit) {
  limit = limit || 3;
  var curLoc = (state && state.trade && state.trade.currentLocation) || "slum";
  var selfLoc = getSelfLiveLocKey(state);
  var homeLoc = getHomeLocationKey(state);

  // 收集所有候选 + 计算距离
  var candidates = [];
  for (var i = 0; i < AMENITIES.length; i++) {
    var a = AMENITIES[i];
    if (a.type !== type) continue;
    var actualLoc = a.loc === "*selfLive" ? selfLoc || homeLoc : a.loc;
    if (!actualLoc) continue;
    var hops =
      typeof getLocationHops === "function"
        ? getLocationHops(curLoc, actualLoc)
        : actualLoc === curLoc
          ? 0
          : 99;
    candidates.push({ amenity: a, actualLoc: actualLoc, hops: hops });
  }

  // 按 hops 升序，同距离再按 tier 降序（同距离优先选好的）
  candidates.sort(function (a, b) {
    if (a.hops !== b.hops) return a.hops - b.hops;
    return (b.amenity.tier || 0) - (a.amenity.tier || 0);
  });

  return candidates.slice(0, limit);
}

/** 获取 amenity 数据（按 id） */
function getAmenityById(id) {
  for (var i = 0; i < AMENITIES.length; i++) {
    if (AMENITIES[i].id === id) return AMENITIES[i];
  }
  return null;
}

/** 类型 → 中文标签 */
function getAmenityTypeName(type) {
  return (
    {
      food: "饥饱",
      bath: "卫生",
      fun: "心情",
      rest: "疲劳",
    }[type] || type
  );
}

/** 类型 → 图标 */
function getAmenityTypeIcon(type) {
  return (
    {
      food: "🍚",
      bath: "🛁",
      fun: "🎭",
      rest: "🛏️",
    }[type] || "✨"
  );
}

;
// ==== js/data/illnesses.js ====
/**
 * Illnesses — 命名疾病数据库
 *
 * 设计原则：
 *   1. 每种病有明确触发条件（习惯阈值），避免随机暴击。
 *   2. 症状以"持续 debuff"为主，让玩家持续感到"哎我得病了"。
 *   3. 治疗有两档：药店（便宜慢）/ 医院（贵快）；少数严重病只能去医院。
 *   4. 部分病可由其它病演化而来（反复肠胃炎 → 胃溃疡）。
 *
 * triggerHabit 字段（state.flags._habits 计数器名）:
 *   - junkFoodMeals       : 累计垃圾食品次数
 *   - lowHungerStreak     : 连续饥饱<25 天数
 *   - lowHygieneStreak    : 连续卫生<30 天数
 *   - lowHappinessStreak  : 连续心情<20 天数
 *   - highFatigueStreak   : 连续疲劳>80 天数
 *   - lateNightActions    : 累计夜间娱乐次数
 *   - stomach_inflammationCount : 已得过几次肠胃炎
 *
 * symptom 字段（applyStatusInteractions 中累加）:
 *   - health              : 每日健康变化（负=持续掉血）
 *   - hunger / fatigue / happiness / hygiene : 每日 needs 额外变化
 *   - physiqueDebuff / mentalDebuff / agilityDebuff / intelligenceDebuff : 有效属性扣减
 *   - apMult              : AP 消耗倍率额外加成
 *   - fatigueRecoveryMult : 睡眠疲劳恢复倍率（<1=恢复打折）
 *
 * treatCost 字段:
 *   - pharmacy : 药店治疗费用（None = 不可药店）
 *   - hospital : 医院治疗费用
 *   - hospital_monthly : 慢性病按月治疗（持续付费才不发作）
 */

