// ==== js/phase1/trade.js ====
﻿/**
 * 交易系统 — 买卖商品、价格波动、批发进货
 *
 * 提供: buyGood(), sellGood(), buyWholesale(), updatePrices()
 */

/** 玩家购买商品 */
function buyGood(goodId, qty) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域A A类#8: state.trade 守卫
  if (!state || !state.trade) {
    StateManager.addMessage("⚠️ 交易系统未就绪。", "warning");
    return false;
  }
  if (typeof qty !== "number" || !isFinite(qty) || qty <= 0) {
    StateManager.addMessage("⚠️ 无效的购买数量。", "danger");
    return false;
  }
  const good = getGoodById(goodId);
  if (!good) {
    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
    return false;
  }

  const locKey = state.trade.currentLocation;
  const price = getCurrentPrice(locKey, goodId);

  // 销售技能折扣（统一使用 pricing.js 函数，最高30% @Lv.100）
  const buyDiscount =
    typeof getSkillBuyDiscount === "function"
      ? 1 - getSkillBuyDiscount(state)
      : Math.min(0.18, (state.skills && state.skills.sales && state.skills.sales.level || 0) * 0.003);
  var salesDiscount = buyDiscount;
  // 历史声誉折扣（P2.9：诚信经营者/拒绝假货获得进货优惠）
  var histDiscount = 0;
  if (typeof getHistoryModifiers === "function") {
    var hm = getHistoryModifiers(state);
    histDiscount = hm.priceDiscount < 1.0 ? 1.0 - hm.priceDiscount : 0;
  }
  // 批量折扣：买5件以上额外2%，买10件以上额外5%
  var bulkDiscount = 0;
  if (typeof qty === "number" && qty >= 10) bulkDiscount = 0.05;
  else if (typeof qty === "number" && qty >= 5) bulkDiscount = 0.02;
  const discount = Math.min(0.3, salesDiscount + histDiscount + bulkDiscount);
  const totalCost = Math.round(price * qty * (1 - discount) * 100) / 100;

  // 检查现金
  if (state.resources.cash < totalCost) {
    StateManager.addMessage(
      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}，你只有 ¥${state.resources.cash}。`,
      "danger",
    );
    return false;
  }

  // 检查背包容量
  const currentItems = state.inventory.items.reduce(
    (sum, item) => sum + item.qty,
    0,
  );
  if (currentItems + qty > state.inventory.capacity) {
    StateManager.addMessage(
      `⚠️ 仓库空间不足！（${currentItems}/${state.inventory.capacity} 槽位）`,
      "danger",
    );
    return false;
  }

  // 扣钱
  state.resources.cash -= totalCost;

  // 加入背包
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (existing) {
    existing.qty += qty;
    existing.boughtAt = locKey;
    existing.boughtDay = state.player.day;
  } else {
    state.inventory.items.push({
      id: goodId,
      qty,
      boughtAt: locKey,
      boughtDay: state.player.day,
    });
  }

  // 买入后该商品在当地微涨 0.2~0.5%
  const buyDelta = Random.float(0.002, 0.005);
  adjustPriceAfterTrade(locKey, goodId, buyDelta);
  const newPrice = getCurrentPrice(locKey, goodId);

  // 交易获得销售经验
  if (typeof gainTradeXp === "function") {
    gainTradeXp(state);
  }

  StateManager.addMessage(
    `🛒 购买了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalCost.toFixed(1)}。${newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : ""}`,
    "success",
  );
  if (typeof playSound === "function") playSound("buy");

  // === v3.23: 触发槽 — after_trade ===
  if (typeof window.TriggerRegistry !== "undefined") {
    try {
      var afterTradeEventBuy = window.TriggerRegistry.triggerRandom(
        "after_trade",
        state,
      );
      if (afterTradeEventBuy) {
        setTimeout(function () {
          if (typeof showEventModal === "function")
            showEventModal(afterTradeEventBuy);
        }, 100);
      }
    } catch (e) {
      console.warn("TriggerRegistry after_trade 触发失败:", e);
    }
  }

  // 剁手节进货成就追踪
  if (typeof getCurrentFestival === "function") {
    var fest = getCurrentFestival(state.player.day);
    if (fest && fest.id === "shopping_festival") {
      state.flags._shoppingFestTotalStockup =
        (state.flags._shoppingFestTotalStockup || 0) + totalCost;
    }
  }

  return true;
}

/** 玩家卖出商品 */
function sellGood(goodId, qty) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域A A类#9: state.trade 守卫
  if (!state || !state.trade) {
    StateManager.addMessage("⚠️ 交易系统未就绪。", "warning");
    return false;
  }
  if (typeof qty !== "number" || !isFinite(qty) || qty <= 0) {
    StateManager.addMessage("⚠️ 无效的卖出数量。", "danger");
    return false;
  }
  const good = getGoodById(goodId);
  if (!good) {
    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
    return false;
  }

  // 检查背包
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (!existing || existing.qty < qty) {
    StateManager.addMessage(`⚠️ 背包中没有足够的${good.name}！`, "danger");
    return false;
  }

  const locKey = state.trade.currentLocation;
  let price = getCurrentPrice(locKey, goodId);

  // 同地转卖惩罚：如果卖出地点就是购买地点，售价打2折（现实：原地倒卖几乎必亏）
  let sameLocationPenalty = false;
  if (existing.boughtAt === locKey) {
    price = Math.round(price * 0.2 * 100) / 100;
    sameLocationPenalty = true;
  }

  // 销售技能溢价（统一使用 pricing.js 函数，最高30% @Lv.100）
  const premium =
    typeof getSkillSellBonus === "function"
      ? getSkillSellBonus(state) - 1
      : Math.min(0.2, (state.skills && state.skills.sales && state.skills.sales.level || 0) * 0.003);
  // 交易税5%（市场手续费，透明收取）
  const TAX = 0.05;
  const totalEarned =
    Math.round(price * qty * (1 + premium) * (1 - TAX) * 100) / 100;

  // 加钱
  state.resources.cash += totalEarned;
  state.resources.totalEarned += totalEarned;
  addDailyTransaction(
    state,
    "income",
    "trade_profit",
    totalEarned,
    "卖出" + good.name + "×" + qty,
  );
  // 追踪累计交易利润
  const avgBuy = getAvgBuyPrice(state, goodId);
  if (avgBuy > 0) {
    const unitProfit = totalEarned / qty - avgBuy;
    if (unitProfit > 0) {
      state.trade.totalProfit =
        (state.trade.totalProfit || 0) + unitProfit * qty;
      state.flags._firstTradeDone = true; // 成就：第一次倒买倒卖
    }
  }

  // 从背包移除
  existing.qty -= qty;
  if (existing.qty <= 0) {
    state.inventory.items = state.inventory.items.filter(
      (i) => i.id !== goodId,
    );
  }

  // 低买高卖时显示利润
  const buyPrice = getAvgBuyPrice(state, goodId);
  let profitMsg = "";
  if (sameLocationPenalty) {
    profitMsg = " ⚠️ 同地转卖，贬值严重！";
  } else if (buyPrice > 0) {
    const profit = totalEarned - buyPrice * qty;
    if (profit > 0) {
      profitMsg = ` 📈 获利 ¥${profit.toFixed(1)}！`;
    } else if (profit < 0) {
      profitMsg = ` 📉 亏损 ¥${Math.abs(profit).toFixed(1)}。`;
    }
  }

  // 卖出后该商品在当地微降 0.2~0.5%
  const sellDelta = -Random.float(0.002, 0.005);
  adjustPriceAfterTrade(locKey, goodId, sellDelta);
  const newPrice = getCurrentPrice(locKey, goodId);

  // 交易获得销售经验
  if (typeof gainTradeXp === "function") {
    gainTradeXp(state);
  }

  const priceMsg =
    newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : "";

  StateManager.addMessage(
    `💰 卖出 ${qty}${good.unit}${good.name}，市场价 ¥${price.toFixed(1)}，扣5%交易税后实收 ¥${totalEarned.toFixed(1)}。${profitMsg}${priceMsg}`,
    "success",
  );
  if (typeof playSound === "function") playSound("sell");

  // === v3.23: 触发槽 — after_trade ===
  if (typeof window.TriggerRegistry !== "undefined") {
    try {
      var afterTradeEventSell = window.TriggerRegistry.triggerRandom(
        "after_trade",
        state,
      );
      if (afterTradeEventSell) {
        setTimeout(function () {
          if (typeof showEventModal === "function")
            showEventModal(afterTradeEventSell);
        }, 100);
      }
    } catch (e) {
      console.warn("TriggerRegistry after_trade 触发失败:", e);
    }
  }

  // 剁手节利润成就追踪
  if (typeof getCurrentFestival === "function") {
    var fest2 = getCurrentFestival(state.player.day);
    if (fest2 && fest2.id === "shopping_festival") {
      state.flags._shoppingFestTotalProfit =
        (state.flags._shoppingFestTotalProfit || 0) + totalEarned;
    }
  }

  return true;
}

/** 批发进货（批发市场专属） */
function buyWholesale(goodId, qty) {
  const state = StateManager.getState();
  if (typeof qty !== "number" || !isFinite(qty) || qty <= 0) {
    StateManager.addMessage("⚠️ 无效的批发数量。", "danger");
    return false;
  }
  const good = getGoodById(goodId);
  if (!good) {
    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
    return false;
  }

  const locKey = state.trade.currentLocation;
  const price = getCurrentPrice(locKey, goodId);

  // 批发折扣：批发市场的价格 × 0.95（批量价，5%折扣）
  const wholesalePrice = Math.round(price * 0.95 * 100) / 100;
  const totalCost = Math.round(wholesalePrice * qty * 100) / 100;

  // 最低起批量
  if (qty < 5) {
    StateManager.addMessage("⚠️ 批发最少购买5件。", "warning");
    return false;
  }

  // 检查现金
  if (state.resources.cash < totalCost) {
    StateManager.addMessage(
      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}。`,
      "danger",
    );
    return false;
  }

  // 检查背包
  const currentItems = state.inventory.items.reduce(
    (sum, item) => sum + item.qty,
    0,
  );
  if (currentItems + qty > state.inventory.capacity) {
    StateManager.addMessage(
      `⚠️ 仓库空间不足！（${currentItems}/${state.inventory.capacity} 槽位）`,
      "danger",
    );
    return false;
  }

  // 扣钱
  state.resources.cash -= totalCost;

  // 记录买入价（用于后续利润计算）
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (existing) {
    // 加权平均买入价
    const oldTotal = (existing.avgBuyPrice || wholesalePrice) * existing.qty;
    const newTotal = wholesalePrice * qty;
    existing.qty += qty;
    existing.boughtAt = locKey;
    existing.boughtDay = state.player.day;
    existing.avgBuyPrice =
      Math.round(((oldTotal + newTotal) / existing.qty) * 100) / 100;
  } else {
    state.inventory.items.push({
      id: goodId,
      qty,
      avgBuyPrice: wholesalePrice,
      boughtAt: locKey,
      boughtDay: state.player.day,
    });
  }

  StateManager.addMessage(
    `📦 批发进货 ${qty}${good.unit}${good.name}，批发价 ¥${wholesalePrice.toFixed(1)}/件，共 ¥${totalCost.toFixed(1)}。`,
    "success",
  );
  if (typeof playSound === "function") playSound("buy");

  // 剁手节进货成就追踪（批发也算）
  if (typeof getCurrentFestival === "function") {
    var fest3 = getCurrentFestival(state.player.day);
    if (fest3 && fest3.id === "shopping_festival") {
      state.flags._shoppingFestTotalStockup =
        (state.flags._shoppingFestTotalStockup || 0) + totalCost;
    }
  }

  return true;
}

/** 快速出售（从背包里选一个商品卖） */
function quickSell(goodId) {
  const state = StateManager.getState();
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (!existing || existing.qty <= 0) {
    StateManager.addMessage(`⚠️ 背包中没有该商品。`, "warning");
    return false;
  }
  const qty = Math.min(existing.qty, 1); // 默认卖1个
  return sellGood(goodId, qty);
}

/** 交易后动态调价：买入涨价，卖出降价 */
function adjustPriceAfterTrade(locKey, goodId, delta) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域A A类#10: state.trade 守卫
  if (!state || !state.trade) return;
  const good = getGoodById(goodId);
  if (!good) return;
  const prices = state.trade.goodsPrices[locKey];
  if (!prices) return;
  const oldPrice = prices[goodId] || good.basePrice;
  const change = oldPrice * delta;
  let newPrice = oldPrice + change;
  newPrice = Math.max(
    good.basePrice * 0.65,
    Math.min(good.basePrice * 1.5, newPrice),
  );
  newPrice = Math.round(newPrice * 100) / 100;
  prices[goodId] = newPrice;
}

/** 获取当前地点某商品的零售价（含节日价格修正） */
function getCurrentPrice(locKey, goodId) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域A A类#11: state.trade 守卫
  if (!state || !state.trade || !state.trade.goodsPrices) return 1;
  const prices = state.trade.goodsPrices[locKey];
  let price;
  if (prices && prices[goodId] !== undefined) {
    price = prices[goodId];
  } else {
    const good = getGoodById(goodId);
    price = good ? good.basePrice : 1;
  }
  // 节日价格修正
  if (typeof getFestivalPriceMod === "function") {
    const good = getGoodById(goodId);
    if (good && good.category) {
      const mod = getFestivalPriceMod(state, good.category);
      if (mod !== 1.0) price = Math.round(price * mod * 10) / 10;
    }
  }
  return price;
}

/** 获取某商品在所有地点的最低价格（用于价格对比） */
function getLowestPrice(goodId) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域A A类#12: state.trade 守卫
  if (!state || !state.trade || !state.trade.goodsPrices) return 0;
  let lowest = Infinity;
  let lowestLoc = null;
  for (const locKey of Object.keys(LOCATIONS)) {
    const prices = state.trade.goodsPrices[locKey] || {};
    const price = prices[goodId];
    if (price && price < lowest) {
      lowest = price;
      lowestLoc = locKey;
    }
  }
  return { price: lowest, location: lowestLoc };
}

/** 获取某商品在所有地点的最高价格 */
function getHighestPrice(goodId) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域A A类#13: state.trade 守卫
  if (!state || !state.trade || !state.trade.goodsPrices) return 0;
  let highest = 0;
  let highestLoc = null;
  for (const locKey of Object.keys(LOCATIONS)) {
    const prices = state.trade.goodsPrices[locKey] || {};
    const price = prices[goodId];
    if (price && price > highest) {
      highest = price;
      highestLoc = locKey;
    }
  }
  return { price: highest, location: highestLoc };
}

/** 估算平均买入价 */
function getAvgBuyPrice(state, goodId) {
  const item = state.inventory.items.find((i) => i.id === goodId);
  return item ? item.avgBuyPrice || 0 : 0;
}

/** 更新所有地点所有商品的价格（每3天调用一次） */
function updateAllPrices(state) {
  // [全系统自洽修复] 域A A类#14: state.trade 守卫
  if (!state || !state.trade) return;
  for (const locKey of Object.keys(LOCATIONS)) {
    const loc = LOCATIONS[locKey];
    // 确保价格对象存在
    if (!state.trade.goodsPrices[locKey]) {
      state.trade.goodsPrices[locKey] = {};
    }
    for (const good of GOODS) {
      let price = good.basePrice;

      // 1. 地点倍率
      if (loc.priceMod && loc.priceMod[good.id]) {
        price *= loc.priceMod[good.id];
      }

      // 2. 随机波动 ±4%（极小差价，倒卖基本不赚钱）
      const fluctuation = Random.float(0.96, 1.04);
      price *= fluctuation;

      // 3. 均值回归（10%向旧价格靠拢）
      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
      price = price + (oldPrice - price) * 0.1;

      // 4. 限制在合理范围（含 priceMod 差异，最终区间 0.7x~1.3x）
      price = Math.max(
        good.basePrice * 0.7,
        Math.min(good.basePrice * 1.3, price),
      );
      price = Math.round(price * 100) / 100;

      state.trade.goodsPrices[locKey][good.id] = price;
    }
  }
  state.trade.lastPriceUpdate = state.player.day;
}

/**
 * 获取某地点今日可交易的商品列表
 * 委托至 trade_intel.js 的 getDailyGoodsForLocation
 * @param {string} locKey - 地点 ID
 * @param {object} state - 游戏状态
 * @returns {Array} 可用商品列表
 */
function getAvailableGoodsAtLocation(locKey, state) {
  if (typeof getDailyGoodsForLocation === "function") {
    return getDailyGoodsForLocation(locKey, state);
  }
  // 降级：如果没有 trade_intel.js，返回全部商品
  return GOODS.slice();
}

;
// ==== js/phase1/trade_intel.js ====
/**
 * 交易情报系统 — 技能驱动的价格信息可见度 + 区域商品概率 + NPC情报
 *
 * 核心原则：
 *   1. 销售技能决定价格信息可见度（技能越高，看到越多）
 *   2. 今日访问过的区域才能对比价格（"记忆"机制，次日清空精确记忆）
 *   3. 前3日保留模糊印象（"偏低/正常/偏高"），不显示精确数字
 *   4. NPC在好感足够时可分享专业领域价格情报
 *   5. 每个区域有特产（必出）+ 随机商品（按概率）+ 日常（必出）
 *
 * 依赖: locations.js, goods.js, npcs.js, state.js
 * 在 index.html 中位于 trade.js 之后加载
 */

// ====== 销售技能等级门槛 ======
var SALES_SKILL_THRESHOLDS = {
  LOCAL_ONLY: 0, // 只能看当前地点价格
  CAN_COMPARE: 20, // 可以对比已访问区域（红/绿）
  CAN_SEE_VISITED_EXTREMES: 40, // 可以看到"已访问区域中"最低/最高
  CAN_SEE_CITY_EXTREMES: 60, // 可以看到全城最低/最高（需今日跑完全城）
  CAN_PREDICT_TREND: 80, // 可以看到下个周期价格走势箭头
};

// ====== 模糊记忆等级（前几日） ======
var PRICE_TIER_LABELS = {
  low: "偏低",
  mid: "正常",
  high: "偏高",
};

/** 前3日模糊记忆保留天数 */
var MEMORY_RETENTION_DAYS = 3;

/**
 * 获取某商品的模糊价格区间
 * @param {number} price - [current price
 * @param {number} basePrice - base price of the good
 * @returns {"low"|"mid"|"high"} 模糊等级
 */
function getPriceTier(price, basePrice) {
  var ratio = price / basePrice;
  if (ratio < 0.85) return "low";
  if (ratio > 1.15) return "high";
  return "mid";
}

/**
 * 记录玩家访问某个区域（今日价格快照）
 * 调用时机：玩家进入某地点并打开交易页时
 * @param {object} state - 游戏状态
 * @param {string} locKey - 地点 ID
 */
function recordLocationVisit(state, locKey) {
  var today = state.player && state.player.day ? state.player.day : 1;
  var visited = state.trade.visitedToday || {};

  // 如果今天是新的一天，重置 visitedToday（保留 visitedTodayPrices）
  if (state.trade._visitedDay !== today) {
    // 将昨日 visitedToday 转入模糊记忆
    archiveYesterdayMemory(state);
    state.trade.visitedToday = {};
    state.trade._visitedDay = today;
    visited = {};
  }

  // 如果该地点今日已访问过，不重复记录
  if (visited[locKey]) return;

  // 快照当前价格
  var prices = state.trade.goodsPrices[locKey] || {};
  var snapshot = {};
  for (var gid in prices) {
    if (prices.hasOwnProperty(gid)) {
      snapshot[gid] = prices[gid];
    }
  }
  visited[locKey] = {
    visitDay: today,
    prices: snapshot,
  };
  state.trade.visitedToday = visited;
  state.trade._visitedDay = today;
}

/**
 * 将昨日精确记忆归档为模糊记忆（滚动保留3天）
 */
function archiveYesterdayMemory(state) {
  var yesterday = state.trade._visitedDay;
  if (!yesterday) return;

  var visited = state.trade.visitedToday || {};
  var memory = state.trade.priceMemory || [];

  for (var locKey in visited) {
    if (!visited.hasOwnProperty(locKey)) continue;
    var snap = visited[locKey].prices;
    for (var gid in snap) {
      if (!snap.hasOwnProperty(gid)) continue;
      var price = snap[gid];
      var good = getGoodById(gid);
      if (!good) continue;
      memory.push({
        day: yesterday,
        locKey: locKey,
        goodId: gid,
        tier: getPriceTier(price, good.basePrice),
      });
    }
  }

  // 只保留最近 MEMORY_RETENTION_DAYS 天
  var cutoff = yesterday - MEMORY_RETENTION_DAYS;
  memory = memory.filter(function (m) {
    return m.day >= cutoff;
  });

  state.trade.priceMemory = memory;
}

/**
 * 获取今日已访问的地点列表
 * @param {object} state
 * @returns {string[]} 地点 ID 数组
 */
function getRememberedLocations(state) {
  var visited = state.trade.visitedToday || {};
  return Object.keys(visited);
}

/**
 * 判断销售技能是否达到"可对比已访问区域价格"的门槛
 * 门槛: 销售 >= 20
 * @param {object} state
 * @returns {boolean}
 */
function canSeePriceMarkers(state) {
  var salesLvl =
    (state.skills && state.skills.sales && state.skills.sales.level) || 0;
  return salesLvl >= SALES_SKILL_THRESHOLDS.CAN_COMPARE;
}

/**
 * 判断销售技能是否达到"可看到已访问区域中最低/最高"的门槛
 * 门槛: 销售 >= 40
 * @param {object} state
 * @returns {boolean}
 */
function canSeeVisitedExtremes(state) {
  var salesLvl =
    (state.skills && state.skills.sales && state.skills.sales.level) || 0;
  return salesLvl >= SALES_SKILL_THRESHOLDS.CAN_SEE_VISITED_EXTREMES;
}

/**
 * 判断能否看到全城最低/最高
 * 条件：销售 >= 60 + 今日已跑完全城所有地点
 * @param {object} state
 * @returns {boolean}
 */
function canSeeCityExtremes(state) {
  var salesLvl =
    (state.skills && state.skills.sales && state.skills.sales.level) || 0;
  if (salesLvl < SALES_SKILL_THRESHOLDS.CAN_SEE_CITY_EXTREMES) return false;

  var visited = getRememberedLocations(state);
  var allLocs = Object.keys(LOCATIONS);
  // 检查是否所有地点都访问过
  for (var i = 0; i < allLocs.length; i++) {
    if (visited.indexOf(allLocs[i]) === -1) return false;
  }
  return true;
}

/**
 * 判断能否看到价格趋势箭头（↑↓→）
 * 门槛: 销售 >= 80
 * @param {object} state
 * @returns {boolean}
 */
function canPredictTrend(state) {
  var salesLvl =
    (state.skills && state.skills.sales && state.skills.sales.level) || 0;
  return salesLvl >= SALES_SKILL_THRESHOLDS.CAN_PREDICT_TREND;
}

/**
 * 获取前几日的价格模糊记忆提示
 * @param {object} state
 * @param {string} locKey - 可选，过滤某个地点
 * @returns {string[]} 提示文本数组
 */
function getPriceMemoryHints(state, locKey) {
  var memory = state.trade.priceMemory || [];
  var hints = [];

  // 过滤
  var filtered = locKey
    ? memory.filter(function (m) {
        return m.locKey === locKey;
      })
    : memory;

  // 按天分组去重（同一天同一地点同一商品只保留一条）
  var seen = {};
  filtered = filtered.filter(function (m) {
    var key = m.day + "_" + m.locKey + "_" + m.goodId;
    if (seen[key]) return false;
    seen[key] = true;
    return true;
  });

  for (var i = 0; i < filtered.length; i++) {
    var m = filtered[i];
    var loc = getLocation(m.locKey);
    var good = getGoodById(m.goodId);
    if (!loc || !good) continue;
    var tierLabel = PRICE_TIER_LABELS[m.tier] || "正常";
    var dayDiff = (state.player.day || 1) - m.day;
    var dayStr =
      dayDiff === 0 ? "今天" : dayDiff === 1 ? "昨天" : dayDiff + "天前";
    hints.push(dayStr + loc.name + "的" + good.name + "价格" + tierLabel);
  }

  // 最多返回 5 条
  return hints.slice(0, 5);
}

/**
 * 检查某个商品在当前地点是否需要显示红/绿价格标记
 *
 * 规则：
 *   - 销售 < 20：不显示任何标记
 *   - 销售 >= 20：对比已访问区域，比已访问均价低→绿，高→红
 *
 * @param {object} state
 * @param {string} locKey - 当前地点
 * @param {string} goodId - 商品 ID
 * @param {number} price - 当前价格
 * @returns {{ direction: "up"|"down"|null, label: string }}
 */
function getPriceMarker(state, locKey, goodId, price) {
  var result = { direction: null, label: "" };
  if (!canSeePriceMarkers(state)) return result;

  var visited = state.trade.visitedToday || {};
  var comparePrices = [];

  for (var vLocKey in visited) {
    if (!visited.hasOwnProperty(vLocKey)) continue;
    if (vLocKey === locKey) continue; // 不和自己比
    var snap = visited[vLocKey].prices;
    if (snap && snap[goodId] !== undefined) {
      comparePrices.push(snap[goodId]);
    }
  }

  if (comparePrices.length === 0) return result;

  var avg =
    comparePrices.reduce(function (a, b) {
      return a + b;
    }, 0) / comparePrices.length;

  if (price < avg * 0.98) {
    result.direction = "down";
    result.label = "🟢 低于已访区域均价";
  } else if (price > avg * 1.02) {
    result.direction = "up";
    result.label = "🔴 高于已访区域均价";
  }

  return result;
}

/**
 * 检查某商品在当前地点是否是"已访问区域中的最低/最高"
 * @param {object} state
 * @param {string} locKey - 当前地点
 * @param {string} goodId - 商品 ID
 * @returns {{ isVisitedLowest: boolean, isVisitedHighest: boolean, label: string }}
 */
function getVisitedExtreme(state, locKey, goodId) {
  var result = { isVisitedLowest: false, isVisitedHighest: false, label: "" };
  if (!canSeeVisitedExtremes(state)) return result;

  var visited = state.trade.visitedToday || {};
  var allPrices = [];

  for (var vLocKey in visited) {
    if (!visited.hasOwnProperty(vLocKey)) continue;
    var snap = visited[vLocKey].prices;
    if (snap && snap[goodId] !== undefined) {
      allPrices.push({ loc: vLocKey, price: snap[goodId] });
    }
  }

  if (allPrices.length < 2) return result;

  var currentPrice = 0;
  for (var i = 0; i < allPrices.length; i++) {
    if (allPrices[i].loc === locKey) {
      currentPrice = allPrices[i].price;
      break;
    }
  }
  if (!currentPrice) return result;

  var min = Infinity,
    max = -Infinity;
  for (var j = 0; j < allPrices.length; j++) {
    if (allPrices[j].price < min) min = allPrices[j].price;
    if (allPrices[j].price > max) max = allPrices[j].price;
  }

  if (currentPrice <= min) {
    result.isVisitedLowest = true;
  }
  if (currentPrice >= max) {
    result.isVisitedHighest = true;
  }

  if (result.isVisitedLowest && result.isVisitedHighest) {
    result.label = "🟡 唯一价格（仅访问过1处）";
  } else if (result.isVisitedLowest) {
    result.label = "🟢 已访区域最低";
  } else if (result.isVisitedHighest) {
    result.label = "🔴 已访区域最高";
  }

  return result;
}

/**
 * 检查是否全城最低/全城最高（需销售>=60+跑完全城）
 * @param {object} state
 * @param {string} locKey
 * @param {string} goodId
 * @returns {{ isCityLowest: boolean, isCityHighest: boolean, label: string }}
 */
function getCityExtreme(state, locKey, goodId) {
  var result = { isCityLowest: false, isCityHighest: false, label: "" };
  if (!canSeeCityExtremes(state)) return result;

  var lowest = getLowestPrice(goodId);
  var highest = getHighestPrice(goodId);

  if (lowest.location === locKey) {
    result.isCityLowest = true;
    result.label = "🏆 全城最低！";
  }
  if (highest.location === locKey) {
    result.isCityHighest = true;
    result.label = result.isCityLowest ? "🏆 全城最低！" : "📈 全城最高";
  }

  return result;
}

/**
 * 获取价格趋势预测箭头
 * @param {object} state
 * @param {string} locKey
 * @param {string} goodId
 * @returns {string} "↑" | "↓" | "→" | ""
 */
function getPriceTrend(state, locKey, goodId) {
  if (!canPredictTrend(state)) return "";

  // 基于历史价格趋势判断（看过去3天的模糊记忆）
  var memory = state.trade.priceMemory || [];
  var relevant = memory.filter(function (m) {
    return m.locKey === locKey && m.goodId === goodId;
  });

  if (relevant.length < 2) return "→";

  // 按天排序
  relevant.sort(function (a, b) {
    return a.day - b.day;
  });

  var tiers = relevant.map(function (m) {
    return m.tier;
  });
  var recent = tiers.slice(-3);

  var lowCount = 0,
    highCount = 0;
  for (var i = 0; i < recent.length; i++) {
    if (recent[i] === "low") lowCount++;
    if (recent[i] === "high") highCount++;
  }

  // 连续低价→可能涨
  if (lowCount >= 2) return "↑";
  // 连续高价→可能跌
  if (highCount >= 2) return "↓";
  return "→";
}

// ====== NPC 价格情报系统 ======

/**
 * NPC价格情报专业领域定义
 * 每个NPC可以透露的信息由其职业/背景决定
 */
var NPC_TRADE_INFO = {
  // 王大婶 — 房东，最懂柴米油盐
  aunt_wang: {
    expertise: ["daily", "food"],
    infoTypes: {
      price_level: { label: "日用品价格水平", threshold: 30, cost: 50 },
      category_lowest: { label: "全城日用品哪最便宜", threshold: 60, cost: 20 },
    },
  },
  // 李工头 — 包工头，懂废品/建材
  boss_li: {
    expertise: ["scrap"],
    infoTypes: {
      price_level: { label: "废品行情走势", threshold: 30, cost: 50 },
      good_highest: { label: "哪收废品价最高", threshold: 60, cost: 30 },
    },
  },
  // 张姐 — 中介，消息灵通
  sister_zhang: {
    expertise: ["clothing", "electronics", "luxury"],
    infoTypes: {
      price_level: { label: "商业区价格资讯", threshold: 30, cost: 60 },
      category_highest: { label: "哪卖服装电子最贵", threshold: 60, cost: 30 },
    },
  },
  // 老周 — 收废品老人，废品行家
  old_zhou: {
    expertise: ["scrap"],
    infoTypes: {
      good_highest: { label: "废品全城最高价", threshold: 30, cost: 40 },
      category_lowest: { label: "全城废品回收比价", threshold: 60, cost: 20 },
    },
  },
  // 小美 — 大学生，懂二手/平价商品
  xiao_mei: {
    expertise: ["daily", "food", "clothing"],
    infoTypes: {
      price_level: { label: "平价商品情报", threshold: 30, cost: 30 },
      category_lowest: { label: "哪买东西最便宜", threshold: 60, cost: 10 },
    },
  },
  // 陈师傅 — 大厨，懂食材
  chef_chen: {
    expertise: ["food"],
    infoTypes: {
      price_level: { label: "食材价格行情", threshold: 30, cost: 40 },
      category_lowest: { label: "哪买菜最便宜", threshold: 60, cost: 15 },
    },
  },
};

/**
 * 获取某NPC可提供的交易情报（基于好感度过滤）
 * @param {string} npcId
 * @param {object} state
 * @returns {object|null} { expertise, availableInfo: [...] }
 */
function getNPCTradeInfo(npcId, state) {
  var infoDef = NPC_TRADE_INFO[npcId];
  if (!infoDef) return null;

  var rel = state.relationships && state.relationships[npcId];
  var affinity = rel ? rel.affinity : 0;
  var met = rel ? rel.met : false;
  if (!met) return null;

  var availableInfo = [];
  var types = infoDef.infoTypes;
  for (var typeId in types) {
    if (!types.hasOwnProperty(typeId)) continue;
    var typeDef = types[typeId];
    if (affinity >= typeDef.threshold) {
      availableInfo.push({
        id: typeId,
        label: typeDef.label,
        threshold: typeDef.threshold,
        baseCost: typeDef.cost,
        // 好感越高价格越低
        currentCost: getInfoCost(typeDef.cost, affinity),
        free: affinity >= 80,
      });
    }
  }

  return {
    expertise: infoDef.expertise,
    availableInfo: availableInfo,
  };
}

/**
 * 根据好感度计算情报价格
 * 好感30: 原价
 * 好感30~59: 原价 ~ 6折 线性递减
 * 好感60~79: 6折 ~ 3折 线性递减
 * 好感80+: 免费
 */
function getInfoCost(baseCost, affinity) {
  if (affinity >= 80) return 0;
  if (affinity >= 60) {
    // 60→0.6x, 79→0.3x
    var t = (affinity - 60) / 19;
    return Math.round(baseCost * (0.6 - t * 0.3));
  }
  if (affinity >= 30) {
    // 30→1.0x, 59→0.6x
    var t2 = (affinity - 30) / 29;
    return Math.round(baseCost * (1.0 - t2 * 0.4));
  }
  return baseCost;
}

/**
 * 从NPC购买情报
 * @param {string} npcId
 * @param {string} infoTypeId
 * @param {object} state
 * @returns {{ success: boolean, message: string, info?: string }}
 */
function buyInfoFromNpc(npcId, infoTypeId, state) {
  var npc = getNpcById(npcId);
  if (!npc) return { success: false, message: "⚠️ 找不到该NPC。" };

  var infoData = getNPCTradeInfo(npcId, state);
  if (!infoData) return { success: false, message: "⚠️ 该NPC没有情报可提供。" };

  var foundInfo = null;
  for (var i = 0; i < infoData.availableInfo.length; i++) {
    if (infoData.availableInfo[i].id === infoTypeId) {
      foundInfo = infoData.availableInfo[i];
      break;
    }
  }
  if (!foundInfo) {
    return {
      success: false,
      message: "⚠️ 好感度不够，该NPC还不愿意分享这项情报。",
    };
  }

  var cost = foundInfo.currentCost;
  var rel = state.relationships && state.relationships[npcId];
  if (!rel) return { success: false, message: "⚠️ 还不认识该NPC。" };

  // 好感80+免费
  if (foundInfo.free) {
    rel.affinity = Math.min(100, rel.affinity + 2);
    return {
      success: true,
      message:
        "💬 " +
        npc.name +
        "主动告诉你：" +
        generateInfoText(npcId, infoTypeId, state),
      info: generateInfoText(npcId, infoTypeId, state),
    };
  }

  if (state.resources.cash < cost) {
    return {
      success: false,
      message: "⚠️ 钱不够，需要 ¥" + cost + "。",
    };
  }

  state.resources.cash -= cost;

  // 销售技能微量增长
  if (state.skills && state.skills.sales) {
    state.skills.sales.xp += 5;
  }

  // 好感微量增加
  rel.affinity = Math.min(100, rel.affinity + 1);

  return {
    success: true,
    message:
      "💰 花了 ¥" +
      cost +
      " 从" +
      npc.name +
      "那里打听情报：" +
      generateInfoText(npcId, infoTypeId, state),
    info: generateInfoText(npcId, infoTypeId, state),
  };
}

/**
 * 生成NPC情报的具体内容文本
 */
function generateInfoText(npcId, infoTypeId, state) {
  var infoDef = NPC_TRADE_INFO[npcId];
  if (!infoDef) return "";

  var expertise = infoDef.expertise || [];

  switch (infoTypeId) {
    case "price_level": {
      // 告诉某类商品整体价格水平
      var cat = expertise[0] || "daily";
      var catLabel =
        {
          daily: "日用品",
          food: "食品",
          scrap: "废品",
          clothing: "服装",
          electronics: "电子",
          luxury: "奢侈品",
        }[cat] || cat;
      var locs = Object.keys(state.trade.goodsPrices || {});
      var cheapLocs = [];
      for (var i = 0; i < locs.length; i++) {
        var lk = locs[i];
        var loc = getLocation(lk);
        if (!loc) continue;
        var prices = state.trade.goodsPrices[lk] || {};
        var catGoods = GOODS.filter(function (g) {
          return g.category === cat;
        });
        var total = 0,
          count = 0;
        for (var j = 0; j < catGoods.length; j++) {
          if (prices[catGoods[j].id] !== undefined) {
            total += prices[catGoods[j].id];
            count++;
          }
        }
        if (count > 0) {
          cheapLocs.push({ loc: loc.name, avg: total / count });
        }
      }
      cheapLocs.sort(function (a, b) {
        return a.avg - b.avg;
      });
      if (cheapLocs.length >= 2) {
        return (
          "最近" +
          catLabel +
          "整体行情，" +
          cheapLocs[0].loc +
          "最便宜（均¥" +
          cheapLocs[0].avg.toFixed(1) +
          "），" +
          cheapLocs[cheapLocs.length - 1].loc +
          "最贵（均¥" +
          cheapLocs[cheapLocs.length - 1].avg.toFixed(1) +
          "）。"
        );
      }
      return "最近" + catLabel + "价格还算平稳。";
    }
    case "category_lowest": {
      var cat2 = expertise[0] || "daily";
      var catLabel2 =
        {
          daily: "日用品",
          food: "食品",
          scrap: "废品",
          clothing: "服装",
          electronics: "电子",
          luxury: "奢侈品",
        }[cat2] || cat2;
      var lowest = null;
      var lowestPrice = Infinity;
      for (var lk2 in state.trade.goodsPrices) {
        var prices2 = state.trade.goodsPrices[lk2] || {};
        var catGoods2 = GOODS.filter(function (g) {
          return g.category === cat2;
        });
        for (var k = 0; k < catGoods2.length; k++) {
          var gid = catGoods2[k].id;
          if (prices2[gid] !== undefined && prices2[gid] < lowestPrice) {
            lowestPrice = prices2[gid];
            var locObj = getLocation(lk2);
            lowest = locObj ? locObj.name : lk2;
          }
        }
      }
      if (lowest) {
        return (
          "据我所知，今天" +
          catLabel2 +
          "最便宜的是" +
          lowest +
          "，" +
          catLabel2 +
          "最低价 ¥" +
          lowestPrice.toFixed(1) +
          "！"
        );
      }
      return "今天" + catLabel2 + "的价格我不太确定。";
    }
    case "category_highest": {
      var cat3 = expertise[0] || "clothing";
      var catLabel3 =
        {
          daily: "日用品",
          food: "食品",
          scrap: "废品",
          clothing: "服装",
          electronics: "电子",
          luxury: "奢侈品",
        }[cat3] || cat3;
      var highest = null;
      var highestPrice = 0;
      for (var lk3 in state.trade.goodsPrices) {
        var prices3 = state.trade.goodsPrices[lk3] || {};
        var catGoods3 = GOODS.filter(function (g) {
          return g.category === cat3;
        });
        for (var m = 0; m < catGoods3.length; m++) {
          var gid2 = catGoods3[m].id;
          if (prices3[gid2] !== undefined && prices3[gid2] > highestPrice) {
            highestPrice = prices3[gid2];
            var locObj2 = getLocation(lk3);
            highest = locObj2 ? locObj2.name : lk3;
          }
        }
      }
      if (highest) {
        return (
          "听说今天" +
          catLabel3 +
          "卖价最高的是" +
          highest +
          "，" +
          catLabel3 +
          "最高到 ¥" +
          highestPrice.toFixed(1) +
          "！去那边卖准没错。"
        );
      }
      return "今天" + catLabel3 + "的价格我不太确定。";
    }
    case "good_highest": {
      // 告诉某个具体类目哪收价最高（针对废品：老周/李工头）
      var scrapGoods = GOODS.filter(function (g) {
        return g.category === "scrap";
      });
      if (scrapGoods.length === 0) return "今天废品行情一般。";
      var randomGood = Random.fromArray(scrapGoods);
      var bestLoc = null;
      var bestPrice2 = 0;
      for (var lk4 in state.trade.goodsPrices) {
        var p = (state.trade.goodsPrices[lk4] || {})[randomGood.id];
        if (p && p > bestPrice2) {
          bestPrice2 = p;
          var locObj3 = getLocation(lk4);
          bestLoc = locObj3 ? locObj3.name : lk4;
        }
      }
      if (bestLoc) {
        return (
          randomGood.name +
          "今天" +
          bestLoc +
          "收得最高，¥" +
          bestPrice2.toFixed(1) +
          "/" +
          randomGood.unit +
          "！"
        );
      }
      return "今天废品行情一般，再看看。";
    }
    default:
      return "暂时没什么特别的消息。";
  }
}

/**
 * 尝试触发NPC主动分享情报（每日结算时调用）
 * 条件：好感>=60，且今日玩家在该NPC所在地点交易过
 * @param {string} npcId
 * @param {object} state
 * @returns {string|null} 情报文本，如果没有则返回 null
 */
function tryTriggerNPCInfoShare(npcId, state) {
  var rel = state.relationships && state.relationships[npcId];
  if (!rel || !rel.met) return null;
  if (rel.affinity < 60) return null;

  var npc = getNpcById(npcId);
  if (!npc) return null;

  // 30%概率触发
  if (!Random.chance(0.3)) return null;

  var infoDef = NPC_TRADE_INFO[npcId];
  if (!infoDef) return null;

  var types = Object.keys(infoDef.infoTypes);
  if (types.length === 0) return null;

  // 选一个好感足够的类型
  var availableTypes = [];
  for (var i = 0; i < types.length; i++) {
    var t = infoDef.infoTypes[types[i]];
    if (rel.affinity >= t.threshold) {
      availableTypes.push(types[i]);
    }
  }
  if (availableTypes.length === 0) return null;

  var chosenType = Random.fromArray(availableTypes);
  var infoText = generateInfoText(npcId, chosenType, state);

  // 微量销售XP
  if (state.skills && state.skills.sales) {
    state.skills.sales.xp += 10;
  }

  return infoText;
}

// ====== 区域商品概率系统 ======

/**
 * 获取某个地点今日可交易的商品列表
 *
 * 规则：
 *   1. 日常必需品（水、方便面、零食、日用品）每个区域必有
 *   2. 区域特产（specialties）100%出现
 *   3. 其他商品按 dailyProbability 概率出现
 *   4. 每日刷新（由 state 的 _goodsSeed 决定，每天不同）
 *
 * @param {string} locKey - 地点 ID
 * @param {object} state - 游戏状态
 * @returns {Array} 可用商品列表
 */
function getDailyGoodsForLocation(locKey, state) {
  var loc = getLocation(locKey);
  if (!loc) return [];

  // 批发市场特殊处理：所有商品都可交易
  if (locKey === "wholesaleMarket") {
    return GOODS.slice(); // 返回全部商品
  }

  // 构建天的确定性种子（每天不同，保证当天内一致）
  var day = state.player && state.player.day ? state.player.day : 1;
  var seed = day * 7 + locKey.length * 13 + 3;
  var rng = createSeededRandom(seed);

  // 1. 日常必需品（每个区域必有）
  var dailyEssentials = ["water", "instant_noodles", "snacks", "daily_use"];

  // 2. 区域特产（100%出现）
  var specialties = loc.specialties || [];

  // 3. 其他商品按概率出现
  var dailyProb = loc.dailyProbability || 0.5; // 默认 50%
  var otherGoods = [];

  for (var i = 0; i < GOODS.length; i++) {
    var g = GOODS[i];
    // 跳过必需品和特产
    if (dailyEssentials.indexOf(g.id) !== -1) continue;
    if (specialties.indexOf(g.id) !== -1) continue;

    // 用确定性随机判断
    var goodSeed = seed + g.id.length * 3;
    var prob = rng(); // 0~1
    var threshold = dailyProb;
    // 如果该商品的 category 在 loc.specialCategory 中，提高概率
    if (loc.specialCategory && loc.specialCategory.indexOf(g.category) !== -1) {
      threshold = Math.min(1.0, threshold + 0.3);
    }

    if (prob < threshold) {
      otherGoods.push(g);
    }
  }

  // 合并结果（去重）
  var resultIds = [];
  var resultMap = {};

  // 日常必需品
  for (var d = 0; d < dailyEssentials.length; d++) {
    var gid = dailyEssentials[d];
    if (!resultMap[gid]) {
      resultMap[gid] = true;
      resultIds.push(gid);
    }
  }
  // 特产
  for (var s = 0; s < specialties.length; s++) {
    var sid = specialties[s];
    if (!resultMap[sid]) {
      resultMap[sid] = true;
      resultIds.push(sid);
    }
  }
  // 其他
  for (var o = 0; o < otherGoods.length; o++) {
    var og = otherGoods[o];
    if (!resultMap[og.id]) {
      resultMap[og.id] = true;
      resultIds.push(og.id);
    }
  }

  // 按原始 GOODS 顺序排序
  var orderMap = {};
  for (var idx = 0; idx < GOODS.length; idx++) {
    orderMap[GOODS[idx].id] = idx;
  }
  resultIds.sort(function (a, b) {
    return (orderMap[a] || 999) - (orderMap[b] || 999);
  });

  return resultIds
    .map(function (id) {
      return getGoodById(id);
    })
    .filter(Boolean);
}

/**
 * 创建一个确定性随机数生成器（mulberry32）
 * 用于每日商品刷新，保证同一天内结果一致
 */
function createSeededRandom(seed) {
  var s = seed >>> 0;
  return function () {
    s |= 0;
    s = (s + 0x6d2b79f5) | 0;
    var t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * 检查某商品在当前地点今日是否可交易
 */
function isGoodAvailableToday(locKey, goodId, state) {
  var available = getDailyGoodsForLocation(locKey, state);
  for (var i = 0; i < available.length; i++) {
    if (available[i].id === goodId) return true;
  }
  return false;
}

// ====== 每日交易销售XP增长 ======
var DAILY_TRADE_XP_LIMIT = 30; // 每天通过交易获得的销售XP上限

/**
 * 交易后获得销售经验（买卖双方都调用）
 * @param {object} state
 * @param {number} amount - 交易金额（用于计算，但实际限制每日上限）
 */
function gainTradeXp(state) {
  if (!state.skills || !state.skills.sales) return;
  if (!state.trade) return;

  var todayXp = state.trade._todayTradeXp || 0;
  if (todayXp >= DAILY_TRADE_XP_LIMIT) return;

  var gain = Math.min(5, DAILY_TRADE_XP_LIMIT - todayXp); // 每次2~5, 不超过上限
  state.skills.sales.xp += gain;
  state.trade._todayTradeXp = (state.trade._todayTradeXp || 0) + gain;
}

/**
 * 每日重置交易XP计数器（每天第一次调用时执行）
 */
function resetDailyTradeXp(state) {
  var today = state.player && state.player.day ? state.player.day : 1;
  if (state.trade._xpResetDay !== today) {
    state.trade._todayTradeXp = 0;
    state.trade._xpResetDay = today;
  }
}

// ====== NPCTradeInfo 注册到全局（供Wiki引用） ======
if (typeof window !== "undefined") {
  window.NPC_TRADE_INFO = NPC_TRADE_INFO;
  window.SALES_SKILL_THRESHOLDS = SALES_SKILL_THRESHOLDS;
}

;
// ==== js/phase1/needs.js ====
/**
 * 需求系统 — 饥饱/疲劳/卫生/心情衰减 + 情绪状态判定 + 伤病效果
 */

/** 每日需求衰减 (v3.2 蒙特卡洛平衡：饥饱衰减从18→13，防止开局饿死) */
function applyNeedsDecay(state) {
  const n = state.needs;
  // v3.1: 接入难度乘数 — 休闲档衰减慢，困难/地狱档衰减快
  var decayMul =
    typeof getDifficultyMultiplier === "function"
      ? getDifficultyMultiplier(state, "needsDecay")
      : 1.0;
  // [全系统自洽修复] 域G A类修复: 原 `(x||0)` 仅兜底首参，未覆盖 `Math.round(13*decayMul)` 中间值 NaN（Math.max(0,NaN)=NaN 非 0，需求阈值判定全面失灵）
  if (!isFinite(decayMul) || isNaN(decayMul)) decayMul = 1.0;
  decayMul = Math.max(0.1, Math.min(5.0, decayMul));
  n.hunger = Math.max(
    0,
    Math.min(100, (n.hunger || 0) - Math.round(13 * decayMul)),
  );
  n.hygiene = Math.max(
    0,
    Math.min(100, (n.hygiene || 0) - Math.round(7 * decayMul)),
  );
  n.happiness = Math.max(
    0,
    Math.min(100, (n.happiness || 0) - Math.round(4 * decayMul)),
  );
  // fatigue 在 endDay 中通过睡眠恢复单独处理
}

/** 检查需求阈值并施加惩罚 (v3.2 蒙特卡洛平衡：降低阈值惩罚，前30天减半) */
function checkNeedsThresholds(state) {
  const n = state.needs;
  const msgs = [];
  // v3.2 新手保护：前30天需求惩罚减半
  const dayMul = state.player.day <= 30 ? 0.5 : 1.0;
  // v3.1: 接入难度乘数 — 困难/地狱档惩罚更重
  const diffMul =
    typeof getDifficultyMultiplier === "function"
      ? getDifficultyMultiplier(state, "needsDecay")
      : 1.0;
  const combinedMul = dayMul * diffMul;

  if (n.hunger < 10) {
    const dmg = Math.round(2 * combinedMul);
    state.status.health = Math.max(0, state.status.health - dmg);
    if (n.hunger <= 0) state.flags._everStarved = true; // 成就追踪
    msgs.push("⚠️ 极度饥饿！健康-" + dmg + "。赶紧吃点什么！");
  } else if (n.hunger < 25) {
    const dmg = Math.round(1 * combinedMul);
    state.status.health = Math.max(0, state.status.health - dmg);
    msgs.push("🍞 肚子饿了，工作效率下降。");
  }

  if (n.hygiene < 10) {
    const dmg = Math.round(2 * combinedMul);
    state.status.health = Math.max(0, state.status.health - dmg);
    msgs.push("🦠 卫生极差！容易生病。去洗个澡吧。");
  }

  if (n.fatigue > 90) {
    const dmg = Math.round(2 * combinedMul);
    state.status.health = Math.max(0, state.status.health - dmg);
    msgs.push("😵 极度疲劳！需要休息或睡眠。");
  }

  if (n.happiness < 10) {
    msgs.push("😢 心情极度低落，做什么都提不起劲。");
  }

  for (const msg of msgs) {
    StateManager.addMessage(msg, "warning");
  }
}

/** 伤病每日结算 — 已迁移到 illness.js，遍历 status.illnesses 数组 */
function tickHealthStatus(state) {
  // 新疾病系统：每日 tick illness（自然康复+症状结算+慢性病月费）
  if (typeof tickIllnessDecay === "function") {
    tickIllnessDecay(state);
  }
  var st = state.status;
  // 兼容：旧的 injured 字段（受伤还是单独保留，工作中可能受伤）
  if (st.injured) {
    st.health = Math.max(0, st.health - 2);
    if (Random.chance(0.07)) {
      st.injured = false;
      StateManager.addMessage("🩹 伤好了，可以正常干活了。", "info");
    }
  }
  // v3.2.2 MC长期恢复：无受伤时始终+2/天
  // 150-300天MC显示：+2 recovery vs (需求阈值惩罚 + 工作疲劳 > 90 penalty + 慢性病月扣)
  // 勉强平衡但长期有净流失。观察玩家死于Day 69-107。
  // 提高至 +3 recovery 提供更宽的安全余量，仍能被重度受伤/疾病combo击穿
  // 参考：《大多数》稳定的日恢复=让慢性病的"可管理"设计意图成立
  if (!st.injured && st.health < 100) {
    var baseRecovery = 3;
    var recoveryBonus =
      (state.inheritanceBonuses && state.inheritanceBonuses.recoveryRate) || 0;
    var totalRecovery = Math.max(
      1,
      Math.round(baseRecovery * (1 + recoveryBonus)),
    );
    st.health = Math.min(100, st.health + totalRecovery);
  }
}

/** 判定情绪状态（整合有效属性，状态互联系统） */
function determineEmotionalState(state) {
  // 使用有效属性（受状态交叉影响后的真实值）
  var effective =
    typeof getEffectiveStats === "function"
      ? getEffectiveStats(state)
      : {
          mental: state.player.mental,
          intelligence: state.player.intelligence,
        };

  const p = state.player;
  const n = state.needs;
  let score = 50;

  score += (n.happiness - 50) * 0.35;
  if (n.fatigue > 80) score -= 20;
  else if (n.fatigue > 60) score -= 10;
  else if (n.fatigue < 20) score += 5;
  if (n.hunger < 20) score -= 15;
  else if (n.hunger < 40) score -= 5;
  if (n.hygiene < 20) score -= 10;
  else if (n.hygiene > 80) score += 5; // 干净整洁心情好
  // 使用有效心智（状态差→心智打折→情绪更差→恶性循环）
  score += (effective.mental - 50) * 0.2;
  if (state.status.health < 30) score -= 20;
  else if (state.status.health > 90) score += 5; // 健康良好加分
  if (state.status.injured) score -= 10;
  if (state.status.sick) score -= 8;

  let emotionalState;
  if (score < 15) emotionalState = "depressed";
  else if (score < 30) emotionalState = "sad";
  else if (score < 45) emotionalState = "stressed";
  else if (score < 60) emotionalState = "stable";
  else if (score < 80) emotionalState = "happy";
  // [全系统自洽修复] 域G A类修复: 原条件两分支都映射到"happy"，≥80分和60-79分无区分——新增"elated"状态
  else emotionalState = "elated";

  // [全系统自洽修复] 域F联动: 情绪状态转变时推送转折消息 (F→G 联动,让玩家感知情绪轨迹)
  var prevEmo = state.status.emotionalState;
  state.status.emotionalState = emotionalState;
  if (prevEmo && prevEmo !== emotionalState && typeof StateManager !== "undefined") {
    var _emoTransitionMsgs = {
      "stable_happy": "☀️ 今天状态不错,做事心情舒畅。",
      "happy_elated": "🌟 你感觉自己状态极佳！今天做什么都特别顺手！",
      "sad_stable": "🌤️ 心情总算慢慢平复了,生活还要继续。",
      "stressed_sad": "😔 压力让你有些喘不过气,记得给自己减减负。",
      "happy_stable": "🌥️ 激情退去,回归日常,这也是一种节奏。",
      "stable_stressed": "😰 生活压力渐增,别忘了找点乐子调剂。",
    };
    var _key = prevEmo + "_" + emotionalState;
    // 仅对正向/显著负向转变推送,避免刷屏(每7天最多一次)
    if (_emoTransitionMsgs[_key] && state.player && state.player.day % 7 === 0) {
      StateManager.addMessage(_emoTransitionMsgs[_key], "info");
    }
  }

  // [全系统自洽修复] 域G 联动增强: 追踪抑郁/悲伤连续天数（用于触发街头善意事件）
  if (emotionalState === "depressed" || emotionalState === "sad") {
    state.flags._depressionStreak = (state.flags._depressionStreak || 0) + 1;
  } else {
    state.flags._depressionStreak = 0;
  }

  // [全系统自洽修复] 域G 联动增强: 追踪愉悦天数（用于成就系统）
  if (emotionalState === "happy" || emotionalState === "elated") {
    state.flags._happyDaysTotal = (state.flags._happyDaysTotal || 0) + 1;
  }

  // [全系统自洽修复] 域G 联动增强: 首次达到 elated 状态时发送庆祝消息
  if (emotionalState === "elated" && !state.flags._everElated) {
    state.flags._everElated = true;
    StateManager.addMessage("🌟 你感觉自己状态极佳！今天做什么都特别顺手！", "success");
    // 记录到回忆录
    if (typeof addMemoir === "function") {
      try { addMemoir("career", { icon: "🌟", title: "状态极佳", text: "今天你感觉自己状态极佳，做什么都特别顺手！这是你在这座城市第一次达到这样的巅峰状态。" }); } catch(e) {}
    }
  }
  // 首次进入抑郁/悲伤时发送关注提示
  if (emotionalState === "depressed" && !state.flags._everDepressed) {
    state.flags._everDepressed = true;
    StateManager.addMessage("😢 你感到前所未有的低落。也许该找人聊聊，或者好好休息一下。", "warning");
    // 记录到回忆录
    if (typeof addMemoir === "function") {
      try { addMemoir("illness", { icon: "😢", title: "情绪低谷", text: "今天是你在城市里最艰难的一天。情绪跌到了谷底，但你还在这里，没有放弃。" }); } catch(e) {}
    }
  }

  return emotionalState;
}

/** 情绪对工作的修正 */
function getEmotionWorkModifier(state) {
  const emo = state.status.emotionalState || "stable";
  const mods = {
    depressed: { pay: 0.45, injury: 2.5, skillXp: 0.3 },
    sad: { pay: 0.65, injury: 1.5, skillXp: 0.5 },
    stressed: { pay: 0.8, injury: 1.3, skillXp: 0.7 },
    stable: { pay: 1.0, injury: 1.0, skillXp: 1.0 },
    happy: { pay: 1.25, injury: 0.7, skillXp: 1.5 },
    // [全系统自洽修复] 域G A类修复: 新增 elated 状态（情绪分值≥80时触发）
    elated: { pay: 1.5, injury: 0.5, skillXp: 2.0 },
  };
  return mods[emo] || mods.stable;
}

/** 获取情绪图标 */
function getEmotionIcon(state) {
  const icons = {
    depressed: "😢",
    sad: "😔",
    stressed: "😰",
    stable: "😐",
    happy: "😊",
    // [全系统自洽修复] 域G A类修复: 新增 elated 状态图标
    elated: "🌟",
  };
  return icons[state.status.emotionalState] || "😐";
}

/** 获取情绪中文名 */
function getEmotionName(state) {
  var names = {
    depressed: "抑郁",
    sad: "悲伤",
    stressed: "焦虑",
    stable: "平稳",
    happy: "开心",
    elated: "极佳",
  };
  return names[state.status.emotionalState] || "未知";
}

