/**
 * 资产关联维持性开支 — 解决后期"钱太多没事做"
 * 物业费按资产 0.1%/天，社交应酬按资产梯度衰减心情
 * 调用位置：daily_pipeline.js needs_decay 步骤后
 */
function applyWealthBasedOverhead(state) {
  if (typeof StateManager === "undefined") return;
  // [全系统自洽修复] 域G A类修复: cash NaN 传播导致现金永久损坏（undefined/NaN 令 totalAssets=NaN → NaN<50000=false → 进入核心逻辑 → state.resources.cash -= NaN = NaN）
  var totalAssets = (state.resources.cash || 0) + (state.resources.bankBalance || 0);
  if (!isFinite(totalAssets)) totalAssets = 0;
  if (totalAssets < 50000) return; // 仅资产 > 5W 触发

  // 物业费：按资产 0.03%/天（v3.1：0.1%→0.03%，¥500K→¥150/天封顶¥2000/天）
  var propertyFee = Math.min(2000, Math.round(totalAssets * 0.0003));
  if (propertyFee > 0) {
    state.resources.cash -= propertyFee;
    if (typeof addDailyTransaction === "function") {
      addDailyTransaction(
        state,
        "expense",
        "wealth_overhead",
        propertyFee,
        "物业管理费",
      );
    }
    StateManager.addMessage(
      "🏠 物业管理费 ¥" + propertyFee.toLocaleString() + "（资产越高维护越贵）",
      "info",
    );
  }

  // 住房维护费：住房等级越高越贵
  // v3.2: tier 0=¥0, tier 1=¥10, tier 2=¥40, tier 3=¥200 (降低中期负担)
  // v3.53 修复：扩展至 7 档，tier 4-6 维护费不为零（原数组越界导致 tier≥4 维护费=0 的性价比崩坏）
  var houseTier = (state.housing && state.housing.tier) || 0;
  var UPKEEP = [0, 10, 40, 200, 500, 2000, 5000];
  var houseCost = UPKEEP[houseTier] || 0;
  if (houseCost > 0) {
    state.resources.cash -= houseCost;
    if (typeof addDailyTransaction === "function") {
      addDailyTransaction(
        state,
        "expense",
        "wealth_overhead",
        houseCost,
        "住房维护费",
      );
    }
    StateManager.addMessage("🏡 住房维护费 ¥" + houseCost + "/天", "info");
  }

  // 社交应酬：资产每 ¥200K 增加 -1 心情衰减（富人有更多社交压力）
  if (totalAssets > 200000) {
    var socialDecay = Math.min(8, Math.floor(totalAssets / 200000) * 0.8);
    state.needs.happiness = Math.max(0, state.needs.happiness - socialDecay);
  }

  // 高额资产管理费：资产超 1000 万后每日 0.1% 消耗（防止资金无限膨胀）
  if (totalAssets > 10000000) {
    var excessWealth = totalAssets - 10000000;
    var wealthFee = Math.round(excessWealth * 0.001);
    if (wealthFee > 0) {
      state.resources.cash -= wealthFee;
      if (typeof addDailyTransaction === "function") {
        addDailyTransaction(
          state,
          "expense",
          "wealth_overhead",
          wealthFee,
          "财富管理费",
        );
      }
      StateManager.addMessage(
        "💼 财富管理费 ¥" +
          wealthFee.toLocaleString() +
          "（资产超千万的专项管理费用）",
        "info",
      );
    }
  }
}

;
// ==== js/phase1/interactions.js ====
/**
 * 状态互联系统 — 状态↔基础属性↔状态的深度交叉影响
 *
 * 设计参考: The Sims需求轮盘/This War of Mine状态惩罚/RimWorld意识系统/大多数生存联动
 *
 * 提供: getEffectiveStats(), getApCostMultiplier(), applyStatusInteractions(), checkExtremeConditions()
 */

/** 获取经状态修正后的有效属性值（工作时、技能判定时使用） */
function getEffectiveStats(state) {
  const n = state.needs,
    st = state.status,
    p = state.player;
  var mult = { physique: 1.0, intelligence: 1.0, agility: 1.0, mental: 1.0 };

  // === 饥饿影响（饿得没力气/脑子转不动） ===
  if (n.hunger < 30) {
    mult.agility *= 0.85;
    mult.mental *= 0.9;
  }
  if (n.hunger < 15) {
    mult.agility *= 0.75;
    mult.mental *= 0.8;
    mult.physique *= 0.85;
  }
  if (n.hunger < 5) {
    mult.agility *= 0.5;
    mult.mental *= 0.5;
    mult.physique *= 0.6;
  }

  // === 疲劳影响 ===
  if (n.fatigue > 70) {
    mult.agility *= 0.85;
    mult.mental *= 0.9;
  }
  if (n.fatigue > 85) {
    mult.agility *= 0.7;
    mult.mental *= 0.75;
    mult.physique *= 0.85;
  }
  if (n.fatigue > 95) {
    mult.agility *= 0.5;
    mult.mental *= 0.5;
    mult.physique *= 0.7;
  }

  // === 健康影响 ===
  if (st.health < 50) {
    mult.physique *= 0.85;
  }
  if (st.health < 30) {
    mult.physique *= 0.7;
    mult.agility *= 0.85;
  }
  if (st.health < 15) {
    mult.physique *= 0.5;
    mult.agility *= 0.7;
    mult.intelligence *= 0.85;
  }

  // === 心情影响 ===
  if (n.happiness < 20) {
    mult.mental *= 0.8;
    mult.intelligence *= 0.9;
  }
  if (n.happiness < 10) {
    mult.mental *= 0.6;
    mult.intelligence *= 0.8;
  }

  // === 生病/受伤 ===
  if (st.sick) {
    mult.physique *= 0.85;
    mult.agility *= 0.9;
    mult.mental *= 0.9;
  }
  if (st.injured) {
    mult.physique *= 0.75;
    mult.agility *= 0.7;
  }

  // === 命名疾病额外属性 debuff（来自 illness.js）===
  if (typeof getIllnessAttrDebuffs === "function") {
    var ad = getIllnessAttrDebuffs(state);
    // ad.physique 等是"扣多少有效点数"，转为乘数：扣10点≈打0.9折
    if (ad.physique) mult.physique *= Math.max(0.3, 1 - ad.physique / 100);
    if (ad.intelligence)
      mult.intelligence *= Math.max(0.3, 1 - ad.intelligence / 100);
    if (ad.agility) mult.agility *= Math.max(0.3, 1 - ad.agility / 100);
    if (ad.mental) mult.mental *= Math.max(0.3, 1 - ad.mental / 100);
  }

  // === 高基础属性正向反馈（好体魄抗压） ===
  if (p.agility > 50) mult.agility *= 1.05;
  if (p.mental > 50) mult.mental *= 1.05;
  if (p.physique > 60) mult.physique *= 1.03;

  // === 基础属性内部互动 ===
  if (p.physique > 50) mult.agility *= 1.03; // 体质好→行动更敏捷
  if (p.mental > 50) mult.intelligence *= 1.03; // 心智强→思考更清晰
  if (p.intelligence > 50) mult.mental *= 1.02; // 智商高→情绪调节更好

  // 计算有效值（保底30%）
  var clamp = function (v) {
    return Math.max(0.3, v);
  };
  return {
    physique: Math.round(p.physique * clamp(mult.physique)),
    intelligence: Math.round(p.intelligence * clamp(mult.intelligence)),
    agility: Math.round(p.agility * clamp(mult.agility)),
    mental: Math.round(p.mental * clamp(mult.mental)),
    multipliers: mult,
  };
}

/** 获取当前AP消耗倍率（影响所有 consumeAP 调用的实际消耗） */
function getApCostMultiplier(state) {
  var n = state.needs,
    st = state.status,
    p = state.player;
  var mult = 1.0;

  // === 负面状态增加AP消耗 ===
  if (n.fatigue > 70) mult += 0.2;
  if (n.fatigue > 85) mult += 0.25; // 累计+0.45
  if (n.fatigue > 95) mult += 0.35; // 累计+0.8

  if (n.hunger < 20) mult += 0.3;
  if (n.hunger < 10) mult += 0.2; // 累计+0.5

  if (st.sick) mult += 0.5;
  if (st.injured) mult += 0.3;

  if (n.happiness < 15) mult += 0.2;

  // === 命名疾病额外 AP 倍率（来自 illness.js）===
  if (typeof getIllnessAttrDebuffs === "function") {
    var ad = getIllnessAttrDebuffs(state);
    if (ad.apMult) mult += ad.apMult;
  }

  // === 天气影响AP ===
  if (state.weather) {
    var w = state.weather.current;
    if (w === "heatwave" || w === "coldwave") mult += 0.2;
    if (w === "storm" || w === "snow") mult += 0.15;
  }

  // === 高敏捷减免（身体灵活→做事高效） ===
  if (p.agility > 50) mult -= 0.1;
  if (p.agility > 75) mult -= 0.1; // 累计-0.2

  // === 保底：AP消耗至少为原始的50%，最多为250% ===
  return Math.max(0.5, Math.min(2.5, mult));
}

/** 每日结算时施加状态→状态的交叉影响（在applyNeedsDecay之后调用） */
function applyStatusInteractions(state) {
  var n = state.needs,
    st = state.status,
    p = state.player;

  // --- 饥饿加速疲劳（没吃饭→没力气→更容易累） ---
  if (n.hunger < 30) n.fatigue = Math.min(100, n.fatigue + 5);
  if (n.hunger < 15) n.fatigue = Math.min(100, n.fatigue + 8);

  // --- 饥饿→心情下降（饿肚子不开心） ---
  if (n.hunger < 20) n.happiness = Math.max(0, n.happiness - 5);

  // --- 疲劳→心情下降（累了心情自然差） ---
  if (n.fatigue > 70) n.happiness = Math.max(0, n.happiness - 3);
  if (n.fatigue > 85) n.happiness = Math.max(0, n.happiness - 5);

  // --- 疲劳→懒得洗漱 ---
  if (n.fatigue > 85) n.hygiene = Math.max(0, n.hygiene - 3);

  // --- 卫生差→心情下降 ---
  if (n.hygiene < 20) n.happiness = Math.max(0, n.happiness - 3);
  if (n.hygiene < 10) n.happiness = Math.max(0, n.happiness - 5);

  // --- 心情好→缓解疲劳（心情愉快精力恢复快） ---
  if (n.happiness > 70) n.fatigue = Math.max(0, n.fatigue - 3);
  if (n.happiness > 85) n.fatigue = Math.max(0, n.fatigue - 5);

  // --- 心情差→疲劳恢复减半（存入临时标记，endDay睡眠恢复时使用） ---
  state._fatigueRecoveryPenalty = n.happiness < 20 ? 0.5 : 1.0;

  // --- 健康差→疲劳增长（身体不好容易累） ---
  if (st.health < 50) n.fatigue = Math.min(100, n.fatigue + 3);
  if (st.health < 30) n.fatigue = Math.min(100, n.fatigue + 5);

  // --- 生病/受伤的全面影响 ---
  if (st.sick) {
    n.fatigue = Math.min(100, n.fatigue + 8);
    n.happiness = Math.max(0, n.happiness - 5);
    n.hygiene = Math.max(0, n.hygiene - 2);
  }
  if (st.injured) {
    n.fatigue = Math.min(100, n.fatigue + 5);
    n.happiness = Math.max(0, n.happiness - 3);
  }

  // --- 命名疾病的每日 needs 累加（来自 illness.js）---
  if (typeof getIllnessNeedsImpact === "function") {
    var ni = getIllnessNeedsImpact(state);
    if (ni.hunger) n.hunger = Math.max(0, Math.min(100, n.hunger + ni.hunger));
    if (ni.fatigue)
      n.fatigue = Math.max(0, Math.min(100, n.fatigue + ni.fatigue));
    if (ni.hygiene)
      n.hygiene = Math.max(0, Math.min(100, n.hygiene + ni.hygiene));
    if (ni.happiness)
      n.happiness = Math.max(0, Math.min(100, n.happiness + ni.happiness));
  }

  // --- 高体质→减缓疲劳积累（身体底子好扛得住） ---
  if (p.physique > 60) n.fatigue = Math.max(0, n.fatigue - 2);
  if (p.physique > 80) n.fatigue = Math.max(0, n.fatigue - 3);

  // --- 高心智→减缓心情下降（内心强大情绪稳定） ---
  if (p.mental > 60) n.happiness = Math.min(100, n.happiness + 2);
  if (p.mental > 80) n.happiness = Math.min(100, n.happiness + 3);

  // --- 高智力→卫生意识更强 ---
  if (p.intelligence > 50) n.hygiene = Math.min(100, n.hygiene + 2);
  if (p.intelligence > 75) n.hygiene = Math.min(100, n.hygiene + 3);

  // --- 保底值 ---
  n.hunger = Math.max(0, Math.min(100, n.hunger));
  n.fatigue = Math.max(0, Math.min(100, n.fatigue));
  n.hygiene = Math.max(0, Math.min(100, n.hygiene));
  n.happiness = Math.max(0, Math.min(100, n.happiness));
}

/**
 * 极端状态检测（在每个行动之前和endDay中调用）
 * 返回: null(正常) | 'skip_day'(跳过当日剩余时间) | 'forced_rest'(强制休息)
 */
function checkExtremeConditions(state) {
  var n = state.needs,
    st = state.status;

  // === 饿晕 → 跳过一整天 ===
  if (n.hunger <= 5) {
    StateManager.addMessage(
      "💀 你饿晕在街头，醒来已经是第二天了...健康严重受损！好心人给了你一点吃的。",
      "danger",
    );
    st.health = Math.max(0, st.health - 15);
    n.hunger = 10; // 好心人给了点吃的
    n.fatigue = Math.min(100, n.fatigue + 20);
    n.happiness = Math.max(0, n.happiness - 20);
    return "skip_day";
  }

  // === 过劳晕倒 → 强制结束当天 ===
  if (n.fatigue >= 98) {
    StateManager.addMessage(
      "😵 你累倒了！身体完全撑不住了，被送回家休息...",
      "danger",
    );
    st.health = Math.max(0, st.health - 10);
    if (Random.chance(0.4)) st.sick = true; // 40%概率过劳生病
    return "skip_day";
  }

  // === 病危送医 ===
  if (st.health <= 5 && !state.flags._forcedHospital) {
    state.flags._forcedHospital = true;
    if (state.resources.cash >= 500) {
      state.resources.cash -= 500;
      st.health = Math.min(50, st.health + 20);
      StateManager.addMessage(
        "🏥 你病危被好心人送进医院，花了¥500急救费用...需要好好休养。",
        "warning",
      );
    } else {
      StateManager.addMessage(
        "🏥 你病危被送医抢救，但付不起¥500医药费...欠下¥500债务。",
        "danger",
      );
      state.resources.bankDebt = (state.resources.bankDebt || 0) + 500;
      state.resources.debt =
        (state.resources.villageDebt || 0) + (state.resources.bankDebt || 0);
      st.health = Math.min(30, st.health + 10);
    }
    return "skip_day";
  }

  // 重置医院标记（健康恢复到安全水平后）
  if (st.health > 20) {
    state.flags._forcedHospital = false;
  }

  // === 心情极度低落→拒绝工作 ===
  if (n.happiness <= 5 && !state.flags._depressionWarned) {
    state.flags._depressionWarned = true;
    StateManager.addMessage(
      "😢 你心情极度低落，做什么都提不起劲...今天效率大幅下降。",
      "warning",
    );
  }
  if (n.happiness > 15) {
    state.flags._depressionWarned = false;
  }

  return null; // 正常
}

/**
 * 获取状态对工作的综合修正（整合情绪+有效属性+状态惩罚）
 * 返回 { payMultiplier, injuryRisk, skillXpMultiplier, apMultiplier }
 */
function getWorkComprehensiveModifier(state) {
  var emoMod =
    typeof getEmotionWorkModifier === "function"
      ? getEmotionWorkModifier(state)
      : { pay: 1.0, injury: 1.0, skillXp: 1.0 };

  var eff = getEffectiveStats(state);
  var apMult = getApCostMultiplier(state);

  // 有效属性影响收入（能力打折→收入打折）
  var avgEff = (eff.physique + eff.intelligence + eff.agility + eff.mental) / 4;
  var avgNominal =
    (state.player.physique +
      state.player.intelligence +
      state.player.agility +
      state.player.mental) /
    4;
  var statPenalty = avgNominal > 0 ? Math.min(1.0, avgEff / avgNominal) : 1.0;

  return {
    payMultiplier: emoMod.pay * Math.max(0.3, statPenalty),
    injuryRisk:
      emoMod.injury *
      (state.status.sick ? 1.5 : 1) *
      (state.status.injured ? 1.5 : 1),
    skillXpMultiplier: emoMod.skillXp * Math.max(0.3, statPenalty),
    apMultiplier: apMult,
  };
}

/** 获取状态图标简要摘要（用于侧边栏提示） */
function getStatusSummary(state) {
  var warnings = [];
  var n = state.needs,
    st = state.status;

  if (n.hunger <= 5) warnings.push("💀饿晕危险");
  else if (n.hunger < 15) warnings.push("⚠️极度饥饿");
  else if (n.hunger < 30) warnings.push("🍞饥饿");

  if (n.fatigue >= 98) warnings.push("😵过劳危险");
  else if (n.fatigue > 85) warnings.push("⚠️极度疲劳");
  else if (n.fatigue > 70) warnings.push("🥱疲劳");

  if (n.hygiene < 15) warnings.push("🦠卫生差");
  if (n.happiness < 15) warnings.push("😢心情差");

  if (st.sick) warnings.push("🤒生病");
  if (st.injured) warnings.push("🩹受伤");
  if (st.health < 20) warnings.push("💔健康危险");

  var apMult = getApCostMultiplier(state);
  if (apMult > 1.3) warnings.push("🐌效率低×" + apMult.toFixed(1));

  return warnings;
}

;
// ==== js/phase1/illness.js ====
﻿/**
 * Illness 系统 — 长期不良习惯 → 命名疾病
 *
 * 三大循环：
 *   1. 每日 tickHabits(state) — 根据当日 needs 更新各种 streak/counter。
 *   2. 每日 rollDailyIllness(state) — 检查 habit 阈值，按 severity 决定的概率患病。
 *   3. 每日 tickIllnessDecay(state) — 已患疾病按 naturalCureDays 自然恢复。
 *
 * 症状叠加：
 *   - getIllnessStatusMods(state) — 返回 {health, hunger, fatigue, ...} 累加值
 *   - 由 applyStatusInteractions 调用，叠加到 needs 上
 *   - getIllnessAttrDebuffs(state) — 返回 {physiqueDebuff, mentalDebuff, ...}
 *   - 由 getEffectiveStats 调用，进一步打折
 *
 * 治疗：
 *   - openClinicModal() 在医院解锁的"看病"行动里调起
 *   - 选病种 + 选档次（药店便宜慢 / 医院贵快）
 */

// ====== 每日习惯追踪 ======

/** 每日结算时调用：更新 streak/counter */
function tickHabits(state) {
  var n = state.needs;
  state.flags._habits = state.flags._habits || {
    junkFoodMeals: 0,
    lowHungerStreak: 0,
    lowHygieneStreak: 0,
    lowHappinessStreak: 0,
    highFatigueStreak: 0,
    lateNightActions: 0,
    stomach_inflammationCount: 0,
    // 疾病演化追踪：每种病治愈/痊愈的次数
    gastritisCount: 0,
    depressionCount: 0,
    coldCount: 0,
    pneumoniaCount: 0,
    malnutritionCount: 0,
    insomniaCount: 0,
    overworkCount: 0,
    // 特殊习惯
    officeWorkDays: 0,
    hungerHighStreak: 0,
    healthUnder30: 0,
  };
  var h = state.flags._habits;

  // 连续低 hunger
  if (n.hunger < 25) h.lowHungerStreak = (h.lowHungerStreak || 0) + 1;
  else h.lowHungerStreak = 0;

  // 连续低 hygiene
  if (n.hygiene < 30) h.lowHygieneStreak = (h.lowHygieneStreak || 0) + 1;
  else h.lowHygieneStreak = 0;

  // 连续低 happiness
  if (n.happiness < 20) h.lowHappinessStreak = (h.lowHappinessStreak || 0) + 1;
  else h.lowHappinessStreak = 0;

  // 连续高 fatigue
  if (n.fatigue > 80) h.highFatigueStreak = (h.highFatigueStreak || 0) + 1;
  else h.highFatigueStreak = 0;

  // 连续高 hunger（肥胖风险）
  if (n.hunger > 80) h.hungerHighStreak = (h.hungerHighStreak || 0) + 1;
  else h.hungerHighStreak = 0;

  // 健康<30 天数
  if (state.status && state.status.health < 30)
    h.healthUnder30 = (h.healthUnder30 || 0) + 1;
  else h.healthUnder30 = 0;

  // 办公室工作天数（由外部调用累加）
  // tickOfficeWorkDays 在 daily_pipeline 中调用

  // 疾病演化计数：已痊愈的疾病计入历史
  // 在 tickIllnessDecay 中，当疾病自然康复时调用 recordIllnessCure
}

// ====== 每日患病判定 ======

/** 检查所有疾病的触发条件，按概率患病 */
function rollDailyIllness(state) {
  if (!ILLNESSES) return;
  state.flags._habits = state.flags._habits || {};
  var h = state.flags._habits;

  for (var key in ILLNESSES) {
    if (!ILLNESSES.hasOwnProperty(key)) continue;
    var ill = ILLNESSES[key];
    if (!ill.triggerHabit) continue;

    // 已有该病则跳过
    if (hasIllness(state, key)) continue;

    // 检查 triggerHabit 所有条件
    var conditionsMet = true;
    var habitName = null;
    for (var hk in ill.triggerHabit) {
      if (!ill.triggerHabit.hasOwnProperty(hk)) continue;
      var threshold = ill.triggerHabit[hk];
      var actual;
      if (hk === "age") actual = state.player.age || 20;
      else actual = h[hk] || 0;
      if (actual < threshold) {
        conditionsMet = false;
        break;
      }
      if (!habitName) habitName = hk;
    }
    if (!conditionsMet) continue;

    // 概率掷骰
    var ch = ill.triggerChance || 0.5;
    // 消费点：城市服务·社区免费体检 medical.healthCheckDone → 建立健康基线，降低大病（severity≥4 或危急重症）触发概率
    if (
      state.medical &&
      state.medical.healthCheckDone &&
      (ill.isCritical || (ill.severity || 1) >= 4)
    ) {
      ch *= 0.5;
    }
    // v3.1 ④ 难度病率乘数：休闲 ×0.6、标准 ×1.0、困难 ×1.5、地狱 ×2.0
    if (typeof getDifficultyMultiplier === "function") {
      ch *= getDifficultyMultiplier(state, "illness");
    }
    if (!Random.chance(ch)) continue;

    // 患病！
    _addIllness(state, key);
    state.flags._everGotSick = true; // 成就追踪
    state.flags._everHadIllness = true; // 成就：疾病幸存者

    // 部分清零相关 habit（避免立刻再得一次）
    if (habitName === "lowHungerStreak")
      h.lowHungerStreak = Math.floor(h.lowHungerStreak / 2);
    else if (habitName === "lowHygieneStreak")
      h.lowHygieneStreak = Math.floor(h.lowHygieneStreak / 2);
    else if (habitName === "lowHappinessStreak")
      h.lowHappinessStreak = Math.floor(h.lowHappinessStreak / 2);
    else if (habitName === "highFatigueStreak")
      h.highFatigueStreak = Math.floor(h.highFatigueStreak / 2);
    else if (habitName === "junkFoodMeals")
      h.junkFoodMeals = Math.max(0, h.junkFoodMeals - 5);
    else if (habitName === "lateNightActions")
      h.lateNightActions = Math.max(0, h.lateNightActions - 4);
  }
}

function _addIllness(state, illnessId) {
  var ill = ILLNESSES[illnessId];
  if (!ill) return;
  // [全系统自洽修复] 域G A类修复: 确保 state.status 存在（管线边界场景）
  if (!state.status) state.status = {};
  state.status.illnesses = state.status.illnesses || [];
  state.status.illnesses.push({
    id: illnessId,
    contractedDay: state.player.day,
    severity: ill.severity || 1,
    treated: false,
  });
  // 兼容旧字段（让现有代码能继续读 sick）
  state.status.sick = true;

  var msg = (ill.icon || "🤒") + " 你患上了" + ill.name + "！";
  if (ill.isEvolution) {
    msg += "（由既往疾病演化而来）";
  }
  if (ill.isCritical) {
    msg += " ⚠️ 危急重症！";
  }
  msg += " " + (ill.desc || "");

  StateManager.addMessage(msg, "danger");

  // 追踪病史计数（用于演化链）- 患病时计数
  state.flags._habits = state.flags._habits || {};
  var evolutionCountMap = {
    cold: "coldCount",
    stomach_inflammation: "stomach_inflammationCount",
    gastritis: "gastritisCount",
    depression: "depressionCount",
    pneumonia: "pneumoniaCount",
    malnutrition: "malnutritionCount",
    insomnia: "insomniaCount",
    overwork: "overworkCount",
    // [全系统自洽修复] 域G A类修复: 新增6种疾病演化链计数器（原缺失导致疾病链断裂）
    hypertension: "hypertensionCount",
    fatty_liver: "fattyLiverCount",
    kidney_disease: "kidneyDiseaseCount",
    heart_disease: "heartDiseaseCount",
    liver_cirrhosis: "liverCirrhosisCount",
  };
  if (evolutionCountMap[illnessId]) {
    var countKey = evolutionCountMap[illnessId];
    state.flags._habits[countKey] = (state.flags._habits[countKey] || 0) + 1;
  }
}

/** 记录疾病痊愈（用于演化链追踪） */
function recordIllnessCure(state, illnessId) {
  var ill = ILLNESSES[illnessId];
  if (!ill) return;
  state.flags._everCuredIllness = true; // 成就：疾病幸存者
  var h = (state.flags._habits = state.flags._habits || {});

  // 将痊愈的疾病计入演化历史
  // [全系统自洽修复] 域G A类修复: 新增6种疾病演化链计数器（fattyLiverCount/hypertensionCount/kidneyDiseaseCount/heartDiseaseCount/liverCirrhosisCount/hepatitisBCount）
  if (illnessId === "cold") h.coldCount = (h.coldCount || 0) + 1;
  else if (illnessId === "stomach_inflammation")
    h.stomach_inflammationCount = (h.stomach_inflammationCount || 0) + 1;
  else if (illnessId === "gastritis")
    h.gastritisCount = (h.gastritisCount || 0) + 1;
  else if (illnessId === "depression")
    h.depressionCount = (h.depressionCount || 0) + 1;
  else if (illnessId === "pneumonia")
    h.pneumoniaCount = (h.pneumoniaCount || 0) + 1;
  else if (illnessId === "malnutrition")
    h.malnutritionCount = (h.malnutritionCount || 0) + 1;
  else if (illnessId === "insomnia")
    h.insomniaCount = (h.insomniaCount || 0) + 1;
  else if (illnessId === "overwork")
    h.overworkCount = (h.overworkCount || 0) + 1;
  else if (illnessId === "hypertension")
    h.hypertensionCount = (h.hypertensionCount || 0) + 1;
  else if (illnessId === "fatty_liver")
    h.fattyLiverCount = (h.fattyLiverCount || 0) + 1;
  else if (illnessId === "kidney_disease")
    h.kidneyDiseaseCount = (h.kidneyDiseaseCount || 0) + 1;
  else if (illnessId === "heart_disease")
    h.heartDiseaseCount = (h.heartDiseaseCount || 0) + 1;
  else if (illnessId === "liver_cirrhosis")
    h.liverCirrhosisCount = (h.liverCirrhosisCount || 0) + 1;
}

// ====== 每日疾病结算 ======

/** 每日：自然恢复 / 慢性病按月扣费 / 累计症状副作用 */
function tickIllnessDecay(state) {
  if (!state.status.illnesses) state.status.illnesses = [];
  var remaining = [];
  for (var i = 0; i < state.status.illnesses.length; i++) {
    var inst = state.status.illnesses[i];
    var ill = ILLNESSES[inst.id];
    if (!ill) continue;

    // 慢性病不会自然好（hypertension）
    if (ill.isChronic) {
      _tickChronic(state, inst, ill);
      remaining.push(inst);
      continue;
    }

    // 已治疗：加速康复
    var daysSince = state.player.day - inst.contractedDay;
    var minDays =
      ill.naturalCureDays && ill.naturalCureDays[0]
        ? ill.naturalCureDays[0]
        : 5;
    var maxDays =
      ill.naturalCureDays && ill.naturalCureDays[1]
        ? ill.naturalCureDays[1]
        : 8;
    if (inst.treated) {
      // 治疗后康复时间减半
      minDays = Math.ceil(minDays / 2);
      maxDays = Math.ceil(maxDays / 2);
    }

    // 营养不良需要 nutritious 餐才能康复
    if (ill.requiresNutrition && !inst.treated) {
      var recentNutrition =
        (state.flags._habits && state.flags._habits.junkFoodMeals) || 0;
      if (recentNutrition >= 3) {
        // 还在吃垃圾食品，不康复
        remaining.push(inst);
        continue;
      }
    }

    // 累计症状（health 持续掉、需要的 needs 加成）
    if (ill.symptom) {
      if (ill.symptom.health) {
        state.status.health = Math.max(
          0,
          state.status.health + ill.symptom.health,
        );
      }
      // 随机晕厥（高血压）
      if (
        ill.symptom.randomFaintCh &&
        Random.chance(ill.symptom.randomFaintCh)
      ) {
        state.needs.fatigue = Math.min(100, state.needs.fatigue + 20);
        StateManager.addMessage(
          "💢 " + ill.name + "突发，你眩晕了一下。",
          "warning",
        );
      }

      // 随机吐血（胃癌）
      if (
        ill.symptom.randomVomitCh &&
        Random.chance(ill.symptom.randomVomitCh)
      ) {
        state.status.health = Math.max(0, state.status.health - 3);
        StateManager.addMessage(
          "🩸 " + ill.name + "发作，你吐了血，健康-3！",
          "danger",
        );
      }

      // 幻觉（重度失眠）
      if (
        ill.symptom.hallucinationCh &&
        Random.chance(ill.symptom.hallucinationCh)
      ) {
        StateManager.addMessage(
          "👻 " + ill.name + "让你产生了幻觉，精神恍惚。",
          "warning",
        );
      }

      // 猝死风险检测
      if (
        ill.symptom.dailyDeathChance &&
        Random.chance(ill.symptom.dailyDeathChance)
      ) {
        StateManager.addMessage(
          "💔 " + ill.name + "导致猝死！你的心脏停止了跳动。",
          "danger",
        );
        state.player.alive = false;
        state.status.health = 0;
        // 游戏结束处理由外部接管
        continue;
      }

      // 头晕（贫血）
      if (ill.symptom.dizzinessCh && Random.chance(ill.symptom.dizzinessCh)) {
        // [全系统自洽修复] 域G A类修复: fatigue 未 clamp 至 100（其他症状均用 Math.min(100,...) 限幅）
        state.needs.fatigue = Math.min(100, state.needs.fatigue + 5);
        StateManager.addMessage(
          "😵 " + ill.name + "让你头晕目眩，疲劳+5。",
          "warning",
        );
      }
    }

    // 自然康复判定
    if (daysSince >= minDays) {
      var cureChance = (daysSince - minDays + 1) / (maxDays - minDays + 1);
      if (Random.chance(cureChance)) {
        StateManager.addMessage(
          (ill.icon || "🤒") + " 你的" + ill.name + "好了。",
          "success",
        );
        // 记录痊愈，用于演化链追踪
        recordIllnessCure(state, inst.id);
        continue; // 不放回 remaining
      }
    }
    remaining.push(inst);
  }
  state.status.illnesses = remaining;

  // 派生兼容字段
  state.status.sick = state.status.illnesses.length > 0;
}

function _tickChronic(state, inst, ill) {
  // 慢性病按月（30天）扣费；不交则发作
  var lastPaid = state.flags._chronicMonthlyPaid || inst.contractedDay;
  var due = state.player.day - lastPaid >= 30;
  if (due) {
    var monthly =
      (typeof ill.treatCostMonthly === "number" && ill.treatCostMonthly) ||
      (ill.treatCost && ill.treatCost.hospital_monthly) ||
      200;
    if (state.resources.cash >= monthly) {
      state.resources.cash -= monthly;
      state.flags._chronicMonthlyPaid = state.player.day;
      if (typeof addDailyTransaction === "function") {
        addDailyTransaction(
          state,
          "expense",
          "medical",
          monthly,
          ill.name + "月费",
        );
      }
      StateManager.addMessage(
        "💊 " + ill.name + "月费 ¥" + monthly + " 已自动扣除。",
        "info",
      );
    } else {
      // 没钱→症状加重
      state.status.health = Math.max(0, state.status.health - 5);
      StateManager.addMessage(
        "⚠️ 没钱付" + ill.name + "月费，症状加重，健康-5！",
        "danger",
      );
    }
  }
}

// ====== 症状对外接口（给 interactions.js 调用）======

/** 累计所有疾病症状对 needs/health 的每日影响（applyStatusInteractions 调用） */
function getIllnessNeedsImpact(state) {
  var impact = { hunger: 0, fatigue: 0, hygiene: 0, happiness: 0, health: 0 };
  if (!state.status.illnesses) return impact;
  for (var i = 0; i < state.status.illnesses.length; i++) {
    var ill = ILLNESSES[state.status.illnesses[i].id];
    if (!ill || !ill.symptom) continue;
    if (ill.symptom.hunger) impact.hunger += ill.symptom.hunger;
    if (ill.symptom.fatigue) impact.fatigue += ill.symptom.fatigue;
    if (ill.symptom.hygiene) impact.hygiene += ill.symptom.hygiene;
    if (ill.symptom.happiness) impact.happiness += ill.symptom.happiness;
    if (ill.symptom.health) impact.health += ill.symptom.health;
  }
  return impact;
}

/** 累计所有疾病对有效属性的扣减（getEffectiveStats 调用） */
function getIllnessAttrDebuffs(state) {
  var d = {
    physique: 0,
    intelligence: 0,
    agility: 0,
    mental: 0,
    apMult: 0,
    fatigueRecoveryMult: 1.0,
  };
  if (!state.status.illnesses) return d;
  for (var i = 0; i < state.status.illnesses.length; i++) {
    var ill = ILLNESSES[state.status.illnesses[i].id];
    if (!ill || !ill.symptom) continue;
    if (ill.symptom.physiqueDebuff) d.physique += ill.symptom.physiqueDebuff;
    if (ill.symptom.intelligenceDebuff)
      d.intelligence += ill.symptom.intelligenceDebuff;
    if (ill.symptom.agilityDebuff) d.agility += ill.symptom.agilityDebuff;
    if (ill.symptom.mentalDebuff) d.mental += ill.symptom.mentalDebuff;
    if (ill.symptom.apMult) d.apMult += ill.symptom.apMult;
    if (ill.symptom.fatigueRecoveryMult)
      d.fatigueRecoveryMult *= ill.symptom.fatigueRecoveryMult;
  }
  return d;
}

/** 每日累加办公室工作天数（由 daily_pipeline 调用） */
function tickOfficeWorkDays(state) {
  if (state.corporate && state.corporate.company) {
    var jobDef = getJobById && getJobById(state.corporate.jobId);
    if (jobDef && (jobDef.type === "office" || jobDef.type === "corp")) {
      state.flags._habits = state.flags._habits || {};
      state.flags._habits.officeWorkDays =
        (state.flags._habits.officeWorkDays || 0) + 1;
    }
  }
}

// ====== 治疗 UI ======

/** 打开诊所 / 看病弹窗（在医院解锁的行动里调用） */
function openClinicModal() {
  var state = StateManager.getState();
  var illnesses = state.status.illnesses || [];
  if (illnesses.length === 0) {
    showModal({
      title: "🏥 医院",
      body: '<p style="font-size:13px;line-height:1.7;">医生说：你目前没有患病，注意保持健康习惯就好。</p>',
      buttons: [{ text: "好的", cls: "btn-primary" }],
    });
    return;
  }

  var html =
    '<div style="font-size:13px;line-height:1.7;">医生帮你检查了一下，你目前有以下疾病：</div>';
  html +=
    '<div style="margin-top:10px;display:flex;flex-direction:column;gap:8px;">';
  for (var i = 0; i < illnesses.length; i++) {
    var inst = illnesses[i];
    var ill = ILLNESSES[inst.id];
    if (!ill) continue;
    var daysSince = state.player.day - inst.contractedDay;
    var pharCost = (ill.treatCost && ill.treatCost.pharmacy) || null;
    var hospCost = (ill.treatCost && ill.treatCost.hospital) || null;

    html +=
      '<div style="padding:8px;background:var(--bg-input);border-radius:4px;border-left:3px solid var(--danger);">';
    html +=
      '<div style="font-weight:600;">' +
      (ill.icon || "🤒") +
      " " +
      ill.name +
      ' <span style="font-size:11px;color:var(--text-muted);font-weight:normal;">已患' +
      daysSince +
      "天</span></div>";
    html +=
      '<div style="font-size:11px;color:var(--text-secondary);margin-top:4px;">' +
      (ill.desc || "") +
      "</div>";
    html += '<div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap;">';
    if (pharCost) {
      html +=
        '<button class="btn btn-sm" data-treat="pharmacy" data-ill="' +
        inst.id +
        '">💊 药店治疗 ¥' +
        pharCost +
        "</button>";
    }
    if (hospCost) {
      html +=
        '<button class="btn btn-sm btn-primary" data-treat="hospital" data-ill="' +
        inst.id +
        '">🏥 医院治疗 ¥' +
        hospCost +
        "</button>";
    }
    if (inst.treated) {
      html +=
        '<span style="font-size:11px;color:var(--success);">✓ 已治疗，等待康复</span>';
    }
    html += "</div></div>";
  }
  html += "</div>";
  html +=
    '<div style="margin-top:10px;font-size:11px;color:var(--text-muted);">药店便宜恢复慢，医院贵但效果立竿见影。</div>';

  showModal({
    title: "🏥 看病",
    body: html,
    buttons: [{ text: "关闭", cls: "" }],
  });

  // 给治疗按钮挂监听
  setTimeout(function () {
    var btns = document.querySelectorAll("[data-treat]");
    for (var i = 0; i < btns.length; i++) {
      btns[i].addEventListener("click", function (e) {
        var tier = e.currentTarget.getAttribute("data-treat");
        var illId = e.currentTarget.getAttribute("data-ill");
        treatIllness(illId, tier);
        // 关闭并重开（刷新列表）
        var overlay = document.querySelector(".modal-overlay");
        if (overlay) document.body.removeChild(overlay);
        openClinicModal();
      });
    }
  }, 0);
}

function treatIllness(illnessId, tier) {
  var state = StateManager.getState();
  var ill = ILLNESSES[illnessId];
  if (!ill) return;
  var cost = (ill.treatCost && ill.treatCost[tier]) || 0;
  // 王医生诊所折扣：有 flags.wangClinicDiscount 且 _clinicDiscountDays > 0 时打八折
  if (
    cost > 0 &&
    state.flags &&
    state.flags.wangClinicDiscount &&
    state._clinicDiscountDays > 0
  ) {
    cost = Math.round(cost * 0.8);
    state._clinicDiscountDays--;
    if (state._clinicDiscountDays <= 0) {
      delete state.flags.wangClinicDiscount;
    }
  }
  if (cost === 0 && tier === "pharmacy") {
    StateManager.addMessage("💊 此病无法仅靠药店治疗，请去医院。", "warning");
    return;
  }
  if (state.resources.cash < cost) {
    StateManager.addMessage("💸 现金不足 ¥" + cost + "。", "warning");
    return;
  }
  state.resources.cash -= cost;
  if (typeof addDailyTransaction === "function") {
    addDailyTransaction(state, "expense", "medical", cost, ill.name + "治疗");
  }

  // 找到该病实例并标记
  for (var i = 0; i < state.status.illnesses.length; i++) {
    var inst = state.status.illnesses[i];
    if (inst.id === illnessId) {
      if (tier === "hospital") {
        // 医院立刻康复
        state.status.illnesses.splice(i, 1);
        StateManager.addMessage(
          "🏥 你接受了" +
            ill.name +
            "的医院治疗（¥" +
            cost +
            "），症状立刻消失。",
          "success",
        );
      } else {
        // 药店：标记 treated=true，自然康复时间减半
        inst.treated = true;
        StateManager.addMessage(
          "💊 你买了" + ill.name + "的药（¥" + cost + "），症状会逐渐减轻。",
          "info",
        );
      }
      break;
    }
  }

  // 更新派生兼容字段
  state.status.sick = state.status.illnesses.length > 0;

  // === v3.23: 触发槽 — after_heal ===
  if (typeof window.TriggerRegistry !== "undefined") {
    try {
      var afterHealEvent = window.TriggerRegistry.triggerRandom(
        "after_heal",
        state,
      );
      if (afterHealEvent) {
        setTimeout(function () {
          if (typeof showEventModal === "function")
            showEventModal(afterHealEvent);
        }, 100);
      }
    } catch (e) {
      console.warn("TriggerRegistry after_heal 触发失败:", e);
    }
  }
}

// ====== 疾病演化提示 ======

/** 检查疾病演化风险（每日结算时调用） */
function checkEvolutionRisk(state) {
  if (!ILLNESSES || !state.status || !state.status.illnesses) return;
  var illnesses = state.status.illnesses;
  var warnedEvolution = state.flags._evolutionWarningShown || {};

  for (var i = 0; i < illnesses.length; i++) {
    var inst = illnesses[i];
    var ill = ILLNESSES[inst.id];
    if (!ill || !ill.evolvesTo || ill.evolvesTo.length === 0) continue;

    // 检查演化条件是否接近满足
    var h = state.flags._habits || {};
    for (var ei = 0; ei < ill.evolvesTo.length; ei++) {
      var targetId = ill.evolvesTo[ei];
      var targetIll = ILLNESSES[targetId];
      if (!targetIll || !targetIll.triggerHabit) continue;

      // 检查每个触发条件
      var riskLevel = 0; // 0=无风险, 1=低风险, 2=中风险, 3=高风险
      var maxThreshold = 0;
      var closestHabit = null;

      for (var hk in targetIll.triggerHabit) {
        if (!targetIll.triggerHabit.hasOwnProperty(hk)) continue;
        var threshold = targetIll.triggerHabit[hk];
        var actual = h[hk] || 0;
        if (hk === "age") actual = state.player.age || 20;

        maxThreshold = Math.max(maxThreshold, threshold);
        var ratio = actual / threshold;

        if (ratio >= 0.7) riskLevel = Math.max(riskLevel, 3);
        else if (ratio >= 0.5) riskLevel = Math.max(riskLevel, 2);
        else if (ratio >= 0.3) riskLevel = Math.max(riskLevel, 1);

        if (ratio >= 0.3 && (!closestHabit || ratio > closestHabit.ratio)) {
          closestHabit = {
            habit: hk,
            actual: actual,
            threshold: threshold,
            ratio: ratio,
          };
        }
      }

      // 只显示高风险提示（避免刷屏）
      if (riskLevel >= 2 && !warnedEvolution[inst.id + "_" + targetId]) {
        warnedEvolution[inst.id + "_" + targetId] = true;
        state.flags._evolutionWarningShown = warnedEvolution;

        var riskLabel = riskLevel === 3 ? "🚨 高危" : "⚠️ 中危";
        var habitLabel =
          {
            junkFoodMeals: "垃圾食品",
            lowHungerStreak: "长期饥饿",
            lowHygieneStreak: "卫生极差",
            lowHappinessStreak: "心情低落",
            highFatigueStreak: "过度疲劳",
            lateNightActions: "夜生活",
            stomach_inflammationCount: "肠胃炎",
            coldCount: "感冒",
            pneumoniaCount: "肺炎",
            malnutritionCount: "营养不良",
            insomniaCount: "失眠",
            depressionCount: "抑郁",
            officeWorkDays: "办公室工作",
            hungerHighStreak: "过度饱食",
            healthUnder30: "健康低下",
            age: "年龄",
          }[closestHabit?.habit || "unknown"] ||
          closestHabit?.habit ||
          "未知习惯";

        var msg =
          riskLabel +
          "：你的" +
          ill.name +
          "有演化成" +
          targetIll.name +
          "的风险！" +
          "当前" +
          habitLabel +
          "（" +
          closestHabit.actual +
          "/" +
          closestHabit.threshold +
          "）接近阈值。" +
          "建议尽快治疗！";

        StateManager.addMessage(msg, riskLevel === 3 ? "danger" : "warning");

        // 首次高危演化风险时弹出提示弹窗
        if (riskLevel === 3 && !state.flags._evolutionModalShown) {
          state.flags._evolutionModalShown = {};
          _showEvolutionWarningModal(state, ill, targetIll, closestHabit);
        }
      }
    }
  }
}

