/* =========================================================
 * 一、初始化 & 行情更新
 * ========================================================= */

/** 初始化股市 */
function initStockMarket(state) {
  // [全系统自洽修复] 域E A类#2: state.corporate.stockMarket 可能未初始化（旧存档降级）
  if (!state.corporate) state.corporate = {};
  if (!state.corporate.stockMarket) state.corporate.stockMarket = {};
  if (!state.corporate.stocks) state.corporate.stocks = [];
  for (const stock of STOCK_LIST) {
    state.corporate.stockMarket[stock.symbol] = {
      price: stock.basePrice * Random.float(0.85, 1.15),
      history: [], // [{ day, price }]
      high20: stock.basePrice,
      low20: stock.basePrice,
      lastNewsDay: -999,
      _initialized: false,
    };
  }
}

/** 初始化时填入少量历史走势 */
function bootstrapStockHistory(state) {
  for (const sym of Object.keys(state.corporate.stockMarket)) {
    const market = state.corporate.stockMarket[sym];
    const def = STOCK_LIST.find((s) => s.symbol === sym);
    if (!def) continue;
    if (!market._initialized) {
      market._initialized = true;
      // 倒推 20 天历史
      let p = market.price / Random.float(0.85, 1.15);
      for (let i = 0; i < 20; i++) {
        const change =
          1 + Random.float(-def.volatility / 2, def.volatility / 2);
        p = p * change;
        market.history.push({ day: state.player.day - (20 - i), price: p });
      }
      market.history.push({ day: state.player.day, price: market.price });
      market.high20 = Math.max(...market.history.map((h) => h.price));
      market.low20 = Math.min(...market.history.map((h) => h.price));
    }
  }
}

/** 更新股市价格（每日 / 季末） */
function updateStockPrices(state, forceNews = false) {
  for (const stock of STOCK_LIST) {
    const market = state.corporate.stockMarket[stock.symbol];
    if (!market) continue;

    // 1) 基础趋势（每日漂移）
    const trend = stock.baseTrend;
    // 2) 随机扰动（正态分布近似）
    const noise = Random.float(-stock.volatility, stock.volatility);
    // 3) 均值回归（偏离20日均价过远时拉回一些）
    let meanReversion = 0;
    if (market.history.length >= 5) {
      const recent = market.history.slice(-5);
      const avg = recent.reduce((s, h) => s + h.price, 0) / recent.length;
      meanReversion = ((avg - market.price) / avg) * 0.15;
    }
    // [全系统自洽修复] 域E 修复:接入新闻系统影响股价
    var newsMul = 1.0;
    if (typeof getNewsEffectForInvestment === "function") {
      newsMul = getNewsEffectForInvestment(
        stock.symbol,
        stock.industry,
        "",
        state,
      );
    }
    const change = (1 + trend + noise + meanReversion) * newsMul;
    market.price = Math.max(0.5, market.price * change);
    market.price = Math.round(market.price * 100) / 100;

    // 4) 新闻冲击（5% 概率触发）
    if (forceNews || Random.chance(0.05)) {
      const newsPool = STOCK_NEWS_TEMPLATES.find(
        (n) => n.symbol === stock.symbol,
      );
      if (newsPool && state.player.day - market.lastNewsDay > 3) {
        const news =
          newsPool.headlines[Random.int(0, newsPool.headlines.length - 1)];
        market.price = Math.max(0.5, market.price * (1 + news.impact));
        market.price = Math.round(market.price * 100) / 100;
        market.lastNewsDay = state.player.day;
        StateManager.addMessage(
          `📊 [${stock.symbol}] ${news.text}`,
          news.impact > 0 ? "success" : "danger",
        );
      }
    }

    // 记录历史
    market.history.push({ day: state.player.day, price: market.price });
    if (market.history.length > 20) market.history.shift();
    market.high20 = Math.max(...market.history.map((h) => h.price));
    market.low20 = Math.min(...market.history.map((h) => h.price));
  }
}

/* =========================================================
 * 二、买卖接口
 * ========================================================= */

/** 买入股票 */
function buyStock(symbol, shares) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域E A类#5: state.corporate 守卫
  if (!state.corporate || !state.corporate.stockMarket) {
    StateManager.addMessage("⚠️ 股票市场未初始化。", "warning");
    return false;
  }
  const market = state.corporate.stockMarket[symbol];
  if (!market) {
    StateManager.addMessage("⚠️ 不存在的股票。", "danger");
    return false;
  }

  shares = Math.floor(shares);
  if (shares <= 0 || !isFinite(shares)) {
    StateManager.addMessage("⚠️ 至少买入1股。", "warning");
    return false;
  }

  const cost = Math.round(market.price * shares * 100) / 100;
  if (state.resources.cash < cost) {
    StateManager.addMessage(
      `⚠️ 需要 ¥${cost.toLocaleString()}，现金不足。`,
      "danger",
    );
    return false;
  }

  state.resources.cash -= cost;

  const existing = state.corporate.stocks.find((s) => s.symbol === symbol);
  if (existing) {
    const totalShares = existing.shares + shares;
    existing.avgPrice =
      Math.round(
        ((existing.avgPrice * existing.shares + cost) / totalShares) * 100,
      ) / 100;
    existing.shares = totalShares;
  } else {
    state.corporate.stocks.push({
      symbol,
      name: STOCK_LIST.find((s) => s.symbol === symbol)?.name || symbol,
      shares,
      avgPrice: market.price,
    });
  }

  StateManager.addMessage(
    `📈 买入 ${symbol} ×${shares}股 @¥${market.price}，共 ¥${cost.toLocaleString()}`,
    "success",
  );

  // Phase 2：记录交易日志（供内幕交易审查）
  if (typeof logTrade === "function") {
    var rumor = state.insiderTrading?.activeRumor;
    var relatedRumorId = null;
    if (rumor && !rumor.resolvedDay) {
      // 检查当前交易是否与风声公司相关
      if (CORP_STOCK_MAP) {
        for (var cid in CORP_STOCK_MAP) {
          if (
            CORP_STOCK_MAP[cid].indexOf(symbol) >= 0 &&
            cid === rumor.companyId
          ) {
            relatedRumorId = rumor.id;
            break;
          }
        }
      }
    }
    logTrade(state, symbol, "buy", shares, market.price, relatedRumorId);
  }

  return true;
}

/** 卖出股票 */
function sellStock(symbol, shares) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域E A类#6: state.corporate.stocks 守卫
  if (!state.corporate || !state.corporate.stocks) {
    StateManager.addMessage("⚠️ 股票持仓未初始化。", "warning");
    return false;
  }
  const holding = state.corporate.stocks.find((s) => s.symbol === symbol);
  if (!holding || holding.shares < shares || !isFinite(shares) || shares <= 0) {
    StateManager.addMessage("⚠️ 持仓不足。", "danger");
    return false;
  }

  const market = state.corporate.stockMarket[symbol];
  if (!market) {
    StateManager.addMessage("⚠️ 该股票已退市，无法交易。", "danger");
    return false;
  }

  const revenue = Math.round(market.price * shares * 100) / 100;
  const profit = revenue - (holding.avgPrice || 0) * shares;

  state.resources.cash += revenue;
  state.resources.totalEarned += Math.max(0, profit);

  holding.shares -= shares;
  if (holding.shares <= 0) {
    state.corporate.stocks = state.corporate.stocks.filter(
      (s) => s.symbol !== symbol,
    );
  }

  const profitStr =
    profit >= 0
      ? `📈 盈利 ¥${Math.round(profit).toLocaleString()}`
      : `📉 亏损 ¥${Math.abs(Math.round(profit)).toLocaleString()}`;
  StateManager.addMessage(
    `💰 卖出 ${symbol} ×${shares}股，¥${revenue.toLocaleString()}。${profitStr}`,
    profit >= 0 ? "success" : "warning",
  );

  // Phase 2：记录交易日志（供内幕交易审查）
  if (typeof logTrade === "function") {
    var rumor = state.insiderTrading?.activeRumor;
    var relatedRumorId = null;
    if (rumor && !rumor.resolvedDay) {
      if (CORP_STOCK_MAP) {
        for (var cid in CORP_STOCK_MAP) {
          if (
            CORP_STOCK_MAP[cid].indexOf(symbol) >= 0 &&
            cid === rumor.companyId
          ) {
            relatedRumorId = rumor.id;
            break;
          }
        }
      }
    }
    logTrade(state, symbol, "sell", shares, market.price, relatedRumorId);
  }

  return true;
}

/** 计算能全部买入的股数（按当前价） */
function calcMaxBuyShares(symbol) {
  const state = StateManager.getState();
  const market = state.corporate.stockMarket[symbol];
  if (!market || market.price <= 0) return 0;
  // 保留 1 元，避免精度问题
  const cash = Math.max(0, state.resources.cash - 1);
  return Math.floor(cash / market.price);
}

/* =========================================================
 * 三、交易 UI
 * ========================================================= */

/** 渲染简易 K 线（折线图 + 颜色块） */
function renderKLine(history, currentPrice) {
  if (!history || !Array.isArray(history) || history.length < 2) {
    return '<div style="color:var(--text-muted);font-size:10px;">无历史数据</div>';
  }
  // [全系统自洽修复] 域E 修复:history中可能有undefined项导致map崩溃
  var prices = history
    .filter(function (h) {
      return h && isFinite(h.price);
    })
    .map(function (h) {
      return h.price;
    });
  if (prices.length < 2) {
    return '<div style="color:var(--text-muted);font-size:10px;">无历史数据</div>';
  }
  const max = Math.max(...prices, currentPrice);
  const min = Math.min(...prices, currentPrice);
  const range = max - min || 1;
  const w = 140; // svg width
  const h = 40; // svg height
  const stepX = w / (history.length - 1);
  const points = history
    .map((p, i) => {
      const x = i * stepX;
      const y = h - ((p.price - min) / range) * h;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");

  // 折线/填充使用固定色（信息蓝），不随涨跌方向变化
  // 方向信息由价格数字和涨跌幅文字（红涨绿跌）负责
  const lineColor = "var(--info)";
  const fillColor = "rgba(90,138,180,0.12)";

  // 构造一个 polygon 用于填充
  const fillPoints = `0,${h} ${points} ${w},${h}`;

  return `
    <svg width="${w}" height="${h}" style="display:block;margin-top:4px;">
      <polygon points="${fillPoints}" fill="${fillColor}" />
      <polyline points="${points}" fill="none" stroke="${lineColor}" stroke-width="1.5" />
    </svg>
  `;
}

/** 渲染单只股票卡片 */
function renderStockCard(stock, state) {
  const market = state.corporate.stockMarket[stock.symbol];
  if (!market) return "";
  const price = market.price;
  const holding = state.corporate.stocks.find((s) => s.symbol === stock.symbol);
  const shares = holding ? holding.shares : 0;

  // 今日涨跌（vs 上一日）
  const prev =
    market.history.length >= 2
      ? market.history[market.history.length - 2].price
      : price;
  const todayChange = price - prev;
  const todayPct = (todayChange / prev) * 100;

  // 7日均价
  const last7 = market.history.slice(-7);
  const avg7 =
    last7.length > 0
      ? last7.reduce((s, h) => s + h.price, 0) / last7.length
      : price;
  const aboveAvg7 = price > avg7;

  // 持仓盈亏
  const pnl = holding ? Math.round((price - holding.avgPrice) * shares) : 0;
  const pnlPct = holding
    ? ((price - holding.avgPrice) / holding.avgPrice) * 100
    : 0;
  // PnL颜色：中国/A股标准 — 盈利红/亏损绿（涨红跌绿）
  const pnlColor = pnl >= 0 ? "var(--danger)" : "var(--success)";
  // 涨跌颜色：红涨绿跌（中国/A股标准）
  const trendColor = todayChange >= 0 ? "var(--danger)" : "var(--success)";
  const trendIcon = todayChange >= 0 ? "▲" : "▼";

  // 全买/全卖能买多少
  const maxBuy = calcMaxBuyShares(stock.symbol);
  const maxSell = shares;

  return `
    <div class="action-card stock-card" style="border-left:3px solid ${trendColor};">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;">
        <div>
          <div class="card-title" style="margin:0;">${stock.symbol} ${stock.name}</div>
          <div style="font-size:10px;color:var(--text-muted);">${stock.industry} | 波动率${(stock.volatility * 100).toFixed(0)}%</div>
        </div>
        <div style="text-align:right;">
          <div style="font-size:18px;font-weight:700;color:${trendColor};">¥${price.toFixed(2)}</div>
          <div style="font-size:11px;color:${trendColor};">${trendIcon} ${todayChange >= 0 ? "+" : ""}${todayChange.toFixed(2)} (${todayPct >= 0 ? "+" : ""}${todayPct.toFixed(2)}%)</div>
        </div>
      </div>

      <div style="display:flex;justify-content:space-between;align-items:center;margin:4px 0;font-size:10px;color:var(--text-muted);">
        <span>7日均 ¥${avg7.toFixed(2)} ${aboveAvg7 ? "🔴" : "🟢"}</span>
        <span>20日高 ¥${market.high20.toFixed(2)}</span>
        <span>20日低 ¥${market.low20.toFixed(2)}</span>
      </div>

      ${renderKLine(market.history, price)}

      ${
        shares > 0
          ? `
        <div style="margin-top:8px;padding:6px 8px;background:rgba(0,180,216,0.06);border-radius:4px;font-size:11px;">
          <div style="display:flex;justify-content:space-between;">
            <span>持仓: <strong>${shares}</strong>股 | 均价 <strong>¥${holding.avgPrice.toFixed(2)}</strong></span>
            <span style="color:${pnlColor};font-weight:600;">${pnl >= 0 ? "+" : ""}¥${pnl.toLocaleString()} (${pnlPct >= 0 ? "+" : ""}${pnlPct.toFixed(1)}%)</span>
          </div>
        </div>
      `
          : ""
      }

      <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:8px;">
        <button class="btn btn-sm btn-success stock-buy" data-sym="${stock.symbol}" data-qty="10">买10</button>
        <button class="btn btn-sm btn-success stock-buy" data-sym="${stock.symbol}" data-qty="100">买100</button>
        <button class="btn btn-sm btn-success stock-buy-all" data-sym="${stock.symbol}" ${maxBuy === 0 ? "disabled" : ""} title="用所有现金按当前价买入">📦 全部买入 (${maxBuy})</button>
        <button class="btn btn-sm btn-danger stock-sell" data-sym="${stock.symbol}" data-qty="10" ${shares === 0 ? "disabled" : ""}>卖10</button>
        <button class="btn btn-sm btn-danger stock-sell-all" data-sym="${stock.symbol}" ${shares === 0 ? "disabled" : ""} title="卖出全部持仓">💰 全部卖出 (${shares})</button>
      </div>
    </div>
  `;
}

function showStockTradeModal() {
  const state = StateManager.getState();
  // [全系统自洽修复] 域E A类#3: stockMarket可能未初始化（旧存档/Phase1）
  if (!state.corporate || !state.corporate.stockMarket) {
    if (typeof StateManager !== "undefined") StateManager.addMessage("⚠️ 股票市场尚未开放", "warning");
    return;
  }
  // 首次打开：bootstrap 历史
  if (Object.values(state.corporate.stockMarket).some((m) => !m._initialized)) {
    bootstrapStockHistory(state);
  }

  // 持仓概览
  const totalStockValue = state.corporate.stocks.reduce((sum, s) => {
    const m = state.corporate.stockMarket[s.symbol];
    return sum + (m ? m.price * s.shares : 0);
  }, 0);
  const totalCost = state.corporate.stocks.reduce(
    (sum, s) => sum + (s.avgPrice || 0) * (s.shares || 0),
    0,
  );
  const totalPnL = Math.round(totalStockValue - totalCost);
  const pnlColor = totalPnL >= 0 ? "var(--danger)" : "var(--success)";

  let body = `
    <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:var(--bg-card);border-radius:6px;margin-bottom:12px;">
      <div>
        <div style="font-size:11px;color:var(--text-muted);">现金</div>
        <div style="font-size:16px;font-weight:600;color:var(--success);">¥${state.resources.cash.toLocaleString()}</div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);">持仓市值</div>
        <div style="font-size:16px;font-weight:600;">¥${totalStockValue.toLocaleString()}</div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);">浮动盈亏</div>
        <div style="font-size:16px;font-weight:600;color:${pnlColor};">${totalPnL >= 0 ? "+" : ""}¥${totalPnL.toLocaleString()}</div>
      </div>
    </div>
    <p style="font-size:11px;color:var(--text-muted);margin-bottom:8px;">
      💡 提示：每只股票有独立的行业、波动率，会受公司新闻影响。价格每日波动 + 漂移 + 回归。
    </p>
    <div style="max-height:55vh;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:8px;">
  `;

  for (const stock of STOCK_LIST) {
    body += renderStockCard(stock, state);
  }
  body += "</div>";

  showModal({
    title: "📈 股票交易 (8只多行业)",
    body,
    buttons: [
      {
        text: "🚀 刷新行情",
        cls: "btn-primary",
        callback: () => {
          // 模拟一次价格更新看看效果
          updateStockPrices(state, false);
          showStockTradeModal();
        },
      },
      {
        text: "关闭",
        cls: "",
        callback: () => {
          renderAll();
        },
      },
    ],
  });

  // 绑定按钮
  setTimeout(() => {
    document.querySelectorAll(".stock-buy").forEach((btn) => {
      btn.onclick = () => {
        buyStock(btn.dataset.sym, parseInt(btn.dataset.qty));
        showStockTradeModal();
      };
    });
    document.querySelectorAll(".stock-buy-all").forEach((btn) => {
      btn.onclick = () => {
        const sym = btn.dataset.sym;
        const qty = calcMaxBuyShares(sym);
        if (qty > 0) {
          buyStock(sym, qty);
        } else {
          StateManager.addMessage("⚠️ 现金不足买入 1 股。", "warning");
        }
        showStockTradeModal();
      };
    });
    document.querySelectorAll(".stock-sell").forEach((btn) => {
      btn.onclick = () => {
        const sym = btn.dataset.sym;
        const qty = parseInt(btn.dataset.qty);
        const holding = state.corporate.stocks.find((s) => s.symbol === sym);
        if (holding && holding.shares > 0) {
          sellStock(sym, Math.min(qty, holding.shares));
        }
        showStockTradeModal();
      };
    });
    document.querySelectorAll(".stock-sell-all").forEach((btn) => {
      btn.onclick = () => {
        const sym = btn.dataset.sym;
        const holding = state.corporate.stocks.find((s) => s.symbol === sym);
        if (holding && holding.shares > 0) {
          sellStock(sym, holding.shares);
        } else {
          StateManager.addMessage("⚠️ 没有持仓可卖。", "warning");
        }
        showStockTradeModal();
      };
    });
  }, 50);
}

/** 刷新行情的辅助函数（季度切换时调用） */
function refreshStockMarket(state) {
  updateStockPrices(state, true);
  bootstrapStockHistory(state);
}

;
// ==== js/phase2/corp_ops.js ====
/**
 * 职场行动执行引擎
 */

/** 执行职场行动 */
function doCorporateAction(actionId) {
  const state = StateManager.getState();
  // [全系统自洽修复] 域H A类#2: state.corporate 可能未初始化（Phase1误调）
  if (!state.corporate || !state.corporate.rank) {
    if (typeof StateManager !== "undefined") StateManager.addMessage("⚠️ 未入职，无法执行职场行动。", "warning");
    return false;
  }
  // [全系统自洽修复] 域H A类#3: 检查 state.player.corporate 存在性（与 state.corporate 是不同路径）
  if (!state.player.corporate) {
    if (typeof StateManager !== "undefined") StateManager.addMessage("⚠️ 职场角色数据未初始化，无法执行职场行动。", "warning");
    return false;
  }
  const action = CORP_ACTIONS.find((a) => a.id === actionId);
  if (!action) return false;

  // 检查职级要求
  if (action.requiresRank) {
    const rankIndex = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
      state.corporate.rank,
    );
    const requiredIndex = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
      action.requiresRank,
    );
    if (rankIndex < requiredIndex) {
      StateManager.addMessage(
        `⚠️ 需要${action.requiresRank}以上才能执行此操作。`,
        "warning",
      );
      return false;
    }
  }

  // 检查费用
  // [全系统自洽修复] 域H A类: cash NaN 防御（旧存档/极端值导致现金损坏）
  if (action.cost && (state.resources.cash || 0) < action.cost) {
    StateManager.addMessage(`⚠️ 需要 ¥${action.cost}，现金不足。`, "warning");
    return false;
  }

  // 特殊处理：股票交易
  if (action.special === "stock") {
    showStockTradeModal();
    return true;
  }

  // 扣费
  if (action.cost) {
    state.resources.cash -= action.cost;
  }

  // 应用效果（Q4冲刺KPI+50%）
  const c = state.player.corporate;
  const effects = action.effects;
  const sprintBonus = state.flags.q4Sprint ? 1.5 : 1;
  if (effects.kpi)
    c.kpi = Math.max(
      0,
      Math.min(150, c.kpi + Math.round(effects.kpi * sprintBonus)),
    );
  if (effects.ability)
    c.ability = Math.max(0, Math.min(100, c.ability + effects.ability));
  if (effects.hair) c.hair = Math.max(0, Math.min(100, c.hair + effects.hair));
  if (effects.dignity)
    c.dignity = Math.max(0, Math.min(100, c.dignity + effects.dignity));
  if (effects.upwardMgmt)
    c.upwardMgmt = Math.max(
      0,
      Math.min(100, c.upwardMgmt + effects.upwardMgmt),
    );
  if (effects.popularity)
    c.popularity = Math.max(
      0,
      Math.min(100, c.popularity + effects.popularity),
    );
  if (effects.risk) c.risk = Math.max(0, Math.min(100, c.risk + effects.risk));
  if (effects.fatigue)
    state.needs.fatigue = Math.max(
      0,
      Math.min(100, state.needs.fatigue + effects.fatigue),
    );
  if (effects.happiness)
    state.needs.happiness = Math.max(
      0,
      Math.min(100, state.needs.happiness + effects.happiness),
    );
  // 现金效果
  if (effects.cash)
    state.resources.cash = Math.max(0, state.resources.cash + effects.cash);
  if (effects.intelligence)
    state.player.intelligence = Math.min(
      100,
      state.player.intelligence + effects.intelligence,
    );

  state.corporate.actionsUsed++;
  StateManager.addMessage(`${action.icon} ${action.name}完成！`, "success");

  // [全系统自洽修复] 域H 联动增强4: 季度行动进度指示器（H→F）
  var rankDataProgress = state.corporate.rank ? CORP_RANKS[state.corporate.rank] : null;
  var maxActs = rankDataProgress ? rankDataProgress.maxActions : 3;
  var used = state.corporate.actionsUsed;
  StateManager.addMessage(`📊 季度行动进度: ${used}/${maxActs}`, "info");

  // 检查季度是否用完
  const rankData = CORP_RANKS[state.corporate.rank];
  const maxActions = rankData ? rankData.maxActions : 3;
  if (state.corporate.actionsUsed >= maxActions) {
    endQuarter();
  }

  return true;
}

/** 季度结束 */
function endQuarter() {
  const state = StateManager.getState();
  // [全系统自洽修复] 域H A类#2: state.corporate 空守卫（防旧存档/降级状态崩溃）
  if (!state.corporate || !state.corporate.rank) {
    StateManager.addMessage("⚠️ 未入职，无法结算季度。", "warning");
    return false;
  }
  const c = state.corporate;

  // 已退休人员停发工资（查 career_dev 退休标记）
  if (state.flags && state.flags._retired) {
    StateManager.addMessage("🏖️ 已退休，季度工资停发。", "info");
    // [全系统自洽修复] 域H A类#1: 退休后仍重置 actionsUsed+推进季度，否则 actionsUsed 永不归零→endQuarter 死循环
    c.actionsUsed = 0;
    if (c.corpQuarter >= 4) { c.corpQuarter = 1; state.player.corpYear++; }
    else { c.corpQuarter++; }
    return;
  }

  // 绩效考核
  // [全系统自洽修复] 域H A类#4: typeof 守卫 + state.resources/state.needs 防御
  if (typeof calculatePerfScore !== "function") {
    StateManager.addMessage("⚠️ 绩效系统不可用，跳过季度结算。", "warning");
    return false;
  }
  const perfResult = calculatePerfScore(state);
  if (typeof assignGrade !== "function") {
    StateManager.addMessage("⚠️ 绩效评级系统不可用，跳过季度结算。", "warning");
    return false;
  }
  const grade = assignGrade(perfResult.score, state);
  c.perfHistory.push({
    year: state.player.corpYear,
    quarter: state.player.corpQuarter,
    grade: grade.grade,
    score: perfResult.score,
  });

  // 追踪连续C
  if (grade.grade === "C") {
    c.consecutiveC++;
  } else {
    c.consecutiveC = 0;
  }

  // 发放季度工资
  const rankData = CORP_RANKS[c.rank];
  const salary = rankData ? rankData.baseSalary * 3 : 45000;
  if (!state.resources) state.resources = { cash: 0, bankBalance: 0, totalEarned: 0 };
  state.resources.cash = (state.resources.cash || 0) + salary;
  state.resources.totalEarned = (state.resources.totalEarned || 0) + salary;
  if (typeof addDailyTransaction === "function") {
    addDailyTransaction(
      state,
      "income",
      "salary",
      salary,
      "季度工资 - " + c.rank,
    );
  }

  StateManager.addMessage(
    `💰 Q${c.corpQuarter} 结束。工资到账 ¥${salary.toLocaleString()}。绩效: ${grade.grade}`,
    "success",
  );

  // [全系统自洽修复] 域H 联动增强6: 季度绩效影响职场同事关系（H→D）
  if (typeof addDailyTransaction === "function" && state.relationships) {
    var gradeAffinityMap = { "S+": 5, S: 4, A: 3, B: 1, C: -2 };
    var affinityChange = gradeAffinityMap[grade.grade] || 0;
    if (affinityChange !== 0) {
      var workplaceNPCs = ["boss_li", "xiao_mei", "zhaojie", "old_zhou"];
      for (var wi = 0; wi < workplaceNPCs.length; wi++) {
        var npcRel = state.relationships[workplaceNPCs[wi]];
        if (npcRel && npcRel.met) {
          // [全系统自洽修复] 域H A类修复: 绩效影响同事好感改走 applyAffinityChange
          applyAffinityChange(state, workplaceNPCs[wi], affinityChange, "绩效影响");
        }
      }
      if (affinityChange > 0) {
        StateManager.addMessage("📈 好绩效让同事们对你刮目相看，好感度+" + affinityChange + "。", "success");
      } else if (affinityChange < 0) {
        StateManager.addMessage("📉 绩效不佳，同事们看你的眼神有点微妙，好感度" + affinityChange + "。", "warning");
      }
    }
  }

  // Q1 年终奖（发放后清除冲刺标记）
  if (c.corpQuarter === 1 && c.perfHistory.length >= 4) {
    const bonusMultiplier =
      { "S+": 3, S: 2, A: 1.5, B: 1, C: 0 }[grade.grade] || 0;
    const bonus = Math.round(rankData.baseSalary * bonusMultiplier);
    if (bonus > 0) {
      state.resources.cash += bonus;
      addDailyTransaction(
        state,
        "income",
        "salary",
        bonus,
        "年终奖 - 绩效" + grade.grade,
      );
      StateManager.addMessage(
        `🎉 年终奖到账！绩效 ${grade.grade}，奖金 ¥${bonus.toLocaleString()}！`,
        "success",
      );
    }
    state.flags.q4Sprint = false;
  }

  // Q4 冲刺（下季度 KPI 增益 +50%）
  if (c.corpQuarter === 4) {
    state.flags.q4Sprint = true;
    // [全系统自洽修复] 域H 联动增强1: Q4冲刺积累疲劳（H→G）
    if (state.needs) {
      state.needs.fatigue = Math.min(100, (state.needs.fatigue || 0) + 5);
      StateManager.addMessage("😰 冲刺季压力大，疲劳+5。", "warning");
    }
    StateManager.addMessage(
      "🏃 进入Q4冲刺季！下季度所有KPI增益+50%，绩效评分×1.1。",
      "event",
    );
  }

  // Q3 晋升判定
  if (c.corpQuarter === 3) {
    const promoResult = checkPromotion(state);
    if (promoResult) {
      applyPromotion(state, promoResult);
    }
  }

  // 更新股票市场（延迟初始化+每季度行情刷新）
  if (
    typeof initStockMarket === "function" &&
    Object.keys(c.stockMarket || {}).length === 0
  ) {
    initStockMarket(state);
  }
  if (
    typeof updateStockPrices === "function" &&
    Object.keys(c.stockMarket || {}).length > 0
  ) {
    // [全系统自洽修复] 域H 联动增强2: 绩效影响股价（H→E）
    // S/S+级绩效→利好公司股价，C级→利空
    if (grade.grade === "S+" || grade.grade === "S") {
      state.flags._corpPerfStockBoost = true;
    } else if (grade.grade === "C") {
      state.flags._corpPerfStockDrag = true;
    }
    updateStockPrices(state, false);
  }

  // 职场随机事件
  if (Random.chance(0.2) && typeof rollCorporateEvent === "function") {
    rollCorporateEvent(state);
  }

  // ====== Phase 2: 季末内幕交易审查 ======
  if (typeof auditInsiderTrading === "function") {
    var auditResults = auditInsiderTrading(state);
    if (auditResults && auditResults.length > 0) {
      // 已在 auditInsiderTrading 中发送消息
    }
  }

  // ====== Phase 2: 创业系统季度结算（已移至每日管线 tickStartup(daily)）======

  // ====== Phase 2: 检查创业公司收购要约（季度检查）======
  if (typeof getAcquisitionOffer === "function") {
    var offer = getAcquisitionOffer(state);
    if (offer) {
      // 显示收购要约弹窗
      if (typeof showAcquisitionModal === "function") {
        showAcquisitionModal(state);
      }
    }
  }

  // ====== Phase 2: 检查交易处罚是否到期 ======
  if (typeof checkTradingPenalty === "function") {
    checkTradingPenalty(state);
  }

  // [全系统自洽修复] 域H 联动增强5: 职场压力累积叙事（H→B）— 风险过高时触发倦怠反思
  var riskLevel = c.risk || 0;
  if (riskLevel > 70) {
    var burnoutMsg = "😰 职场风险等级已达" + riskLevel + "，你感到身心俱疲。";
    if (riskLevel > 85) {
      burnoutMsg += " 连续的高压工作让你开始怀疑自己是否还能撑下去。";
      state.needs.fatigue = Math.min(100, (state.needs.fatigue || 0) + 5);
      state.needs.happiness = Math.max(0, (state.needs.happiness || 50) - 5);
    } else {
      burnoutMsg += " 你告诉自己再坚持一下，但身体在发出警告。";
      state.needs.fatigue = Math.min(100, (state.needs.fatigue || 0) + 3);
    }
    StateManager.addMessage(burnoutMsg, "warning");
  }

  // 推进季度
  c.actionsUsed = 0;
  if (c.corpQuarter >= 4) {
    c.corpQuarter = 1;
    state.player.corpYear++;
    state.player.age++;
    StateManager.addMessage(
      `🎂 又一年过去了，你现在${state.player.age}岁了。`,
      "event",
    );
    // [全系统自洽修复] 域H 联动增强3: 职场年度叙事回顾（H→B）
    var yearsHere = state.player.corpYear || 1;
    var gradeThisYear = (c.perfHistory && c.perfHistory.length > 0) ? c.perfHistory[c.perfHistory.length - 1].grade : "C";
    var totalEarnedCorp = state.resources && state.resources.totalEarned ? state.resources.totalEarned : 0;
    var reflection = "";
    if (yearsHere <= 2) {
      reflection = "入职第" + yearsHere + "年，你从新人开始一步步站稳脚跟。";
    } else if (yearsHere <= 5) {
      reflection = "第" + yearsHere + "年了，你已成为团队的中坚力量。";
    } else {
      reflection = "第" + yearsHere + "年——你看着新来的年轻人，想起当年的自己。";
    }
    if (gradeThisYear === "S+" || gradeThisYear === "S") {
      reflection += " 今年绩效" + gradeThisYear + "，你对自己的表现很满意。";
    } else if (gradeThisYear === "C") {
      reflection += " 今年绩效不太理想，但明年还有机会。";
    }
    if (totalEarnedCorp > 0) {
      reflection += " 职场生涯累计收入¥" + totalEarnedCorp.toLocaleString() + "。";
    }
    StateManager.addMessage("📋 " + reflection, "info");
  } else {
    c.corpQuarter++;
  }

  // 失败条件
  if (typeof checkCorpLoseConditions === "function") checkCorpLoseConditions(state);
  // 胜利条件
  if (typeof checkCorpWinConditions === "function") checkCorpWinConditions(state);

  // [全系统自洽修复] 域H 联动增强: H→G C级绩效压力增疲劳
  if (grade.grade === "C" && state.needs) {
    state.needs.fatigue = Math.min(100, (state.needs.fatigue || 0) + 3);
    StateManager.addMessage("😰 绩效不佳让你压力很大，疲劳+3。", "warning");
  }

  // [全系统自洽修复] 域H 联动增强: H→F 季度末公司状态摘要
  if (state.startup && state.startup.company) {
    var _company = state.startup.company;
    var _cash = _company.cashReserve || 0;
    var _emp = (_company.employees || []).length;
    var _burn = _company.burnRate || 0;
    var _runway = _burn > 0 ? Math.round(_cash / _burn * 30) : 999;
    if (_emp > 0) {
      StateManager.addMessage("🏢 公司状态：团队" + _emp + "人 · 现金¥" + Math.round(_cash).toLocaleString() + " · 可维持约" + _runway + "天", "info");
    }
  }

  if (typeof autoSave === "function") autoSave("milestone");
}

/** 进入职场阶段 */
function enterCorporatePhase(companyId) {
  const state = StateManager.getState();
  const p = state.player;

  // 多周目保护：如果所选公司已倒闭，自动选一个活着的
  if (typeof isCompanyDeceased === "function" && isCompanyDeceased(companyId)) {
    var alive =
      typeof getAvailableCompanies === "function"
        ? getAvailableCompanies()
        : COMPANIES;
    if (alive.length > 0) {
      companyId = alive[0].id;
      StateManager.addMessage(
        "⚠️ 你选择的公司已在历史中倒闭，自动转向" + alive[0].name,
        "warning",
      );
    }
  }

  const company =
    COMPANIES.find((c) => c.id === (companyId || "star_tech")) || COMPANIES[0];

  p.phase = "corporate";
  p.corpYear = 1;
  p.corpQuarter = 1;

  // [全系统自洽修复] 域H A类#5: 初始化 p.corporate 对象防止后续属性访问崩溃
  if (!p.corporate) p.corporate = {};

  p.corporate.hair = 100;
  p.corporate.dignity = Math.min(100, Math.round(p.mental * 1.2));
  p.corporate.upwardMgmt = Math.min(
    100,
    Math.round(state.skills.sales.level * 0.8 + 15),
  );
  p.corporate.kpi = Math.min(
    150,
    Math.round(p.agility * 0.5 + state.skills.coding.level * 0.5 + 15),
  );
  p.corporate.ability = Math.min(
    100,
    Math.round(p.intelligence * 0.8 + state.skills.coding.level * 0.5 + 10),
  );
  p.corporate.risk = Math.min(100, 8 + Random.int(0, 11));
  p.corporate.popularity = Math.min(
    100,
    Math.round(state.player.fame * 0.5 + 25),
  );

  state.corporate.rank = "P5";
  // [全系统自洽修复] 域H 修复:初始化corporate.level(P5→1)，供events_corp/family_events事件条件使用
  state.corporate.level = 1;
  // [全系统自洽修复] 域H A类#1: 初始化corpQuarter(默认1=Q1)，endQuarter使用c.corpQuarter推进季度
  state.corporate.corpQuarter = 1;
  state.corporate.company = company;
  state.corporate.joinedDay = p.day;
  state.corporate.actionsUsed = 0;

  // 初始化股票市场
  if (typeof initStockMarket === "function") {
    initStockMarket(state);
    if (typeof bootstrapStockHistory === "function") {
      bootstrapStockHistory(state);
    }
  }

  // 立即初始化投资系统（首日即显示走势图）
  if (typeof initInvestment === "function") {
    initInvestment(state);
  }

  // 张姐内推：入职时额外向上管理+10、人缘+10（有人脉就是不一样）
  if (state.flags.zhangReferred) {
    p.corporate.upwardMgmt = Math.min(100, p.corporate.upwardMgmt + 10);
    p.corporate.popularity = Math.min(100, p.corporate.popularity + 10);
    StateManager.addMessage(
      "🤝 张姐内推加分：向上管理和人缘都好了不少！",
      "success",
    );
  }
  // 小美实习引荐：入职时额外能力+15、KPI+10（实习经历是资本）
  if (state.flags.xiaomeiInternship) {
    p.corporate.ability = Math.min(100, p.corporate.ability + 15);
    p.corporate.kpi = Math.min(150, p.corporate.kpi + 10);
    StateManager.addMessage(
      "💻 小美的实习引荐：工作能力和KPI起点高了不少！",
      "success",
    );
  }

  StateManager.addMessage(
    `🏢 入职 ${company.name}！从P5开始职场生涯。${company.culture}。`,
    "success",
  );
  // [全系统自洽修复] 域H 联动增强: Phase1→2过渡叙事闭环
  var streetDays = p.day;
  var totalEarned = state.resources.totalEarned || 0;
  StateManager.addMessage(
    "📜 从街头到写字楼，你用了" +
      streetDays +
      "天。" +
      (totalEarned > 0
        ? "街头打拼攒下¥" + totalEarned.toLocaleString() + "。"
        : "") +
      "新的战场，准备好了。",
    "info",
  );
  StateManager.addMessage(
    "💡 做项目提升KPI，向上社交获取信任。每季度有行动次数限制。Q3有晋升答辩。",
    "info",
  );

  document.querySelector(".modal-overlay")?.remove();
  currentTab = "actions";
  renderAll();
}

