// ==== js/ui/modal.js ====
/**
 * 模态框模块
 *
 * 从 main.js 提取，管理所有弹窗：showModal、存档菜单、银行操作、面试等。
 */

// [全系统自洽修复] 域F A类修复: 原 if(typeof _esc==="undefined"){ 包裹整个文件，若 _esc 已定义则所有弹窗函数不执行（P0级）
// 改为仅 _esc 函数受守卫，其余函数始终定义
if (typeof _esc === "undefined") {
  function _esc(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }
}

// ====== 兼容旧式 showModal(title, desc, buttons) 签名 ======
function showModal() {
  var args = arguments;
  // 旧式: showModal(title, desc, buttons) — 3个字符串/数组参数
  if (
    args.length >= 2 &&
    typeof args[0] === "string" &&
    typeof args[1] === "string"
  ) {
    return showModalImpl({
      title: args[0],
      body: '<p style="line-height:1.7;">' + args[1] + "</p>",
      buttons: Array.isArray(args[2]) ? args[2] : [],
    });
  }
  // 新式: showModal({ title, body, buttons })
  return showModalImpl(args[0] || {});
}

// ====== 模态对话框实现 ======
function showModalImpl({ title, body, buttons = [] }) {
  // 先清理旧的 modal-overlay，避免叠加
  const oldOverlay = document.querySelector(".modal-overlay");
  if (oldOverlay) {
    try {
      document.body.removeChild(oldOverlay);
    } catch (e) {
      console.warn("移除旧弹窗失败:", e);
    }
  }

  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";

  const box = document.createElement("div");
  box.className = "modal-box";

  // 用安全方式构建 HTML，避免模板字符串注入问题
  const titleEl = document.createElement("h2");
  titleEl.textContent = title;
  box.appendChild(titleEl);

  const bodyDiv = document.createElement("div");
  bodyDiv.className = "modal-body";
  bodyDiv.style.cssText =
    "margin:12px 0;font-size:13px;line-height:1.7;color:var(--text-primary);";
  bodyDiv.innerHTML = body; // body 是纯 HTML 字符串，安全
  box.appendChild(bodyDiv);

  const actionsDiv = document.createElement("div");
  actionsDiv.className = "modal-actions";
  for (const btn of buttons) {
    const btnEl = document.createElement("button");
    btnEl.className = "btn " + (btn.cls || "btn-primary");
    btnEl.textContent = btn.text;
    // 确保按钮文字始终可见（防止 CSS 覆盖）
    if (btn.cls && btn.cls.includes("btn-primary")) {
      btnEl.style.color = "#fff";
    } else if (btn.cls && btn.cls.includes("btn-secondary")) {
      btnEl.style.color = "var(--text-primary)";
    }
    if (btn._disabled) {
      btnEl.disabled = true;
      btnEl.setAttribute("aria-disabled", "true");
      btnEl.title = btn.disabledReason || "当前条件不足";
    }
    btnEl.addEventListener("click", function (e) {
      e.preventDefault();
      if (btn._disabled) return;
      // 先调用回调，让回调有机会读取弹窗中的元素
      var shouldClose = true;
      if (btn.callback) {
        var ret = btn.callback();
        // 如果回调返回 false，不关闭弹窗
        if (ret === false) {
          shouldClose = false;
        }
      }
      // 默认关闭弹窗（除非回调返回 false）
      if (shouldClose) {
        try {
          if (overlay.parentNode) {
            // [全系统自洽修复] 域F A类修复: 按钮关闭时同步移除ESC监听器，防止内存泄漏
            if (overlay._escHandler) {
              document.removeEventListener("keydown", overlay._escHandler);
            }
            overlay.parentNode.removeChild(overlay);
          }
        } catch (err) {
          // 忽略
        }
      }
    });
    actionsDiv.appendChild(btnEl);
  }
  box.appendChild(actionsDiv);

  overlay.appendChild(box);
  // 所有弹窗必须点击按钮关闭，不允许点击外部关闭
  // [全系统自洽修复] 域F 修复:点击遮罩时给抖动反馈，避免用户以为按钮死了
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) {
      overlay.style.transition = "background 0.15s";
      overlay.style.background = "rgba(0,0,0,0.55)";
      setTimeout(function () {
        overlay.style.background = "";
      }, 200);
    }
  });
  // [全系统自洽修复] 域F 修复:ESC键关闭弹窗，提升桌面端可用性
  // [全系统自洽修复] 域F A类修复: 保存handler引用以便按钮关闭时移除，防止内存泄漏
  var _modalEscHandler = function (e) {
    if (e.key === "Escape" && document.body.contains(overlay)) {
      try {
        if (overlay.parentNode) {
          overlay.parentNode.removeChild(overlay);
        }
      } catch (err) {
        // ignore
      }
      document.removeEventListener("keydown", _modalEscHandler);
    }
  };
  document.addEventListener("keydown", _modalEscHandler);
  // 保存引用到 overlay 上，供按钮关闭时同步移除
  overlay._escHandler = _modalEscHandler;
  document.body.appendChild(overlay);
}

