/** 每日检查动态提示，触发后标记防重复 */
function checkDynamicHints(state) {
  for (var i = 0; i < DYNAMIC_HINTS.length; i++) {
    var hint = DYNAMIC_HINTS[i];
    try {
      if (hint.trigger(state)) {
        state.flags["_hint_" + hint.id] = true;
        StateManager.addMessage(hint.message, "hint");
      }
    } catch (e) {
      /* 防止单条hint出错影响全局 */
    }
  }
}

// 全局挂载
if (typeof window !== "undefined") {
  Object.assign(window, {
    startTutorial,
    isTutorialDone,
    markTutorialDone,
    resetTutorial,
    showTutorialStep,
    highlightElement,
    cleanupHighlight,
    TUTORIAL_KEY,
    DYNAMIC_HINTS,
    checkDynamicHints,
    SCENARIO_TUTORIAL_STEPS,
  });
}

;
// ==== js/ui/navigation.js ====
/**
 * 全游戏统一导航系统 (v1.0)
 *
 * 集中管理所有跳转逻辑，提供统一的 navigateTo API：
 *   - Tab 切换
 *   - 地点旅行（含行动力/金钱消耗确认）
 *   - 百科条目跳转
 *   - 子Tab导航
 *   - 跨系统上下文导航
 *
 * 设计参照：《城市：天际线》右键菜单跳转 / 《Papers Please》弹窗确认 / 《大多数》UI流畅性
 *
 * 用法：
 *   navigateTo(state, { type: 'tab', name: 'actions' })
 *   navigateTo(state, { type: 'location', key: 'school', ap: 12 })
 *   navigateTo(state, { type: 'wiki', cat: 'locations', entry: 'school' })
 *   navigateTo(state, { type: 'subTab', tab: 'personal_growth', subTab: 'pg_edu' })
 */

// ================================================================
//  导航目标类型
// ================================================================
var NAV_TYPES = {
  TAB: "tab",
  LOCATION: "location",
  WIKI: "wiki",
  SUB_TAB: "subTab",
  ACTION: "action",
  WIKI_LIST: "wikiList",
};

// ================================================================
//  统一导航入口
// ================================================================

/**
 * 统一导航入口 — 所有跳转最终都走向这里
 *
 * @param {Object} state       当前游戏状态
 * @param {Object} target      导航目标
 * @param {string} target.type  导航类型：'tab' | 'location' | 'wiki' | 'subTab' | 'action'
 * @param {string} target.name  目标 Tab 名（type='tab' 或 type='subTab' 时）
 * @param {string} target.key   目标地点 key（type='location' 时）
 * @param {string} target.cat   百科分类（type='wiki' 时）
 * @param {string} target.entry 百科条目 ID（type='wiki' 时）
 * @param {string} target.subTab 子Tab ID（type='subTab' 时）
 * @param {string} target.actionId 行动 ID（type='action' 时）
 * @param {Object} [options]    可选参数
 * @param {string} [options.title]        确认弹窗标题（覆盖默认）
 * @param {string} [options.body]         确认弹窗内容（覆盖默认）
 * @param {number} [options.apCost]       AP 消耗（覆盖自动计算）
 * @param {number} [options.cashCost]     ¥ 消耗（覆盖自动计算）
 * @param {boolean} [options.skipConfirm] 跳过确认弹窗
 * @param {string} [options.confirmText]  确认按钮文字（默认"出发"）
 * @param {string} [options.cancelText]   取消按钮文字（默认"算了"）
 * @param {Function} [options.onComplete] 导航完成回调
 * @param {Function} [options.onCancel]   取消回调
 * @returns {boolean} 成功发起了导航（不是"已完成"，弹窗确认后才会真正完成）
 */
function navigateTo(state, target, options) {
  if (!state)
    state =
      typeof StateManager !== "undefined" ? StateManager.getState() : null;
  if (!state) {
    console.warn("[Nav] 无法导航：无游戏状态");
    return false;
  }
  options = options || {};

  // ---- 1. 检查目标是否可达 ----
  var check = _navCheck(state, target);
  if (!check.valid) {
    if (typeof StateManager !== "undefined" && check.message) {
      StateManager.addMessage("🚫 " + check.message, "warning");
    }
    if (options.onCancel) options.onCancel();
    return false;
  }

  // ---- 2. 是否需要确认弹窗 ----
  var apCost =
    options.apCost !== undefined ? options.apCost : check.apCost || 0;
  var cashCost =
    options.cashCost !== undefined ? options.cashCost : check.cashCost || 0;
  var hasCost = apCost > 0 || cashCost > 0;
  var skipConfirm = options.skipConfirm === true || !hasCost;

  // ---- 3. 检查资源是否充足 ----
  if (apCost > 0 && state.player && (state.player.actionPoints || 0) < apCost) {
    if (typeof StateManager !== "undefined") {
      StateManager.addMessage(
        "⚠️ 行动力不足（需要 " +
          apCost +
          "，当前 " +
          Math.floor(state.player.actionPoints || 0) +
          "）",
        "warning",
      );
    }
    if (options.onCancel) options.onCancel();
    return false;
  }
  if (
    cashCost > 0 &&
    state.resources &&
    (state.resources.cash || 0) < cashCost
  ) {
    if (typeof StateManager !== "undefined") {
      StateManager.addMessage(
        "💸 现金不足（需要 ¥" +
          cashCost +
          "，当前 ¥" +
          Math.floor(state.resources.cash || 0) +
          "）",
        "warning",
      );
    }
    if (options.onCancel) options.onCancel();
    return false;
  }

  // ---- 4. 执行导航（免确认时直接走，需确认时弹窗）----
  // 将计算好的消耗写入 options，确保 _doNavigate 能正确扣费
  var navOptions = Object.assign({}, options, {
    apCost: apCost,
    cashCost: cashCost,
  });

  if (skipConfirm) {
    _doNavigate(state, target, navOptions);
    return true;
  }

  // ---- 需要确认弹窗 ----
  var title = options.title || check.title || "导航确认";
  var body = options.body || _buildConfirmBody(target, apCost, cashCost, check);
  var confirmText = options.confirmText || "✅ 出发";
  var cancelText = options.cancelText || "❌ 算了";

  if (typeof showModal === "function") {
    showModal({
      title: title,
      body: body,
      buttons: [
        {
          text: cancelText,
          cls: "btn-secondary",
          callback: function () {
            if (options.onCancel) options.onCancel();
            StateManager.addMessage("❌ 取消了行动", "hint");
          },
        },
        {
          text: confirmText,
          cls: "btn-primary",
          callback: function () {
            _doNavigate(state, target, navOptions);
          },
        },
      ],
    });
  } else {
    // fallback: 无弹窗支持时直接导航
    _doNavigate(state, target, navOptions);
  }
  return true;
}

// ================================================================
//  内部实现
// ================================================================

/**
 * 检查导航目标是否有效，返回可达性、消耗、描述信息
 */
function _navCheck(state, target) {
  var result = { valid: false, apCost: 0, cashCost: 0, title: "", message: "" };

  if (!target || !target.type) {
    result.message = "导航目标无效";
    return result;
  }

  switch (target.type) {
    case NAV_TYPES.TAB: {
      var tabName = target.name;
      // 检查 Tab 是否在 TAB_RENDERERS 中注册
      if (typeof TAB_RENDERERS !== "undefined" && !TAB_RENDERERS[tabName]) {
        result.message = "找不到 Tab：" + tabName;
        return result;
      }
      // v3.7 合并重构：5 个 Tab 全阶段常驻可见，不做阶段限制
      result.valid = true;
      result.title = "📋 切换到 " + (target.displayName || tabName);
      result.message = "";
      break;
    }
    case NAV_TYPES.LOCATION: {
      var locKey = target.key;
      if (typeof LOCATIONS === "undefined" || !LOCATIONS[locKey]) {
        result.message = "找不到地点：" + locKey;
        return result;
      }
      var curLoc = state.trade && state.trade.currentLocation;
      if (curLoc === locKey) {
        // 已在目标地点，无需旅行
        result.valid = true;
        result.apCost = 0;
        result.title = "📍 已在" + LOCATIONS[locKey].name;
        result.message = "";
        return result;
      }
      // 计算旅行消耗
      if (typeof getTravelApCost === "function") {
        result.apCost = getTravelApCost(curLoc, locKey, state);
      } else {
        result.apCost = 12; // 默认消耗
      }
      // 计算交通费用（取最低价）
      if (typeof getLocation === "function") {
        var hops =
          typeof getLocationHops === "function"
            ? getLocationHops(curLoc, locKey)
            : 1;
        if (hops <= 2) {
          result.cashCost = 3; // 共享单车
        } else {
          result.cashCost = 4; // 地铁
        }
      }
      result.valid = true;
      result.title = "🚶 前往 " + LOCATIONS[locKey].name;
      break;
    }
    case NAV_TYPES.WIKI: {
      var wCat = target.cat;
      var wEntry = target.entry;
      if (typeof WIKI_CATEGORIES !== "undefined") {
        var catFound = WIKI_CATEGORIES.some(function (c) {
          return c.id === wCat;
        });
        if (!catFound) {
          result.message = "找不到百科分类：" + wCat;
          return result;
        }
      }
      result.valid = true;
      result.title = "📖 百科：查看详情";
      result.apCost = 0;
      break;
    }
    case NAV_TYPES.SUB_TAB: {
      // 子Tab导航依赖于父Tab必须先可达
      if (target.tab) {
        var parentCheck = _navCheck(state, { type: "tab", name: target.tab });
        if (!parentCheck.valid) {
          result.message = "无法导航：" + parentCheck.message;
          return result;
        }
      }
      result.valid = true;
      result.title = "📋 打开 " + (target.displayName || target.subTab);
      break;
    }
    case NAV_TYPES.ACTION: {
      // 查找行动是否可用（不实际执行）
      if (typeof getAvailableActions === "function") {
        var allActions = getAvailableActions(state);
        var found = false;
        for (var i = 0; i < allActions.length; i++) {
          if (allActions[i].id === target.actionId && !allActions[i].disabled) {
            found = true;
            break;
          }
        }
        if (!found) {
          result.message =
            "行动不可用：" + (target.displayName || target.actionId);
          return result;
        }
      }
      result.valid = true;
      result.title = "⚡ 执行行动";
      break;
    }
    case NAV_TYPES.WIKI_LIST: {
      // 百科列表页（回到分类列表）
      result.valid = true;
      result.title = "📖 百科列表";
      break;
    }
    default:
      result.message = "未知导航类型：" + target.type;
  }

  return result;
}

/**
 * 构建确认弹窗内容
 */
function _buildConfirmBody(target, apCost, cashCost, check) {
  var parts = [];

  // 描述即将做什么
  switch (target.type) {
    case NAV_TYPES.TAB:
      parts.push(
        "📋 切换到 <strong>" +
          _navEsc(target.displayName || target.name) +
          "</strong> Tab",
      );
      break;
    case NAV_TYPES.LOCATION: {
      var locName =
        LOCATIONS && LOCATIONS[target.key]
          ? LOCATIONS[target.key].name
          : target.key;
      var curLoc = check.curLocName || "当前位置";
      parts.push(
        "🚶 从 <strong>" +
          _navEsc(curLoc) +
          "</strong> 前往 <strong>" +
          _navEsc(locName) +
          "</strong>",
      );
      // 显示地点简介
      if (LOCATIONS && LOCATIONS[target.key] && LOCATIONS[target.key].desc) {
        parts.push(
          '<div style="font-size:11px;color:var(--text-muted);margin-top:4px;">' +
            _navEsc(LOCATIONS[target.key].desc) +
            "</div>",
        );
      }
      // 显示该地点的服务标签
      if (typeof getLocationServiceBadges === "function") {
        var badges = getLocationServiceBadges(target.key);
        if (badges.length > 0) {
          var badgeHtml = badges
            .map(function (b) {
              return (
                '<span style="font-size:10px;padding:1px 5px;border-radius:3px;background:' +
                b.bg +
                ";color:" +
                b.color +
                ';">' +
                b.icon +
                _navEsc(b.label) +
                "</span>"
              );
            })
            .join(" ");
          parts.push(
            '<div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:3px;">' +
              badgeHtml +
              "</div>",
          );
        }
      }
      break;
    }
    case NAV_TYPES.WIKI: {
      var entryLabel = target.entry;
      var catLabel = target.cat;
      var catObj = null;
      if (typeof WIKI_CATEGORIES !== "undefined") {
        for (var i = 0; i < WIKI_CATEGORIES.length; i++) {
          if (WIKI_CATEGORIES[i].id === catLabel) {
            catObj = WIKI_CATEGORIES[i];
            break;
          }
        }
      }
      parts.push(
        "📖 查看百科 — <strong>" +
          (catObj ? catObj.icon + " " + catObj.name : _navEsc(catLabel)) +
          (entryLabel ? " / " + _navEsc(entryLabel) : "（列表）") +
          "</strong>",
      );
      parts.push(
        '<div style="font-size:11px;color:var(--text-muted);margin-top:4px;">查阅资料不需要消耗资源</div>',
      );
      break;
    }
    case NAV_TYPES.SUB_TAB:
      parts.push(
        "📋 打开 <strong>" +
          _navEsc(target.displayName || target.subTab) +
          "</strong>" +
          (target.tab ? "（在 " + _navEsc(target.tab) + " Tab 内）" : ""),
      );
      break;
    case NAV_TYPES.ACTION:
      parts.push(
        "⚡ 执行行动：<strong>" +
          _navEsc(target.displayName || target.actionId) +
          "</strong>",
      );
      break;
  }

  // 资源消耗汇总
  if (apCost > 0 || cashCost > 0) {
    var costParts = [];
    if (apCost > 0) costParts.push("⚡ 行动力 -" + apCost);
    if (cashCost > 0) costParts.push("💰 ¥" + cashCost);
    parts.push(
      '<div style="margin-top:8px;padding:6px 10px;background:rgba(255,193,7,0.08);border:1px solid rgba(255,193,7,0.2);border-radius:6px;font-size:12px;color:var(--warning);">' +
        "消耗：<strong>" +
        costParts.join(" · ") +
        "</strong>" +
        "</div>",
    );
  }

  return '<div style="line-height:1.6;">' + parts.join("<br>") + "</div>";
}

/**
 * 实际执行导航
 */
function _doNavigate(state, target, options) {
  options = options || {};

  switch (target.type) {
    case NAV_TYPES.TAB: {
      var tabName = target.name;
      if (typeof switchTab === "function") {
        switchTab(tabName);
      } else {
        // fallback
        if (typeof currentTab !== "undefined") currentTab = tabName;
        if (typeof renderAll === "function") renderAll();
      }
      break;
    }

    case NAV_TYPES.LOCATION: {
      var locKey = target.key;
      var curLoc = state.trade && state.trade.currentLocation;
      if (curLoc === locKey) {
        // 已在该地点，切换到指定Tab或地图Tab
        var alreadyHereTab = target.navTab || "city";
        if (typeof switchTab === "function") switchTab(alreadyHereTab);
        StateManager.addMessage(
          "📍 已在" + (LOCATIONS[locKey] ? LOCATIONS[locKey].name : locKey),
          "info",
        );
        break;
      }

      // 扣减资源
      var apCost = options.apCost !== undefined ? options.apCost : 0;
      var cashCost = options.cashCost !== undefined ? options.cashCost : 0;
      if (apCost > 0 && state.player) {
        state.player.actionPoints = Math.max(
          0,
          (state.player.actionPoints || 0) - apCost,
        );
      }
      if (cashCost > 0 && state.resources) {
        state.resources.cash = Math.max(
          0,
          (state.resources.cash || 0) - cashCost,
        );
      }

      // 更新位置
      StateManager.update("trade.currentLocation", locKey);

      // 触发到达事件
      if (typeof triggerOnArrivalEvents === "function") {
        try {
          triggerOnArrivalEvents(locKey, state);
        } catch (e) {
          /* ignore */
        }
      }
      if (typeof rollNpcEncounterOnArrival === "function") {
        try {
          rollNpcEncounterOnArrival(locKey, state);
        } catch (e) {
          /* ignore */
        }
      }

      // 记录访问
      if (typeof recordLocationVisit === "function") {
        try {
          recordLocationVisit(state, locKey);
        } catch (e) {
          /* ignore */
        }
      }

      var locName =
        LOCATIONS && LOCATIONS[locKey] ? LOCATIONS[locKey].name : locKey;
      var costParts = [];
      if (apCost > 0) costParts.push("⚡ -" + apCost + " 行动力");
      if (cashCost > 0) costParts.push("💰 -¥" + cashCost);
      var costNote = costParts.length ? "（" + costParts.join("，") + "）" : "";
      StateManager.addMessage(
        "🚶 你来到了" + locName + "。" + costNote,
        "info",
      );

      // 到达后导航到指定Tab（默认行动Tab，可传target.navTab覆盖）
      var postNavTab = target.navTab || "actions";
      // 同时设置子Tab（用于培训中心等场景）：到达后切换到"我→技能"而非固定Tab
      if (target.subTab) {
        if (postNavTab === "me") {
          state._meSubTab = target.subTab;
        } else if (postNavTab === "career") {
          state._careerTabSubTab = target.subTab;
        } else if (postNavTab === "city") {
          state._citySubTab = target.subTab;
        }
      }
      if (typeof switchTab === "function") switchTab(postNavTab);
      else if (typeof renderAll === "function") renderAll();
      break;
    }

    case NAV_TYPES.WIKI: {
      if (typeof wikiNavigate === "function") {
        wikiNavigate(target.cat, target.entry || null);
      } else {
        if (typeof switchTab === "function") switchTab("wiki");
        else if (typeof renderAll === "function") renderAll();
      }
      break;
    }

    case NAV_TYPES.WIKI_LIST: {
      if (typeof _wikiBackToList === "function") {
        _wikiBackToList();
      } else {
        if (typeof switchTab === "function") switchTab("wiki");
        else if (typeof renderAll === "function") renderAll();
      }
      break;
    }

    case NAV_TYPES.SUB_TAB: {
      // 先切换到父Tab，再设置子Tab状态
      if (target.tab) {
        // 设置子Tab状态
        var subTabKey = "_" + target.tab.replace(/-/g, "_") + "SubTab";
        // v3.7 合并重构：旧 tab 名映射到新 tab
        var parentTab = target.tab;
        if (parentTab === "personal_growth") {
          parentTab = "me";
          state._meSubTab = target.subTab;
        } else if (parentTab === "career_dev") {
          parentTab = "career";
          state._careerTabSubTab = target.subTab;
        } else if (parentTab === "me") {
          state._meSubTab = target.subTab;
        } else if (parentTab === "career") {
          state._careerTabSubTab = target.subTab;
        } else {
          state[subTabKey] = target.subTab;
        }
        // 切换到父Tab
        if (typeof switchTab === "function") {
          switchTab(parentTab);
        } else {
          if (typeof currentTab !== "undefined") currentTab = parentTab;
          if (typeof renderAll === "function") renderAll();
        }
      }
      break;
    }

    case NAV_TYPES.ACTION: {
      // 查找并执行行动
      if (typeof getAvailableActions === "function") {
        var allActions = getAvailableActions(state);
        for (var i = 0; i < allActions.length; i++) {
          if (allActions[i].id === target.actionId && !allActions[i].disabled) {
            if (typeof allActions[i].handler === "function") {
              allActions[i].handler();
              if (typeof renderAll === "function") renderAll();
            }
            break;
          }
        }
      }
      break;
    }
  }

  // 完成回调
  if (options.onComplete) options.onComplete();
}

/**
 * 安全转义 HTML
 */
function _navEsc(s) {
  if (s === undefined || s === null) return "";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// ================================================================
//  快捷导航函数（常用场景）
// ================================================================

/**
 * 一键导航到指定 Tab
 * @param {string} tabName - Tab 名称
 */
function navToTab(tabName) {
  var state =
    typeof StateManager !== "undefined" ? StateManager.getState() : null;
  if (!state) {
    if (typeof switchTab === "function") {
      switchTab(tabName);
    }
    return;
  }
  navigateTo(
    state,
    { type: "tab", name: tabName, displayName: _tabDisplayName(tabName) },
    { skipConfirm: true },
  );
}

/**
 * 一键前往某个地点（带消耗确认）
 * @param {string} locKey    - 地点 key
 * @param {Object} [opts]    - 可选参数
 */
function navToLocation(locKey, opts) {
  opts = opts || {};
  var state =
    typeof StateManager !== "undefined" ? StateManager.getState() : null;
  if (!state) {
    StateManager.addMessage("⚠️ 无法导航：游戏未加载", "warning");
    return;
  }
  var loc =
    typeof LOCATIONS !== "undefined" && LOCATIONS[locKey]
      ? LOCATIONS[locKey]
      : null;
  navigateTo(
    state,
    {
      type: "location",
      key: locKey,
      displayName: loc ? loc.name : locKey,
    },
    {
      skipConfirm: opts.skipConfirm || false,
      title: opts.title,
      onComplete: opts.onComplete,
      onCancel: opts.onCancel,
    },
  );
}

/**
 * 一键导航到百科
 * @param {string} catId   - 百科分类
 * @param {string} entryId - 条目 ID（可选）
 */
function navToWiki(catId, entryId) {
  var state =
    typeof StateManager !== "undefined" ? StateManager.getState() : null;
  navigateTo(
    state,
    {
      type: "wiki",
      cat: catId,
      entry: entryId || null,
    },
    { skipConfirm: true },
  );
}

/**
 * 一键导航到个人成长Tab的学历子面板
 */
function navToEducation() {
  var state =
    typeof StateManager !== "undefined" ? StateManager.getState() : null;
  navigateTo(
    state,
    {
      type: "subTab",
      tab: "me",
      subTab: "me_growth",
      displayName: "🎓 学历",
    },
    { skipConfirm: true },
  );
}

/**
 * 一键前往大学城（并切换到行动Tab）
 */
function navToUniversity() {
  var state =
    typeof StateManager !== "undefined" ? StateManager.getState() : null;
  if (!state) return;
  var curLoc = state.trade && state.trade.currentLocation;
  if (curLoc === "school") {
    // 已在大学城，直接切换到行动Tab让用户看到备考按钮
    navToTab("actions");
    StateManager.addMessage("📍 你已在大学城，可以开始备考了", "info");
    return;
  }
  // 需要前往大学城
  navToLocation("school", {
    skipConfirm: false,
    title: "🎓 去大学城备考",
    onComplete: function () {
      // 到达后自动切换到行动Tab
      setTimeout(function () {
        navToTab("actions");
      }, 100);
    },
  });
}

/**
 * Tab名中文显示
 */
function _tabDisplayName(tabName) {
  var names = {
    actions: "⚡ 行动",
    city: "🗺️ 城市",
    me: "👤 我",
    career: "💼 事业",
    wiki: "📖 百科",
  };
  return names[tabName] || tabName;
}

// ================================================================
//  导航链接生成器（用于在各种界面生成可点击的导航链接）
// ================================================================

/**
 * 生成导航链接 HTML（点击后弹出确认弹窗）
 *
 * @param {Object} target - 导航目标（同 navigateTo 的 target）
 * @param {string} label  - 链接显示文字
 * @param {Object} [opts] - 选项
 * @param {boolean} [opts.inline] - 内联显示（不加额外的容器样式）
 * @returns {string} HTML 字符串
 *
 * 用法：
 *   navLink({ type: 'location', key: 'school' }, '📚 去大学城')
 *   navLink({ type: 'tab', name: 'inventory' }, '🎒 查看背包')
 *   navLink({ type: 'wiki', cat: 'jobs', entry: 'programmer' }, '💻 查看程序员工作')
 *   navLink({ type: 'subTab', tab: 'personal_growth', subTab: 'pg_edu' }, '🎓 查看学历')
 */
function navLink(target, label, opts) {
  opts = opts || {};
  var extraAttrs = "";
  if (opts.inline) {
    extraAttrs =
      ' style="display:inline;padding:0;background:none;border:none;color:var(--accent);cursor:pointer;text-decoration:underline;font-size:inherit;"';
  }
  return (
    '<button class="nav-link-btn" data-nav-type="' +
    _navEsc(target.type) +
    "\" data-nav-target='" +
    _navEsc(JSON.stringify(target)) +
    "'" +
    extraAttrs +
    ">" +
    _navEsc(label) +
    "</button>"
  );
}

/**
 * 导航链接点击绑定（在 DOM 更新后调用）
 * 查找所有 .nav-link-btn 并绑定点击事件
 */
function bindNavLinks() {
  var btns = document.querySelectorAll(".nav-link-btn");
  for (var i = 0; i < btns.length; i++) {
    (function (btn) {
      // 避免重复绑定
      if (btn.dataset._navBound) return;
      btn.dataset._navBound = "1";
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var navType = btn.dataset.navType;
        var navTarget = null;
        try {
          navTarget = JSON.parse(btn.dataset.navTarget);
        } catch (err) {
          StateManager.addMessage("⚠️ 导航链接解析失败", "warning");
          return;
        }
        if (navTarget) {
          navTarget.type = navType; // 确保 type 一致
          var state =
            typeof StateManager !== "undefined"
              ? StateManager.getState()
              : null;
          navigateTo(state, navTarget);
        }
      });
    })(btns[i]);
  }
}

// ================================================================
//  Tab 按钮事件绑定 — 修复核心 Bug
// ================================================================

/**
 * 绑定 Tab 按钮点击事件
 * 在游戏启动后调用一次即可，之后 renderTabBar 只管理显示
 *
 * 修复：原代码中 tab-btn 没有 click 事件处理函数
 */
function initTabNavigation() {
  var tabBar = document.getElementById("tab-bar");
  if (!tabBar) return;

  // 使用事件委托（更可靠，也能处理动态添加的按钮）
  if (!tabBar.dataset._navInit) {
    tabBar.dataset._navInit = "1";
    tabBar.addEventListener("click", function (e) {
      var btn = e.target.closest(".tab-btn");
      if (!btn) return;
      var tabName = btn.dataset.tab;
      if (!tabName) return;

      // 检查是否被禁用（v3.7 合并后所有 Tab 常驻可见）
      if (btn.style.display === "none") {
        StateManager.addMessage("⛔ 该 Tab 当前不可用", "warning");
        return;
      }

      // [全系统自洽修复] 域F A类修复: 删除死代码 — v3.7合并后 corp/trade Tab 已不存在

      // 执行 Tab 切换
      if (typeof switchTab === "function") {
        switchTab(tabName);
      } else if (typeof currentTab !== "undefined") {
        currentTab = tabName;
        if (typeof renderAll === "function") renderAll();
      }
    });
  }
}

// ================================================================
//  从 wiki-link 跳转到游戏内位置
// ================================================================

/**
 * 在百科条目详情中添加"前往实地"按钮
 * 返回一个导航到游戏地点/Tab的按钮 HTML
 *
 * @param {string} destType  - 目标类型 ('location' | 'tab' | 'wiki')
 * @param {string} destKey   - 目标 key
 * @param {string} label     - 按钮文字
 * @param {Object} [opts]    - 选项
 * @returns {string} HTML
 */
function navActionButton(destType, destKey, label, opts) {
  opts = opts || {};
  var target = { type: destType, key: destKey, name: destKey };
  if (destType === "wiki") {
    target = {
      type: "wiki",
      cat: destKey,
      entry: opts.entry || null,
      displayName: label,
    };
  } else if (destType === "tab") {
    target = { type: "tab", name: destKey, displayName: label };
  } else if (destType === "subTab") {
    // destKey = subTab id, opts.tab = parent tab name
    target = {
      type: "subTab",
      subTab: destKey,
      tab: opts.tab || "me",
      displayName: label,
    };
  } else if (destType === "location") {
    target = { type: "location", key: destKey, displayName: label };
    if (opts.navTab) target.navTab = opts.navTab;
    if (opts.subTab) target.subTab = opts.subTab; // 到达后设置子Tab
  }
  return (
    '<button class="btn btn-sm nav-action-btn" style="margin:2px 4px;min-height:36px;" ' +
    'data-nav-type="' +
    _navEsc(destType) +
    '" ' +
    "data-nav-target='" +
    _navEsc(JSON.stringify(target)) +
    "' " +
    ">" +
    _navEsc(label) +
    "</button>"
  );
}

/**
 * 绑定所有导航按钮（nav-link-btn + nav-action-btn）
 * 每次 renderAll 后调用
 */
function bindAllNavButtons() {
  bindNavLinks();

  // 绑定 nav-action-btn
  var actionBtns = document.querySelectorAll(".nav-action-btn");
  for (var i = 0; i < actionBtns.length; i++) {
    (function (btn) {
      if (btn.dataset._navBound) return;
      btn.dataset._navBound = "1";
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var navTarget = null;
        try {
          navTarget = JSON.parse(btn.dataset.navTarget);
        } catch (err) {
          return;
        }
        if (navTarget) {
          var state =
            typeof StateManager !== "undefined"
              ? StateManager.getState()
              : null;
          navigateTo(state, navTarget);
        }
      });
    })(actionBtns[i]);
  }
}

// ================================================================
//  辅助：渲染导航按钮分类区（用于提示框/卡片底部）
// ================================================================

/**
 * 生成一个"快速跳转"区域 HTML
 * @param {Array} links - 导航链接配置 [{ target: {...}, label: '...' }, ...]
 * @returns {string} HTML
 */
function navQuickLinks(links) {
  if (!links || links.length === 0) return "";
  var html =
    '<div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--border);">' +
    '<div style="font-size:10px;color:var(--text-muted);margin-bottom:4px;">🔗 快速跳转</div>' +
    '<div style="display:flex;flex-wrap:wrap;gap:4px;">';
  for (var i = 0; i < links.length; i++) {
    var l = links[i];
    html += navLink(l.target, l.label, { inline: true });
  }
  html += "</div></div>";
  return html;
}

// ================================================================
//  自动初始化
// ================================================================

// 页面加载完成后自动绑定 Tab 按钮
if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      initTabNavigation();
    });
  } else {
    // 已经加载完成
    initTabNavigation();
  }
}

// 也暴露一个延迟初始化（供 main.js 在游戏启动后调用）
window._navEnsureInit = function () {
  initTabNavigation();
};

;
// ==== js/ui/daily_focus.js ====
/**
 * 今日重点（Daily Focus）— P0 改进 #1
 *
 * 问题：玩家面对 35+ 街头工作、6 行业投资、20+ 标签界面，
 *   每日开局有"决策瘫痪"。Hermes 评估指出"信息层级过载（D）"。
 *
 * 设计参考：
 * - 《大多数》"今日目标"区块（侧边栏黄色挂条）
 * - BitLife "Top Recommendations"
 * - This War of Mine 早晨清单
 *
 * 实现：基于 state 推断 1-3 条"今日最该做"，渲染到 #daily-focus-section
 *   每条 ≤ 14 字，单 emoji 起头；点击关闭则当日不再显示。
 *
 * 规则采用"加权评分 → 取前 3"算法：
 *   1) 紧急健康/疲劳/食物 (权重 100)
 *   2) 紧急债务到期      (权重 90)
 *   3) 装备临近报废      (权重 70)
 *   4) 当前可领的成就    (权重 50)
 *   5) 行业热度异常机会  (权重 40)
 *   6) 节日抢钱窗口      (权重 30)
 *   7) 梦想里程碑接近    (权重 20)
 */

(function () {
  function _fmt(text) {
    return text;
  }

  function _collectCandidates(state) {
    var out = [];
    var p = state.player || {};
    var n = state.needs || {};
    var r = state.resources || {};
    var s = state.status || {};

    // 健康危机
    if ((s.health || 100) < 35) {
      out.push({
        w: 100,
        icon: "🚑",
        text: "去医院或药店看病",
        hint: "健康<35，再低会昏迷",
      });
    }
    if ((n.hunger || 100) < 30) {
      out.push({
        w: 95,
        icon: "🍜",
        text: "买饭吃，别饿着",
        hint: "饥饿过低损耗体力",
      });
    }
    if ((n.fatigue || 0) > 80) {
      out.push({
        w: 92,
        icon: "🛏️",
        text: "回家睡一觉",
        hint: "疲劳过高效率折半",
      });
    }
    if ((n.happiness || 50) < 20) {
      out.push({
        w: 88,
        icon: "🎮",
        text: "找件开心的事做",
        hint: "心情过低会触发心理事件",
      });
    }

    // 债务紧迫
    var vd = r.villageDebt || 0;
    if (vd > 0) {
      var vi = r.villageDebtInterest || 0;
      if (vi > 0 && vd > 3000 && p.day && p.day > 30) {
        var rateHint = "利息复利越滚越大";
        if (typeof window !== "undefined" && window.EconomySystem) {
          var _ta = (r.cash || 0) + (r.bankBalance || 0);
          var _dr = window.EconomySystem.getDynamicLoanRate(_ta) * 100;
          rateHint = "日息" + _dr.toFixed(2) + "%复利，尽快还清";
        }
        out.push({
          w: 90,
          icon: "🏘️",
          text: "尽快还村长一些钱",
          hint: rateHint,
        });
      } else if (vd > 0 && p.day && p.day > 80) {
        out.push({
          w: 60,
          icon: "🏘️",
          text: "找时间还村长债",
          hint: "拖太久会被催债事件",
        });
      }
    }

    // 装备耐久
    var equipped = (state.inventory && state.inventory.equipment) || {};
    Object.keys(equipped).forEach(function (slot) {
      var inst =
        typeof getEquippedInstance === "function"
          ? getEquippedInstance(state, slot)
          : null;
      if (
        !inst ||
        typeof inst.durability !== "number" ||
        typeof inst.maxDurability !== "number" ||
        inst.maxDurability <= 0
      )
        return;
      var pct = inst.durability / inst.maxDurability;
      if (pct < 0.2) {
        out.push({
          w: 70,
          icon: "🔧",
          text: "修一下装备别报废",
          hint:
            (inst.itemId || slot) + " 耐久仅 " + Math.round(pct * 100) + "%",
        });
      }
    });

    // 节日抢钱
    if (typeof getActiveFestival === "function") {
      try {
        var fes = getActiveFestival(state);
        if (fes && fes.id) {
          out.push({
            w: 30,
            icon: "🎊",
            text: "节日窗口：摆摊好时机",
            hint: fes.name + " 期间客流暴增",
          });
        }
      } catch (e) {
        /* ignore */
      }
    }

    // 行业热度异常
    if (typeof getSectorHeat === "function") {
      var sectors = ["科技", "消费", "金融", "房地产", "医药", "新能源"];
      var hottest = null,
        coolest = null;
      for (var si = 0; si < sectors.length; si++) {
        var h = getSectorHeat(sectors[si]);
        if (h === undefined || h === null) continue;
        if (!hottest || h > hottest.h) hottest = { name: sectors[si], h: h };
        if (!coolest || h < coolest.h) coolest = { name: sectors[si], h: h };
      }
      if (hottest && hottest.h > 1.15) {
        out.push({
          w: 40,
          icon: "📈",
          text: hottest.name + "行业过热",
          hint: "可考虑投资该行业股",
        });
      }
      if (coolest && coolest.h < 0.85) {
        out.push({
          w: 35,
          icon: "📉",
          text: coolest.name + "在低位",
          hint: "或为抄底窗口",
        });
      }
    }

    // 梦想里程碑
    if (typeof getDreamProgress === "function" && p.day > 30) {
      try {
        var prog = getDreamProgress(state);
        if (prog >= 60 && prog < 100) {
          out.push({
            w: 20,
            icon: "🌟",
            text: "梦想进度 " + prog + "%",
            hint: "完成下一里程碑触发剧情",
          });
        }
      } catch (e) {
        /* ignore */
      }
    }

    // 学习/技能：极低核心属性预警
    if ((p.intelligence || 0) < 15 && p.day > 20) {
      out.push({
        w: 25,
        icon: "📚",
        text: "智力过低，考虑学习",
        hint: "图书馆/夜校提升智力",
      });
    }
    if ((p.physique || 0) < 15 && p.day > 20) {
      out.push({
        w: 25,
        icon: "💪",
        text: "体质过低，影响体力工作",
        hint: "公园锻炼或多吃肉",
      });
    }

    // 35岁危机预警（P1：中国本土化）
    if (p.phase === "street" && p.age >= 33 && p.age < 36) {
      out.push({
        w: 45,
        icon: "⏳",
        text: "接近35岁分水岭",
        hint: "现在还来得及转型/上岸",
      });
    }

    if (typeof getStoryChapterChecklist === "function") {
      try {
        var chapterGoals = getStoryChapterChecklist(state);
        for (var gi = 0; gi < chapterGoals.length; gi++) {
          var goal = chapterGoals[gi];
          if (!goal || goal.done) continue;
          out.push({
            w: 58 + (goal.weight || 0) / 10,
            icon: "\uD83D\uDCD6",
            text: goal.label,
            hint: goal.hint,
          });
        }
      } catch (e) {
        /* ignore */
      }
    }

    // NPC好感度进度
    if (p.day > 5 && state.relationships) {
      var lowRels = 0;
      for (var nk in state.relationships) {
        var r = state.relationships[nk];
        if (r && r.met && r.affinity < 60 && r.affinity > 10) lowRels++;
      }
      if (lowRels > 0) {
        out.push({
          w: 38,
          icon: "🤝",
          text: "NPC好感+" + lowRels + "人可提升",
          hint: "送礼聊天解锁推荐工作",
        });
      }
    }

    // 主动目标建议
    if (p.day > 3 && p.phase === "street") {
      if (state.housing && state.housing.tier === 0 && (r.cash || 0) < 500) {
        out.push({
          w: 35,
          icon: "🛏️",
          text: "攒¥500租床位",
          hint: "改善睡眠恢复行动力",
        });
      }
      var metNpcs = state.relationships
        ? Object.keys(state.relationships).filter(function (k) {
            return state.relationships[k].met;
          }).length
        : 0;
      if (metNpcs < 2) {
        out.push({
          w: 33,
          icon: "🤝",
          text: "认识更多NPC",
          hint: "NPC关系解锁高薪工作",
        });
      }
      if ((p.intelligence || 20) < 35 && p.day > 7) {
        out.push({
          w: 30,
          icon: "🧠",
          text: "去培训中心学习",
          hint: "智力提升可入职科技园",
        });
      }
    }

    // 企业阶段就绪度（street → corporate）
    if (p.phase === "street" && p.day > 15) {
      var intelPct = Math.min(
        100,
        Math.round(((p.intelligence || 20) / 45) * 100),
      );
      var expPct = Math.min(
        100,
        Math.round(
          ((p.day || 0) / 200) * 50 + ((r.totalEarned || 0) / 5000) * 50,
        ),
      );
      var ready =
        p.intelligence >= 45 || (p.day >= 200 && (r.totalEarned || 0) > 5000);
      if (!ready) {
        var best = Math.max(intelPct, expPct);
        if (best > 30) {
          out.push({
            w: 45 + Math.floor(best / 10),
            icon: "🏢",
            text: "企业就绪 " + best + "%",
            hint: "智力" + intelPct + "% | 经验" + expPct + "% → 去科技园",
          });
        }
      }
    }

    return out;
  }

  function getDailyFocus(state) {
    var cands = _collectCandidates(state);
    cands.sort(function (a, b) {
      return b.w - a.w;
    });
    return cands.slice(0, 3);
  }

  function renderDailyFocusSection(state) {
    var el = document.getElementById("daily-focus-section");
    if (!el) return;
    // 序章/欢迎页面或职场后期不显示
    if (
      !state.player ||
      state.player.phase !== "street" ||
      state.player.day < 2
    ) {
      el.style.display = "none";
      return;
    }
    // 玩家关闭过当天的提示
    if (
      state.flags &&
      state.flags._dailyFocusDismissedDay === state.player.day
    ) {
      el.style.display = "none";
      return;
    }
    var items = getDailyFocus(state);
    if (!items.length) {
      el.style.display = "none";
      return;
    }
    el.style.display = "";
    var html =
      '<h3 style="display:flex;justify-content:space-between;align-items:center;">' +
      "<span>📌 今日重点</span>" +
      '<button class="btn-mini" onclick="dismissDailyFocus()" title="今天不再显示" ' +
      'style="font-size:10px;padding:1px 5px;background:transparent;border:1px solid var(--border);' +
      'color:var(--text-muted);border-radius:3px;cursor:pointer;">✕</button>' +
      "</h3>";
    html +=
      '<div style="display:flex;flex-direction:column;gap:4px;font-size:11px;">';
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      html +=
        '<div style="padding:5px 7px;background:rgba(243,180,90,0.10);border-left:2px solid #d2964a;border-radius:3px;" title="' +
        (it.hint || "").replace(/"/g, "&quot;") +
        '">' +
        '<span style="font-size:13px;">' +
        it.icon +
        "</span> " +
        '<span style="color:var(--text-primary);">' +
        _fmt(it.text) +
        "</span>" +
        "</div>";
    }
    html += "</div>";
    el.innerHTML = html;
  }

  function dismissDailyFocus() {
    var st = StateManager.getState();
    if (!st.flags) st.flags = {};
    st.flags._dailyFocusDismissedDay = st.player.day;
    renderDailyFocusSection(st);
  }

  if (typeof window !== "undefined") {
    window.getDailyFocus = getDailyFocus;
    window.renderDailyFocusSection = renderDailyFocusSection;
    window.dismissDailyFocus = dismissDailyFocus;
  }
})();

