// ==== js/ui/life_memoir.js ====
/**
 * 人生回忆录系统（v3.6 P1-4）
 *
 * 8类回忆录：童年/求学/初恋/职场/创业/家庭/疾病/旅行
 * localStorage.__lifeMemoirs存储
 * 每类最多10条回忆
 *
 * 设计参考：BitLife人生回顾 / This War of Mine记忆片段
 */

(function () {
  // ====== 回忆录类别定义 ======
  const MEMOIR_CATEGORIES = {
    childhood: {
      id: "childhood",
      name: "童年",
      icon: "🧸",
      color: "var(--warning)",
    },
    education: {
      id: "education",
      name: "求学",
      icon: "📚",
      color: "var(--primary)",
    },
    love: {
      id: "love",
      name: "初恋",
      icon: "💕",
      color: "#e91e63",
    },
    career: {
      id: "career",
      name: "职场",
      icon: "🏢",
      color: "var(--info)",
    },
    startup: {
      id: "startup",
      name: "创业",
      icon: "🚀",
      color: "var(--success)",
    },
    family: {
      id: "family",
      name: "家庭",
      icon: "👨‍👩‍👧",
      color: "#9c27b0",
    },
    illness: {
      id: "illness",
      name: "疾病",
      icon: "🏥",
      color: "var(--danger)",
    },
    travel: {
      id: "travel",
      name: "旅行",
      icon: "✈️",
      color: "#00bcd4",
    },
  };

  const MAX_MEMOIRS_PER_CATEGORY = 10;
  const STORAGE_KEY = "__lifeMemoirs";

  /**
   * 获取所有回忆录
   * @returns {Object} 回忆录数据
   */
  function getMemoirs() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        return JSON.parse(raw);
      }
    } catch (e) {
      console.error("读取回忆录失败:", e);
    }
    return {};
  }

  /**
   * 保存回忆录
   * @param {Object} memoirs - 回忆录数据
   */
  function saveMemoirs(memoirs) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(memoirs));
    } catch (e) {
      console.error("保存回忆录失败:", e);
    }
  }

  /**
   * 添加回忆录
   * @param {string} category - 类别ID
   * @param {Object} memoir - 回忆录内容
   * @returns {boolean} 是否成功
   */
  function addMemoir(category, memoir) {
    const memoirs = getMemoirs();
    if (!memoirs[category]) {
      memoirs[category] = [];
    }

    // 检查是否超过上限
    if (memoirs[category].length >= MAX_MEMOIRS_PER_CATEGORY) {
      // 移除最早的
      memoirs[category].shift();
    }

    // 添加时间戳
    memoir.addedAt = Date.now();
    memoir.day =
      memoir.day ||
      (typeof StateManager !== "undefined"
        ? StateManager.getState().player.day
        : 0);

    memoirs[category].push(memoir);
    saveMemoirs(memoirs);
    return true;
  }

  /**
   * 获取某类别的回忆录
   * @param {string} category - 类别ID
   * @returns {Array} 回忆录列表
   */
  function getMemoirsByCategory(category) {
    const memoirs = getMemoirs();
    return memoirs[category] || [];
  }

  /**
   * 获取所有回忆录统计
   * @returns {Object} 统计信息
   */
  function getMemoirStats() {
    const memoirs = getMemoirs();
    const stats = {};
    let total = 0;
    for (let cat in MEMOIR_CATEGORIES) {
      const count = (memoirs[cat] || []).length;
      stats[cat] = count;
      total += count;
    }
    stats.total = total;
    return stats;
  }

  /**
   * 生成结局回忆录摘要
   * @param {Object} state - 游戏状态
   * @returns {string} 回忆录摘要
   */
  function generateEndingMemoir(state) {
    const stats = getMemoirStats();
    const day = state.player.day;
    const age = state.player.age;

    let summary = `📖 人生回忆录摘要\n`;
    summary += `─────────────────\n`;
    summary += `游戏天数：${day}天\n`;
    summary += `年龄：${age}岁\n`;
    summary += `记录片段：${stats.total}个\n\n`;

    for (let cat in MEMOIR_CATEGORIES) {
      const count = stats[cat];
      if (count > 0) {
        const icon = MEMOIR_CATEGORIES[cat].icon;
        const name = MEMOIR_CATEGORIES[cat].name;
        summary += `${icon} ${name}：${count}个片段\n`;
      }
    }

    return summary;
  }

  /**
   * 渲染回忆录查看弹窗
   * @param {Object} state - 游戏状态
   */
  function showMemoirModal(state) {
    if (typeof showModal !== "function") {
      console.warn("showModal未定义，无法打开回忆录弹窗");
      return;
    }

    const stats = getMemoirStats();
    const statsText = Object.entries(MEMOIR_CATEGORIES)
      .map(([cat, def]) => {
        const count = stats[cat] || 0;
        return `${def.icon} ${def.name}：${count}`;
      })
      .join(" · ");

    const content = document.createElement("div");
    content.innerHTML = `
      <div style="padding:12px;">
        <h4 style="margin-top:0;">📖 人生回忆录</h4>
        <p style="color:var(--text-muted);font-size:12px;">${statsText}</p>
        <div style="max-height:400px;overflow-y:auto;">
          ${Object.entries(MEMOIR_CATEGORIES)
            .map(([cat, def]) => {
              const memoirs = getMemoirsByCategory(cat);
              if (memoirs.length === 0) {
                return `<div style="padding:8px;color:var(--text-muted);font-size:12px;">${def.icon} ${def.name}：暂无记录</div>`;
              }
              return memoirs
                .slice(-5)
                .reverse()
                .map(
                  (m, i) => `
                  <div style="padding:8px;margin-bottom:4px;background:var(--bg-secondary);border-radius:4px;font-size:12px;">
                    <div style="color:${def.color};font-weight:bold;">${def.icon} ${m.title || "未命名"}</div>
                    <div style="color:var(--text-muted);">${m.content || m.desc || ""}</div>
                    <div style="font-size:10px;color:var(--text-muted);margin-top:4px;">第${m.day || "?"}天</div>
                  </div>
                `,
                )
                .join("");
            })
            .join("")}
        </div>
      </div>
    `;

    showModal("人生回忆录", content, "large");
  }

  /**
   * 自动记录关键事件
   * @param {string} category - 类别
   * @param {string} title - 标题
   * @param {string} content - 内容
   */
  function autoRecord(category, title, content) {
    if (!MEMOIR_CATEGORIES[category]) {
      console.warn("未知回忆录类别:", category);
      return;
    }
    addMemoir(category, {
      title,
      content,
      day:
        typeof StateManager !== "undefined"
          ? StateManager.getState().player.day
          : 0,
    });
  }

  // ====== 导出 ======
  if (typeof window !== "undefined") {
    window.MEMOIR_CATEGORIES = MEMOIR_CATEGORIES;
    window.lifeMemoir = {
      add: addMemoir,
      get: getMemoirsByCategory,
      getAll: getMemoirs,
      getStats: getMemoirStats,
      generateEnding: generateEndingMemoir,
      show: showMemoirModal,
      autoRecord: autoRecord,
      categories: MEMOIR_CATEGORIES,
      maxPerCategory: MAX_MEMOIRS_PER_CATEGORY,
      generateCityStory: generateCityStory,
    };
  }

  // ====== P3-1 城市故事生成 ======
  function generateCityStory(state) {
    if (!state) return "";
    var p = state.player || {};
    var s = state.status || {};
    var r = state.resources || {};
    var day = p.day || 1;
    var ribbon = "";
    var ribbonDesc = "";
    if (typeof determineLifeRibbon === "function") {
      var stats = typeof collectLifeStats === "function" ? collectLifeStats(state) : {};
      var rib = determineLifeRibbon(state, stats);
      if (rib) { ribbon = (rib.icon || "🌟") + " " + (rib.name || ""); ribbonDesc = rib.desc || ""; }
    }
    if (!ribbon) { ribbon = "🌆 城市过客"; ribbonDesc = "你在这座城市留下了自己的足迹。"; }
    var cash = r.cash || 0;
    var bank = r.bankBalance || 0;
    var totalAssets = cash + bank;
    var health = s.health || 0;
    var illnessCount = (s.illnesses || []).length;
    var fame = p.fame || 0;
    var morality = p.morality || 50;
    var phase = p.phase === "corporate" ? "🏢 职场人" : "🏘️ 街头打拼";
    var memoirStats = typeof getMemoirStats === "function" ? getMemoirStats() : {};
    var memoirCount = 0;
    for (var mk in memoirStats) memoirCount += memoirStats[mk] || 0;

    var html = '<div style="text-align:center;padding:8px;">';
    html += '<div style="font-size:48px;margin-bottom:8px;">🏙️</div>';
    html += '<h2 style="margin:4px 0;">你的城市故事</h2>';
    html += '<div style="font-size:18px;font-weight:bold;color:var(--accent);margin:8px 0;">' + ribbon + '</div>';
    html += '<div style="font-size:12px;color:var(--text-muted);margin-bottom:12px;">' + ribbonDesc + '</div>';
    html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;text-align:left;font-size:12px;">';
    html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">📅 存活 <strong>' + day + '</strong> 天</div>';
    html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">💰 总资产 <strong>¥' + totalAssets.toLocaleString() + '</strong></div>';
    html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">❤️ 最终健康 <strong>' + health + '</strong></div>';
    html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">' + phase + '</div>';
    if (fame > 0) html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">⭐ 名气 <strong>' + fame + '</strong></div>';
    if (illnessCount > 0) html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">🏥 患病 <strong>' + illnessCount + '</strong> 次</div>';
    if (morality >= 70) html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">😇 道德高尚</div>';
    else if (morality <= 30) html += '<div style="background:var(--bg-secondary);padding:8px;border-radius:6px;">😈 道德沦丧</div>';
    html += '</div>';
    html += '<div style="margin-top:12px;padding:10px;background:var(--bg-secondary);border-radius:8px;text-align:left;font-size:12px;line-height:1.6;">';
    html += '<strong>📜 人生轨迹</strong><br>';
    if (day < 30) html += '你在这座城市没能站稳脚跟，<strong>' + ribbon + '</strong>——一段短暂而深刻的经历。';
    else if (day < 100) html += '你在这座城市挣扎了近百天，最终<strong>' + ribbon + '</strong>。这段日子教会了你生存。';
    else if (day < 365) html += '你在这座城市坚持了近一年，从陌生到熟悉，最终<strong>' + ribbon + '</strong>。';
    else html += '你在这座城市扎根了整整' + Math.floor(day / 365) + '年，经历了风风雨雨，最终<strong>' + ribbon + '</strong>。你的故事成为了这座城市的一部分。';
    html += '</div>';
    html += '<button class="btn btn-sm" style="margin-top:12px;" onclick="alert(\'📋 请截图分享你的城市故事！\')">📸 分享</button>';
    html += '</div>';
    return html;
  }
})();

;
// ==== js/ui/victory.js ====
/**
 * 多种胜利路线系统
 *
 * 打破固定套路，提供5种不同的获胜方式：
 *   🏪 经商大亨 | ⭐ 城市名人 | 🎓 技能大师 | 💰 投资天才 | 🏢 职场巅峰 | 💵 财务自由
 */

/** 每日检查所有胜利路线 */
function checkVictoryPaths(state) {
  if (state.flags.gameOver || state.flags.victory) return;
  const inv = state.investment;

  // 🏪 经商大亨：累计交易利润 >= ¥500,000
  const totalProfit = state.trade?.totalProfit || 0;
  if (totalProfit >= 50000) {
    triggerVictory(
      state,
      "merchant",
      "🏪 经商大亨！",
      "你靠倒买倒卖积累了 ¥" +
        totalProfit.toLocaleString() +
        " 交易利润，成为城中传奇商人！",
    );
    return;
  }

  // ⭐ 城市名人：名气 >= 100 持续 10 天
  if (state.player.fame >= 100) {
    state.status.fameDays = (state.status.fameDays || 0) + 1;
    if (state.status.fameDays >= 10) {
      triggerVictory(
        state,
        "celebrity",
        "⭐ 城市名人！",
        "你的名气响彻全城，走到哪里都有人认出你。你成了这座城市的象征！",
      );
      return;
    }
  } else {
    state.status.fameDays = 0;
  }

  // 🎓 技能大师：全部10项技能达到80级
  const skillValues = Object.values(state.skills);
  if (
    skillValues.length >= 10 &&
    skillValues.every(function (s) {
      return s.level >= 80;
    })
  ) {
    triggerVictory(
      state,
      "master",
      "🎓 技能大师！",
      "十项全能，样样精通！任何工作在你手里都是大师级水准。",
    );
    return;
  }

  // 💰 投资天才：投资资产 >= ¥10,000,000
  var stockVal = 0;
  if (inv && inv.stockHoldings) {
    stockVal = inv.stockHoldings.reduce(function (s, h) {
      var mkt = inv.stockMarket ? inv.stockMarket[h.symbol] : null;
      return s + (mkt ? mkt.price : 0) * (h.shares || 0);
    }, 0);
  }
  var btcVal =
    (inv && inv.btcPrice ? inv.btcPrice : 0) *
    (inv && inv.btcHoldings ? inv.btcHoldings : 0);
  var propVal = (inv && inv.properties ? inv.properties : []).reduce(function (
    s,
    p,
  ) {
    return s + (p.currentPrice || p.buyPrice || 0);
  }, 0);
  var carVal = (inv && inv.cars ? inv.cars : []).reduce(function (s, c) {
    return s + (c.currentPrice || c.buyPrice || 0);
  }, 0);
  var totalInv = stockVal + btcVal + propVal + carVal;
  if (totalInv >= 1000000) {
    triggerVictory(
      state,
      "investor",
      "💰 投资天才！",
      "你的投资组合突破了千万大关！钱生钱，你已经掌握了财富密码。",
    );
    return;
  }

  // 🎓 学术大师（博士+多项研究成果）
  if (state.player.education >= 3 && (state.player.research || 0) >= 3) {
    triggerVictory(
      state,
      "academic_master",
      "🎓 学术大师！",
      "你读完博士并发表多项研究成果，在学术界赢得一席之地，桃李满天下！",
    );
    return;
  }

  // 🏠 中产稳稳（月薪>2万+有房产/产业+流动资金5万+）
  var _vcCurrentSalary =
    state.career && state.career.currentJob
      ? state.career.currentJob.salary || 0
      : 0;
  var _vcOwnsHouse =
    (state.housing && state.housing.tier >= 2) ||
    (state.investment && state.investment.properties
      ? state.investment.properties.length
      : 0) > 0;
  var _vcLiquid = state.resources.cash + (state.resources.bankBalance || 0);
  if (_vcCurrentSalary > 20000 && _vcOwnsHouse && _vcLiquid >= 50000) {
    triggerVictory(
      state,
      "middle_class",
      "🏠 中产稳稳！",
      "月入过万、有房有存款——你在这座城市扎下了根，日子平淡却踏实。",
    );
    return;
  }

  // 👨‍👩‍👧 幸福家庭（有配偶+子女已成年+家庭净资产为正）
  var _vcFam = state.family || {};
  if (_vcFam.spouse && _vcFam.children && _vcFam.children.length > 0) {
    var _vcAllGrown = _vcFam.children.every(function (c) {
      return (
        (c.age || 0) >= 18 || c.stage === "working" || c.stage === "graduated"
      );
    });
    if (_vcAllGrown) {
      triggerVictory(
        state,
        "happy_family",
        "👨‍👩‍👧 幸福家庭！",
        "子女长大成人，家庭美满——这是多少人奋斗一生的归宿。",
      );
      return;
    }
  }

  // 🛠️ 匠人一生（单项技能满级+证书>=5+同职业>=15年）
  var _vcHasMasterSkill = false;
  for (var _vcSk in state.skills) {
    if (state.skills[_vcSk] && state.skills[_vcSk].level >= 100) {
      _vcHasMasterSkill = true;
      break;
    }
  }
  var _vcCertLen = (state.certificates || []).length;
  var _vcJobYears =
    (state.career && state.career.currentJob
      ? state.career.currentJob.workDays || 0
      : 0) / 365;
  if (_vcHasMasterSkill && _vcCertLen >= 5 && _vcJobYears >= 15) {
    triggerVictory(
      state,
      "craftsman",
      "🛠️ 匠人一生！",
      "一件事做到极致。技能满级、证书齐全、三十年坚守——你就是传说中的大国工匠。",
    );
    return;
  }

  // 🏚️ 流浪终老（暗结局：35岁后+无房+赤贫+失业）
  var _vcAgeYear = state.player.day / 365;
  if (
    _vcAgeYear >= 35 &&
    (!state.housing || state.housing.tier === 0) &&
    state.resources.cash < 500 &&
    !state.career.currentJob
  ) {
    triggerVictory(
      state,
      "homeless",
      "🏚️ 流浪终老",
      "三十五岁后居无定所、身无分文。城市很大，却容不下一个你……",
    );
    return;
  }

  // 🏛️ 体制内消失（暗结局：公务员路径+15年未晋升）
  var _vcCurPath =
    state.career && state.career.currentJob
      ? state.career.currentJob.path || ""
      : "";
  if (
    (_vcCurPath.indexOf("gov") >= 0 || _vcCurPath.indexOf("civil") >= 0) &&
    _vcJobYears >= 15
  ) {
    var _vcHistory = (state.career.history || []).filter(function (h) {
      return (
        h.event &&
        (h.event.indexOf("晋升") >= 0 || h.event.indexOf("promo") >= 0)
      );
    });
    if (_vcHistory.length <= 1) {
      triggerVictory(
        state,
        "civil_servant",
        "🏛️ 体制内消失",
        "上岸十五年，原地踏步。你成了单位里那个「还在的老同志」。",
      );
      return;
    }
  }

  // 🏙️ 城市套牢（暗结局：房贷车贷占收入>80%持续5年+）
  var _vcMonthlyIncome = _vcCurrentSalary || 1;
  var _vcMonthlyDebt =
    (state.family && state.family.expenses
      ? state.family.expenses.monthlyMortgage || 0
      : 0) +
    (state.resources.bankDebt > 0
      ? Math.round(state.resources.bankDebt * 0.05)
      : 0);
  var _vcDebtRatio = _vcMonthlyDebt / _vcMonthlyIncome;
  if (_vcDebtRatio > 0.8 && _vcAgeYear >= 5) {
    triggerVictory(
      state,
      "city_trapped",
      "🏙️ 城市套牢",
      "收入的80%以上都给了银行。房子在，自由却没——这城市套住了你。",
    );
    return;
  }

  // 🏢 职场巅峰（保留原有逻辑）
  if (state.player.phase === "corporate" && state.corporate.rank === "P10") {
    triggerVictory(
      state,
      "p10",
      "🏆 登峰造极！",
      "你成功晋升到了P10合伙人级别，站在了职场金字塔的顶端！",
    );
    return;
  }

  // 💵 财务自由（保留原有 ¥20,000,000）
  if (state.resources.cash + (state.resources.bankBalance || 0) >= 2000000) {
    triggerVictory(
      state,
      "money",
      "💵 财务自由！",
      "你积累了2000万财富，实现了财务自由。不再为钱发愁的人生，开始了！",
    );
    return;
  }

  // 🌟 心灵大师（情绪状态极佳连续7天）
  if (state.status && state.status.emotionalState === "elated") {
    state.flags._elatedStreak = (state.flags._elatedStreak || 0) + 1;
    if (state.flags._elatedStreak >= 7) {
      triggerVictory(
        state,
        "zen_master",
        "🌟 心灵大师！",
        "连续7天保持极佳状态！你与自己达成了和解，没有什么能动摇你内心的平静与喜悦。",
      );
      return;
    }
  } else {
    state.flags._elatedStreak = 0;
  }
}

/** 触发胜利 */
function triggerVictory(state, type, title, desc) {
  state.flags.victory = true;
  state.flags.victoryType = type;
  state.flags.gameOver = true;
  state.flags.victoryTitle = title;
  state.flags.victoryDesc = desc;
  // v3.1：人生缎带判定
  if (typeof determineLifeRibbon === "function") {
    var result = determineLifeRibbon(state);
    state.flags._lifeRibbon = result.ribbon.id;
    state.flags._lifeRibbonName = result.ribbon.icon + " " + result.ribbon.name;
    if (typeof recordRibbon === "function") {
      var isNew = recordRibbon(result.ribbon.id, result.stats);
      if (isNew) {
        state.flags._newRibbonEarned = true;
      }
    }
  }
  // v3.6 P1-4: 生成人生回忆录摘要
  if (
    typeof lifeMemoir !== "undefined" &&
    typeof lifeMemoir.generateEnding === "function"
  ) {
    var memoirSummary = lifeMemoir.generateEnding(state);
    state.flags._memoirSummary = memoirSummary;
    // 记录到回忆录
    lifeMemoir.add("career", {
      title: "游戏结局",
      content: title + " - " + desc,
      day: state.player.day,
    });
  }
  // 记录公司命运到多周目记忆
  if (typeof recordPlaythroughEnd === "function") {
    recordPlaythroughEnd(state);
  }
  if (typeof showVictoryModal === "function") showVictoryModal();
}

// 全局挂载
if (typeof window !== "undefined") {
  Object.assign(window, {
    checkVictoryPaths: checkVictoryPaths,
    triggerVictory: triggerVictory,
  });
}

